  (71, 1, '', '[{"id":599,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"আমরা নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":600,"position":2,"text_uthmani":"أَرْسَلْنَا","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":601,"position":3,"text_uthmani":"نُوحًا","transliteration":"nūḥan","translation_bn":"নূহকে","root":"—","lemma":"نُوح","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":602,"position":4,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":603,"position":5,"text_uthmani":"قَوْمِهِۦٓ","transliteration":"qawmihi","translation_bn":"তার জাতির","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":604,"position":6,"text_uthmani":"أَنْ","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":605,"position":7,"text_uthmani":"أَنذِرْ","transliteration":"andhir","translation_bn":"\"তুমি সতর্ক কর","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":606,"position":8,"text_uthmani":"قَوْمَكَ","transliteration":"qawmaka","translation_bn":"তোমার জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":607,"position":9,"text_uthmani":"مِن","transliteration":"min","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":608,"position":10,"text_uthmani":"قَبْلِ","transliteration":"qabli","translation_bn":"পূর্বে","root":"قبل","lemma":"قَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":609,"position":11,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":610,"position":12,"text_uthmani":"يَأْتِيَهُمْ","transliteration":"yatiyahum","translation_bn":"তাদের উপর আসবে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":611,"position":13,"text_uthmani":"عَذَابٌ","transliteration":"ʿadhābun","translation_bn":"আযাব","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":612,"position":14,"text_uthmani":"أَلِيمٌۭ","transliteration":"alīmun","translation_bn":"কষ্টদায়ক\"","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":613,"position":15,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'innā arsalnā nūḥan ilā qawmihi an andhir qawmaka min qabli an yatiyahum ʿadhābun alīmun', 'আমি নূহকে তার জাতির কাছে পাঠিয়েছিলাম (এই নির্দেশ দিয়ে) যে, তুমি তোমার জাতিকে সতর্ক কর তাদের কাছে মর্মান্তিক ‘আযাব আসার পূর্বে।', 'Indeed, We sent Noah to his people, [saying], "Warn your people before there comes to them a painful punishment."', 'আমি নূহকে তার জাতির কাছে পাঠিয়েছিলাম (এই নির্দেশ দিয়ে) যে, তুমি তোমার জাতিকে সতর্ক কর তাদের কাছে মর্মান্তিক ‘আযাব আসার পূর্বে।', 'Indeed, We sent Noah to his people, [saying], "Warn your people before there comes to them a painful punishment."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071001.mp3', now()),
  (71, 2, '', '[{"id":1557,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"বলেছিল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1558,"position":2,"text_uthmani":"يَـٰقَوْمِ","transliteration":"yāqawmi","translation_bn":"\"আমার জাতি হে","root":"قوم","lemma":"قَوْم","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":1559,"position":3,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"আমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1560,"position":4,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"জন্যে তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":1561,"position":5,"text_uthmani":"نَذِيرٌۭ","transliteration":"nadhīrun","translation_bn":"সতর্ককারী","root":"نذر","lemma":"نَذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":1562,"position":6,"text_uthmani":"مُّبِينٌ","transliteration":"mubīnun","translation_bn":"সুস্পষ্ট","root":"بين","lemma":"مُّبِين","grammar_bn":"বিশেষণ (Adjective)"},{"id":1563,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'qāla yāqawmi innī lakum nadhīrun mubīnun', 'সে বলেছিল, ‘‘হে আমার জাতির লোকেরা! আমি তোমাদের জন্য এক সুস্পষ্ট সতর্ককারী,', 'He said, "O my people, indeed I am to you a clear warner,', 'সে বলেছিল, ‘‘হে আমার জাতির লোকেরা! আমি তোমাদের জন্য এক সুস্পষ্ট সতর্ককারী,', 'He said, "O my people, indeed I am to you a clear warner,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071002.mp3', now()),
  (71, 3, '', '[{"id":2587,"position":1,"text_uthmani":"أَنِ","transliteration":"ani","translation_bn":"যেন","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2588,"position":2,"text_uthmani":"ٱعْبُدُوا۟","transliteration":"uʿ''budū","translation_bn":"তোমরা এবাদত কর","root":"عبد","lemma":"عَبَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2589,"position":3,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":2590,"position":4,"text_uthmani":"وَٱتَّقُوهُ","transliteration":"wa-ittaqūhu","translation_bn":"এবং তাঁকে ভয় কর","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2591,"position":5,"text_uthmani":"وَأَطِيعُونِ","transliteration":"wa-aṭīʿūni","translation_bn":"ও আমার আনুগত্য কর","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2592,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'ani uʿ''budū l-laha wa-ittaqūhu wa-aṭīʿūni', 'এ বিষয়ে যে, তোমরা আল্লাহর ‘ইবাদাত কর, তাঁকেই ভয় কর, আর আমার কথা মান্য কর।', '[Saying], ''Worship Allah, fear Him and obey me.', 'এ বিষয়ে যে, তোমরা আল্লাহর ‘ইবাদাত কর, তাঁকেই ভয় কর, আর আমার কথা মান্য কর।', '[Saying], ''Worship Allah, fear Him and obey me.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071003.mp3', now()),
  (71, 4, '', '[{"id":3998,"position":1,"text_uthmani":"يَغْفِرْ","transliteration":"yaghfir","translation_bn":"মাফ তিনি করবেন","root":"غفر","lemma":"غَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3999,"position":2,"text_uthmani":"لَكُم","transliteration":"lakum","translation_bn":"তোমাদের জন্য","root":"—","lemma":"لَكُم","grammar_bn":"অব্যয় (Preposition)"},{"id":4000,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4001,"position":4,"text_uthmani":"ذُنُوبِكُمْ","transliteration":"dhunūbikum","translation_bn":"তোমাদের গুনাহ সমূহকে","root":"ذنب","lemma":"ذَنب","grammar_bn":"বিশেষ্য (Noun)"},{"id":4002,"position":5,"text_uthmani":"وَيُؤَخِّرْكُمْ","transliteration":"wayu-akhir''kum","translation_bn":"এবং তোমাদের অবকাশ দেবেন","root":"اخر","lemma":"أَخَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4003,"position":6,"text_uthmani":"إِلَىٰٓ","transliteration":"ilā","translation_bn":"পর্যন্ত","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4004,"position":7,"text_uthmani":"أَجَلٍۢ","transliteration":"ajalin","translation_bn":"সময়","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4005,"position":8,"text_uthmani":"مُّسَمًّى ۚ","transliteration":"musamman","translation_bn":"নির্দিষ্ট","root":"سمو","lemma":"مُّسَمًّى","grammar_bn":"বিশেষণ (Adjective)"},{"id":4007,"position":9,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4008,"position":10,"text_uthmani":"أَجَلَ","transliteration":"ajala","translation_bn":"নির্দধারিত কাল","root":"اجل","lemma":"أَجَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4009,"position":11,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":4010,"position":12,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":4011,"position":13,"text_uthmani":"جَآءَ","transliteration":"jāa","translation_bn":"আসে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4012,"position":14,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":4013,"position":15,"text_uthmani":"يُؤَخَّرُ ۖ","transliteration":"yu-akharu","translation_bn":"বিলম্বিত করা হয়","root":"اخر","lemma":"أَخَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4015,"position":16,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":4016,"position":17,"text_uthmani":"كُنتُمْ","transliteration":"kuntum","translation_bn":"তোমরা হতে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4017,"position":18,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"অবগত\"","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4018,"position":19,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'yaghfir lakum min dhunūbikum wayu-akhir''kum ilā ajalin musamman inna ajala l-lahi idhā jāa lā yu-akharu law kuntum taʿlamūna', 'তাহলে তিনি তোমাদের পাপ ক্ষমা করে দেবেন এবং একটা নির্দিষ্ট সময় পর্যন্ত তোমাদেরকে অবকাশ দেবেন। আল্লাহ কর্তৃক নিদিষ্ট সময় যখন আসবে তখন আর তা বিলম্বিত হবে না। তোমরা যদি জানতে!’', 'Allah will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allah, when it comes, will not be delayed, if you only knew.'' "', 'তাহলে তিনি তোমাদের পাপ ক্ষমা করে দেবেন এবং একটা নির্দিষ্ট সময় পর্যন্ত তোমাদেরকে অবকাশ দেবেন। আল্লাহ কর্তৃক নিদিষ্ট সময় যখন আসবে তখন আর তা বিলম্বিত হবে না। তোমরা যদি জানতে!’', 'Allah will forgive you of your sins and delay you for a specified term. Indeed, the time [set by] Allah, when it comes, will not be delayed, if you only knew.'' "', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071004.mp3', now()),
  (71, 5, '', '[{"id":5306,"position":1,"text_uthmani":"قَالَ","transliteration":"qāla","translation_bn":"সে বলল","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5307,"position":2,"text_uthmani":"رَبِّ","transliteration":"rabbi","translation_bn":"\"আমার রব হে","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5308,"position":3,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"আমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5309,"position":4,"text_uthmani":"دَعَوْتُ","transliteration":"daʿawtu","translation_bn":"আমি ডেকেছি","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":5310,"position":5,"text_uthmani":"قَوْمِى","transliteration":"qawmī","translation_bn":"আমার জাতিকে","root":"قوم","lemma":"قَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":5311,"position":6,"text_uthmani":"لَيْلًۭا","transliteration":"laylan","translation_bn":"রাতে","root":"ليل","lemma":"لَيْل","grammar_bn":"কালবাচক (Time)"},{"id":5312,"position":7,"text_uthmani":"وَنَهَارًۭا","transliteration":"wanahāran","translation_bn":"ও দিনে","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5313,"position":8,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'qāla rabbi innī daʿawtu qawmī laylan wanahāran', 'সে বলেছিল, ‘হে আমার প্রতিপালক! আমি আমার জাতিকে রাত-দিন ডেকেছি,', 'He said, "My Lord, indeed I invited my people [to truth] night and day.', 'সে বলেছিল, ‘হে আমার প্রতিপালক! আমি আমার জাতিকে রাত-দিন ডেকেছি,', 'He said, "My Lord, indeed I invited my people [to truth] night and day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071005.mp3', now()),
  (71, 6, '', '[{"id":6509,"position":1,"text_uthmani":"فَلَمْ","transliteration":"falam","translation_bn":"তাই অতঃপর","root":"—","lemma":"لَم\r","grammar_bn":"শব্দ"},{"id":6510,"position":2,"text_uthmani":"يَزِدْهُمْ","transliteration":"yazid''hum","translation_bn":"তাদের বৃদ্ধি পায়","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6511,"position":3,"text_uthmani":"دُعَآءِىٓ","transliteration":"duʿāī","translation_bn":"আমার দাকে","root":"دعو","lemma":"دُعَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":6512,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":6513,"position":5,"text_uthmani":"فِرَارًۭا","transliteration":"firāran","translation_bn":"পলায়ন","root":"فرر","lemma":"فِرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":6514,"position":6,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'falam yazid''hum duʿāī illā firāran', 'কিন্তু আমার ডাক কেবল তাদের পলায়নী মনোবৃত্তিকেই বাড়িয়ে দিয়েছে,', 'But my invitation increased them not except in flight.', 'কিন্তু আমার ডাক কেবল তাদের পলায়নী মনোবৃত্তিকেই বাড়িয়ে দিয়েছে,', 'But my invitation increased them not except in flight.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071006.mp3', now()),
  (71, 7, '', '[{"id":7915,"position":1,"text_uthmani":"وَإِنِّى","transliteration":"wa-innī","translation_bn":"এবং আমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7916,"position":2,"text_uthmani":"كُلَّمَا","transliteration":"kullamā","translation_bn":"যখনই","root":"كلل\r","lemma":"كُلَّمَا","grammar_bn":"কালবাচক (Time)"},{"id":7917,"position":3,"text_uthmani":"دَعَوْتُهُمْ","transliteration":"daʿawtuhum","translation_bn":"তাদের আমি দেকেছি","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":7918,"position":4,"text_uthmani":"لِتَغْفِرَ","transliteration":"litaghfira","translation_bn":"তুমি মাফ যাতে কর","root":"غفر","lemma":"غَفَرَ","grammar_bn":"শব্দ"},{"id":7919,"position":5,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":7920,"position":6,"text_uthmani":"جَعَلُوٓا۟","transliteration":"jaʿalū","translation_bn":"তারা রেখেছিল","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7921,"position":7,"text_uthmani":"أَصَـٰبِعَهُمْ","transliteration":"aṣābiʿahum","translation_bn":"তাদের আংগুলগুলোকে","root":"صبع","lemma":"أَصَٰبِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":7922,"position":8,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7923,"position":9,"text_uthmani":"ءَاذَانِهِمْ","transliteration":"ādhānihim","translation_bn":"তাদের কানগুলোর","root":"اذن","lemma":"أُذُنٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7924,"position":10,"text_uthmani":"وَٱسْتَغْشَوْا۟","transliteration":"wa-is''taghshaw","translation_bn":"ও তারা ঢেকেছে","root":"غشو","lemma":"ٱسْتَغْشَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7925,"position":11,"text_uthmani":"ثِيَابَهُمْ","transliteration":"thiyābahum","translation_bn":"তাদের কাপড় (দ্বারা)","root":"ثوب","lemma":"ثِيَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":7926,"position":12,"text_uthmani":"وَأَصَرُّوا۟","transliteration":"wa-aṣarrū","translation_bn":"ও অনমনীয় হয়েছে","root":"صرر","lemma":"أَصَرُّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7927,"position":13,"text_uthmani":"وَٱسْتَكْبَرُوا۟","transliteration":"wa-is''takbarū","translation_bn":"এবং অহংকার করেছে","root":"كبر","lemma":"ٱسْتَكْبَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7928,"position":14,"text_uthmani":"ٱسْتِكْبَارًۭا","transliteration":"is''tik''bāran","translation_bn":"বড়ই অহংকার","root":"كبر","lemma":"ٱسْتِكْبَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":7929,"position":15,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wa-innī kullamā daʿawtuhum litaghfira lahum jaʿalū aṣābiʿahum fī ādhānihim wa-is''taghshaw thiyābahum wa-aṣarrū wa-is''takbarū is''tik''bāran', 'আমি যখনই তাদেরকে ডাকি যেন তুমি তাদেরকে ক্ষমা করে দাও, তখনই তারা তাদের কানে আঙ্গুল ডুকিয়ে দিয়েছে, কাপড়ে মুখ ঢেকে নিয়েছে, জিদ করেছে আর খুব বেশি অহঙ্কার করেছে।', 'And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance.', 'আমি যখনই তাদেরকে ডাকি যেন তুমি তাদেরকে ক্ষমা করে দাও, তখনই তারা তাদের কানে আঙ্গুল ডুকিয়ে দিয়েছে, কাপড়ে মুখ ঢেকে নিয়েছে, জিদ করেছে আর খুব বেশি অহঙ্কার করেছে।', 'And indeed, every time I invited them that You may forgive them, they put their fingers in their ears, covered themselves with their garments, persisted, and were arrogant with [great] arrogance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071007.mp3', now()),
  (71, 8, '', '[{"id":9092,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9093,"position":2,"text_uthmani":"إِنِّى","transliteration":"innī","translation_bn":"আমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":9094,"position":3,"text_uthmani":"دَعَوْتُهُمْ","transliteration":"daʿawtuhum","translation_bn":"তাদের ডেকেছি","root":"دعو","lemma":"دَعَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":9095,"position":4,"text_uthmani":"جِهَارًۭا","transliteration":"jihāran","translation_bn":"প্রকাশ্যে","root":"جهر","lemma":"جِهَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":9096,"position":5,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'thumma innī daʿawtuhum jihāran', 'অতঃপর তাদেরকে আমি উচ্চৈঃস্বরে ডেকেছি,', 'Then I invited them publicly.', 'অতঃপর তাদেরকে আমি উচ্চৈঃস্বরে ডেকেছি,', 'Then I invited them publicly.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071008.mp3', now()),
  (71, 9, '', '[{"id":10305,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10306,"position":2,"text_uthmani":"إِنِّىٓ","transliteration":"innī","translation_bn":"আমি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10307,"position":3,"text_uthmani":"أَعْلَنتُ","transliteration":"aʿlantu","translation_bn":"আমি ঘোষণা দিয়াছি","root":"علن","lemma":"أَعْلَن","grammar_bn":"ক্রিয়া (Verb)"},{"id":10308,"position":4,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":10309,"position":5,"text_uthmani":"وَأَسْرَرْتُ","transliteration":"wa-asrartu","translation_bn":"এবং আমি গোপনে বলেছি","root":"سرر","lemma":"أَسَرَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10310,"position":6,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":10311,"position":7,"text_uthmani":"إِسْرَارًۭا","transliteration":"is''rāran","translation_bn":"গোপনে বলা","root":"سرر","lemma":"إِسْرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":10312,"position":8,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'thumma innī aʿlantu lahum wa-asrartu lahum is''rāran', 'এর পর আমি প্রকাশ্যভাবেও তাদের কাছে প্রচার করেছি, আর গোপনে গোপনেও তাদেরকে বুঝিয়েছি।', 'Then I announced to them and [also] confided to them secretly', 'এর পর আমি প্রকাশ্যভাবেও তাদের কাছে প্রচার করেছি, আর গোপনে গোপনেও তাদেরকে বুঝিয়েছি।', 'Then I announced to them and [also] confided to them secretly', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071009.mp3', now()),
  (71, 10, '', '[{"id":11535,"position":1,"text_uthmani":"فَقُلْتُ","transliteration":"faqul''tu","translation_bn":"আমি বলেছি অতঃপর","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11536,"position":2,"text_uthmani":"ٱسْتَغْفِرُوا۟","transliteration":"is''taghfirū","translation_bn":"\"তোমরা মাফ চাও","root":"غفر","lemma":"ٱسْتَغْفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11537,"position":3,"text_uthmani":"رَبَّكُمْ","transliteration":"rabbakum","translation_bn":"তোমাদের রবের (কাছে)","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11538,"position":4,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তিনি নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11539,"position":5,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11540,"position":6,"text_uthmani":"غَفَّارًۭا","transliteration":"ghaffāran","translation_bn":"বড় ক্ষমাশীল","root":"غفر","lemma":"غَفَّار","grammar_bn":"বিশেষ্য (Noun)"},{"id":11541,"position":7,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'faqul''tu is''taghfirū rabbakum innahu kāna ghaffāran', 'আমি বলেছি- ‘তোমরা তোমাদের রব্বের কাছে ক্ষমা চাও, তিনি বড়ই ক্ষমাশীল।', 'And said, ''Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver.', 'আমি বলেছি- ‘তোমরা তোমাদের রব্বের কাছে ক্ষমা চাও, তিনি বড়ই ক্ষমাশীল।', 'And said, ''Ask forgiveness of your Lord. Indeed, He is ever a Perpetual Forgiver.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071010.mp3', now()),
  (71, 11, '', '[{"id":12854,"position":1,"text_uthmani":"يُرْسِلِ","transliteration":"yur''sili","translation_bn":"পাঠাবেন তিনি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":12855,"position":2,"text_uthmani":"ٱلسَّمَآءَ","transliteration":"l-samāa","translation_bn":"আকাশ (থেকে)","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":12856,"position":3,"text_uthmani":"عَلَيْكُم","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":12857,"position":4,"text_uthmani":"مِّدْرَارًۭا","transliteration":"mid''rāran","translation_bn":"বৃষ্টি","root":"درر","lemma":"مِّدْرَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":12858,"position":5,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'yur''sili l-samāa ʿalaykum mid''rāran', '(তোমরা তা করলে) তিনি অজস্র ধারায় তোমাদের উপর বৃষ্টি বর্ষণ করবেন,', 'He will send [rain from] the sky upon you in [continuing] showers', '(তোমরা তা করলে) তিনি অজস্র ধারায় তোমাদের উপর বৃষ্টি বর্ষণ করবেন,', 'He will send [rain from] the sky upon you in [continuing] showers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071011.mp3', now()),
  (71, 12, '', '[{"id":14104,"position":1,"text_uthmani":"وَيُمْدِدْكُم","transliteration":"wayum''did''kum","translation_bn":"এবং তোমাদের সাহায্য করবেন","root":"مدد","lemma":"أَمَدَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14105,"position":2,"text_uthmani":"بِأَمْوَٰلٍۢ","transliteration":"bi-amwālin","translation_bn":"মালসমূহ দিয়ে","root":"مول","lemma":"مَال","grammar_bn":"অব্যয় (Preposition)"},{"id":14106,"position":3,"text_uthmani":"وَبَنِينَ","transliteration":"wabanīna","translation_bn":"ও সন্তান সন্ততি দিয়ে","root":"بني","lemma":"بُنَىّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14107,"position":4,"text_uthmani":"وَيَجْعَل","transliteration":"wayajʿal","translation_bn":"এবং সৃষ্টি করবেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14108,"position":5,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":14109,"position":6,"text_uthmani":"جَنَّـٰتٍۢ","transliteration":"jannātin","translation_bn":"বাগবাগিচাসমূহ","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14110,"position":7,"text_uthmani":"وَيَجْعَل","transliteration":"wayajʿal","translation_bn":"ও বানাবেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14111,"position":8,"text_uthmani":"لَّكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَّكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":14112,"position":9,"text_uthmani":"أَنْهَـٰرًۭا","transliteration":"anhāran","translation_bn":"ঝর্ণাসমূহ","root":"نهر","lemma":"نَهَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":14113,"position":10,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wayum''did''kum bi-amwālin wabanīna wayajʿal lakum jannātin wayajʿal lakum anhāran', 'তোমাদের ধন সম্পদ ও সন্তানাদি বাড়িয়ে দেবেন, তোমাদের জন্য বাগান সৃষ্টি করবেন এবং তোমাদের জন্য নদীনালা প্রবাহিত করবেন।', 'And give you increase in wealth and children and provide for you gardens and provide for you rivers.', 'তোমাদের ধন সম্পদ ও সন্তানাদি বাড়িয়ে দেবেন, তোমাদের জন্য বাগান সৃষ্টি করবেন এবং তোমাদের জন্য নদীনালা প্রবাহিত করবেন।', 'And give you increase in wealth and children and provide for you gardens and provide for you rivers.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071012.mp3', now()),
  (71, 13, '', '[{"id":15231,"position":1,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"কী হয়েছে","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":15232,"position":2,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":15233,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15234,"position":4,"text_uthmani":"تَرْجُونَ","transliteration":"tarjūna","translation_bn":"তোমরা আশা কর","root":"رجو","lemma":"يَرْجُوا@","grammar_bn":"ক্রিয়া (Verb)"},{"id":15235,"position":5,"text_uthmani":"لِلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহর জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":15236,"position":6,"text_uthmani":"وَقَارًۭا","transliteration":"waqāran","translation_bn":"মর্যাদা","root":"وقر","lemma":"وَقَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":15237,"position":7,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'mā lakum lā tarjūna lillahi waqāran', '‘তোমাদের হল কী যে, তোমরা আল্লাহর শ্রেষ্ঠত্ব মেনে নিতে অস্বীকার করছ?', 'What is [the matter] with you that you do not attribute to Allah [due] grandeur', '‘তোমাদের হল কী যে, তোমরা আল্লাহর শ্রেষ্ঠত্ব মেনে নিতে অস্বীকার করছ?', 'What is [the matter] with you that you do not attribute to Allah [due] grandeur', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071013.mp3', now()),
  (71, 14, '', '[{"id":16263,"position":1,"text_uthmani":"وَقَدْ","transliteration":"waqad","translation_bn":"এবং নিশ্চয়","root":"—","lemma":"قَد\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":16264,"position":2,"text_uthmani":"خَلَقَكُمْ","transliteration":"khalaqakum","translation_bn":"তোমাদের তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16265,"position":3,"text_uthmani":"أَطْوَارًا","transliteration":"aṭwāran","translation_bn":"পর্যায়ক্রমে","root":"طور","lemma":"أَطْوَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":16266,"position":4,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'waqad khalaqakum aṭwāran', 'অথচ তিনিই তোমাদেরকে সৃষ্টি করেছেন নানান স্তর অতিক্রম করিয়ে।', 'While He has created you in stages?', 'অথচ তিনিই তোমাদেরকে সৃষ্টি করেছেন নানান স্তর অতিক্রম করিয়ে।', 'While He has created you in stages?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071014.mp3', now()),
  (71, 15, '', '[{"id":17457,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"নাই কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":17458,"position":2,"text_uthmani":"تَرَوْا۟","transliteration":"taraw","translation_bn":"তোমরা দেখ","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":17459,"position":3,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমনে","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":17460,"position":4,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17461,"position":5,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17462,"position":6,"text_uthmani":"سَبْعَ","transliteration":"sabʿa","translation_bn":"সাত","root":"سبع","lemma":"سَبْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":17463,"position":7,"text_uthmani":"سَمَـٰوَٰتٍۢ","transliteration":"samāwātin","translation_bn":"আসমান","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":17464,"position":8,"text_uthmani":"طِبَاقًۭا","transliteration":"ṭibāqan","translation_bn":"স্তরে স্তরে","root":"طبق","lemma":"طَبَق","grammar_bn":"বিশেষণ (Adjective)"},{"id":17465,"position":9,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'alam taraw kayfa khalaqa l-lahu sabʿa samāwātin ṭibāqan', 'তোমরা কি দেখ না, কীভাবে আল্লাহ সাত আসমান সৃষ্টি করেছেন একের উপরে আরেকটিকে (স্থাপন করে)?', 'Do you not consider how Allah has created seven heavens in layers', 'তোমরা কি দেখ না, কীভাবে আল্লাহ সাত আসমান সৃষ্টি করেছেন একের উপরে আরেকটিকে (স্থাপন করে)?', 'Do you not consider how Allah has created seven heavens in layers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071015.mp3', now()),
  (71, 16, '', '[{"id":18508,"position":1,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18509,"position":2,"text_uthmani":"ٱلْقَمَرَ","transliteration":"l-qamara","translation_bn":"চাঁদকে","root":"قمر","lemma":"قَمَر","grammar_bn":"শব্দ"},{"id":18510,"position":3,"text_uthmani":"فِيهِنَّ","transliteration":"fīhinna","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18511,"position":4,"text_uthmani":"نُورًۭا","transliteration":"nūran","translation_bn":"আলো","root":"نور","lemma":"نُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":18512,"position":5,"text_uthmani":"وَجَعَلَ","transliteration":"wajaʿala","translation_bn":"এবং বানিয়েছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18513,"position":6,"text_uthmani":"ٱلشَّمْسَ","transliteration":"l-shamsa","translation_bn":"সূর্যকে","root":"شمس","lemma":"شَمْس","grammar_bn":"শব্দ"},{"id":18514,"position":7,"text_uthmani":"سِرَاجًۭا","transliteration":"sirājan","translation_bn":"প্রদীপ রূপে","root":"سرج","lemma":"سِرَاج","grammar_bn":"বিশেষ্য (Noun)"},{"id":18515,"position":8,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿala l-qamara fīhinna nūran wajaʿala l-shamsa sirājan', 'আর তাদের মাঝে চাঁদকে বানিয়েছেন আলো এবং সূর্যকে করেছেন প্রদীপ।', 'And made the moon therein a [reflected] light and made the sun a burning lamp?', 'আর তাদের মাঝে চাঁদকে বানিয়েছেন আলো এবং সূর্যকে করেছেন প্রদীপ।', 'And made the moon therein a [reflected] light and made the sun a burning lamp?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071016.mp3', now()),
  (71, 17, '', '[{"id":19527,"position":1,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":19528,"position":2,"text_uthmani":"أَنۢبَتَكُم","transliteration":"anbatakum","translation_bn":"তোমাদের উদ্ভুত করেছেন","root":"نبت","lemma":"أَن[بَتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19529,"position":3,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19530,"position":4,"text_uthmani":"ٱلْأَرْضِ","transliteration":"l-arḍi","translation_bn":"মৃত্তিকা","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":19531,"position":5,"text_uthmani":"نَبَاتًۭا","transliteration":"nabātan","translation_bn":"(বিস্ময়করভাবে উদ্ভুত)","root":"نبت","lemma":"نَبَات","grammar_bn":"বিশেষ্য (Noun)"},{"id":19532,"position":6,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wal-lahu anbatakum mina l-arḍi nabātan', 'আল্লাহ তোমাদেরকে মাটি থেকে উদগত করেন (এবং ক্রমশঃ বাড়িয়ে তোলেন যেমন বাড়িয়ে তোলেন বৃক্ষকে)', 'And Allah has caused you to grow from the earth a [progressive] growth.', 'আল্লাহ তোমাদেরকে মাটি থেকে উদগত করেন (এবং ক্রমশঃ বাড়িয়ে তোলেন যেমন বাড়িয়ে তোলেন বৃক্ষকে)', 'And Allah has caused you to grow from the earth a [progressive] growth.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071017.mp3', now()),
  (71, 18, '', '[{"id":20603,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"এরপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20604,"position":2,"text_uthmani":"يُعِيدُكُمْ","transliteration":"yuʿīdukum","translation_bn":"তোমাদের ফিরিয়ে নেবেন","root":"عود","lemma":"أُعِيدُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20605,"position":3,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20606,"position":4,"text_uthmani":"وَيُخْرِجُكُمْ","transliteration":"wayukh''rijukum","translation_bn":"এবং তোমাদেরকে বের করবেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20607,"position":5,"text_uthmani":"إِخْرَاجًۭا","transliteration":"ikh''rājan","translation_bn":"(সম্পূর্ণরূপে) বহিষ্কার","root":"خرج","lemma":"إِخْرَاج","grammar_bn":"বিশেষ্য (Noun)"},{"id":20608,"position":6,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'thumma yuʿīdukum fīhā wayukh''rijukum ikh''rājan', 'অতঃপর এই মাটিতেই তোমাদেরকে ফিরিয়ে আনবেন এবং তোমাদেরকে পুনরুত্থিত করবেন।', 'Then He will return you into it and extract you [another] extraction.', 'অতঃপর এই মাটিতেই তোমাদেরকে ফিরিয়ে আনবেন এবং তোমাদেরকে পুনরুত্থিত করবেন।', 'Then He will return you into it and extract you [another] extraction.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/071018.mp3', now()),
