  (73, 1, '', '[{"id":628,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":629,"position":2,"text_uthmani":"ٱلْمُزَّمِّلُ","transliteration":"l-muzamilu","translation_bn":"বস্ত্রাবৃত","root":"زمل","lemma":"مُزَّمِّل","grammar_bn":"শব্দ"},{"id":630,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-muzamilu', 'ওহে চাদরে আবৃত (ব্যক্তি)!', 'O you who wraps himself [in clothing],', 'ওহে চাদরে আবৃত (ব্যক্তি)!', 'O you who wraps himself [in clothing],', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073001.mp3', now()),
  (73, 2, '', '[{"id":1575,"position":1,"text_uthmani":"قُمِ","transliteration":"qumi","translation_bn":"উঠো","root":"قوم","lemma":"قَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1576,"position":2,"text_uthmani":"ٱلَّيْلَ","transliteration":"al-layla","translation_bn":"রাতে (ইবাদত করো)","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":1577,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":1578,"position":4,"text_uthmani":"قَلِيلًۭا","transliteration":"qalīlan","translation_bn":"কিছু অংশ","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1579,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'qumi al-layla illā qalīlan', 'রাতে নামাযে দাঁড়াও তবে (রাতের) কিছু অংশ বাদে,', 'Arise [to pray] the night, except for a little -', 'রাতে নামাযে দাঁড়াও তবে (রাতের) কিছু অংশ বাদে,', 'Arise [to pray] the night, except for a little -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073002.mp3', now()),
  (73, 3, '', '[{"id":2616,"position":1,"text_uthmani":"نِّصْفَهُۥٓ","transliteration":"niṣ''fahu","translation_bn":"তার অর্ধেক","root":"نصف","lemma":"نِصْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":2617,"position":2,"text_uthmani":"أَوِ","transliteration":"awi","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2618,"position":3,"text_uthmani":"ٱنقُصْ","transliteration":"unquṣ","translation_bn":"কম করো","root":"نقص","lemma":"يُنقَصُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2619,"position":4,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তা থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2620,"position":5,"text_uthmani":"قَلِيلًا","transliteration":"qalīlan","translation_bn":"সামান্য","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":2621,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'niṣ''fahu awi unquṣ min''hu qalīlan', 'রাতের অর্ধেক (সময় দাঁড়াও) কিংবা তার থেকে কিছুটা কম কর,', 'Half of it - or subtract from it a little', 'রাতের অর্ধেক (সময় দাঁড়াও) কিংবা তার থেকে কিছুটা কম কর,', 'Half of it - or subtract from it a little', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073003.mp3', now()),
  (73, 4, '', '[{"id":4034,"position":1,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"অথবা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4035,"position":2,"text_uthmani":"زِدْ","transliteration":"zid","translation_bn":"বাড়াও","root":"زيد","lemma":"زَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4036,"position":3,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4037,"position":4,"text_uthmani":"وَرَتِّلِ","transliteration":"warattili","translation_bn":"এবং আবৃতি করো ধীরে ধীরে","root":"رتل","lemma":"رَتَّلْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4038,"position":5,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":4039,"position":6,"text_uthmani":"تَرْتِيلًا","transliteration":"tartīlan","translation_bn":"তারতিলসহ","root":"رتل","lemma":"تَرْتِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":4040,"position":7,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'aw zid ʿalayhi warattili l-qur''āna tartīlan', 'অথবা তার চেয়ে বাড়াও, আর ধীরে ধীরে সুস্পষ্টভাবে কুরআন পাঠ কর।', 'Or add to it, and recite the Qur''an with measured recitation.', 'অথবা তার চেয়ে বাড়াও, আর ধীরে ধীরে সুস্পষ্টভাবে কুরআন পাঠ কর।', 'Or add to it, and recite the Qur''an with measured recitation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073004.mp3', now()),
  (73, 5, '', '[{"id":5325,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5326,"position":2,"text_uthmani":"سَنُلْقِى","transliteration":"sanul''qī","translation_bn":"অর্পণ আমরা শিঘ্রই করবো","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":5327,"position":3,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5328,"position":4,"text_uthmani":"قَوْلًۭا","transliteration":"qawlan","translation_bn":"বাণী","root":"قول","lemma":"قَوْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5329,"position":5,"text_uthmani":"ثَقِيلًا","transliteration":"thaqīlan","translation_bn":"ভারী","root":"ثقل","lemma":"ثَقِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":5330,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'innā sanul''qī ʿalayka qawlan thaqīlan', 'আমি তোমার উপর গুরুভার কালাম নাযিল করব (বিশ্বের বুকে যার প্রচার ও প্রতিষ্ঠা করার দায়িত্বভার অতি বড় কঠিন কাজ)।', 'Indeed, We will cast upon you a heavy word.', 'আমি তোমার উপর গুরুভার কালাম নাযিল করব (বিশ্বের বুকে যার প্রচার ও প্রতিষ্ঠা করার দায়িত্বভার অতি বড় কঠিন কাজ)।', 'Indeed, We will cast upon you a heavy word.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073005.mp3', now()),
  (73, 6, '', '[{"id":6527,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6528,"position":2,"text_uthmani":"نَاشِئَةَ","transliteration":"nāshi-ata","translation_bn":"উথান (শয্যা ত্যাগ)","root":"نشا","lemma":"نَاشِئَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":6529,"position":3,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাত্রি কালের","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":6530,"position":4,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"তা","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":6531,"position":5,"text_uthmani":"أَشَدُّ","transliteration":"ashaddu","translation_bn":"প্রবলতর","root":"شدد","lemma":"أَشَدّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6532,"position":6,"text_uthmani":"وَطْـًۭٔا","transliteration":"waṭan","translation_bn":"দলনে (প্রবৃত্তি)","root":"وطا","lemma":"وَطْـ#","grammar_bn":"বিশেষ্য (Noun)"},{"id":6533,"position":7,"text_uthmani":"وَأَقْوَمُ","transliteration":"wa-aqwamu","translation_bn":"এবং সঠিকতর","root":"قوم","lemma":"أَقْوَم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6534,"position":8,"text_uthmani":"قِيلًا","transliteration":"qīlan","translation_bn":"বাক্য স্ফুরণে","root":"قول","lemma":"قِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":6535,"position":9,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'inna nāshi-ata al-layli hiya ashaddu waṭan wa-aqwamu qīlan', 'বাস্তবিকই রাতে বিছানা ছেড়ে উঠা আত্মসংযমের জন্য বেশি কার্যকর এবং (কুরআন) স্পষ্ট উচ্চারণের অনুকূল।', 'Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words.', 'বাস্তবিকই রাতে বিছানা ছেড়ে উঠা আত্মসংযমের জন্য বেশি কার্যকর এবং (কুরআন) স্পষ্ট উচ্চারণের অনুকূল।', 'Indeed, the hours of the night are more effective for concurrence [of heart and tongue] and more suitable for words.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073006.mp3', now()),
  (73, 7, '', '[{"id":7940,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":7941,"position":2,"text_uthmani":"لَكَ","transliteration":"laka","translation_bn":"তোমার জন্যে","root":"—","lemma":"لَكَ","grammar_bn":"অব্যয় (Preposition)"},{"id":7942,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7943,"position":4,"text_uthmani":"ٱلنَّهَارِ","transliteration":"l-nahāri","translation_bn":"দিনে","root":"نهر","lemma":"نَهَار","grammar_bn":"শব্দ"},{"id":7944,"position":5,"text_uthmani":"سَبْحًۭا","transliteration":"sabḥan","translation_bn":"ব্যস্ততা","root":"سبح","lemma":"سَبْح","grammar_bn":"বিশেষ্য (Noun)"},{"id":7945,"position":6,"text_uthmani":"طَوِيلًۭا","transliteration":"ṭawīlan","translation_bn":"দীর্ঘ","root":"طول","lemma":"طَوِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":7946,"position":7,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'inna laka fī l-nahāri sabḥan ṭawīlan', 'দিনের বেলায় তোমার জন্য আছে দীর্ঘ কর্মব্যস্ততা।', 'Indeed, for you by day is prolonged occupation.', 'দিনের বেলায় তোমার জন্য আছে দীর্ঘ কর্মব্যস্ততা।', 'Indeed, for you by day is prolonged occupation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073007.mp3', now()),
  (73, 8, '', '[{"id":9106,"position":1,"text_uthmani":"وَٱذْكُرِ","transliteration":"wa-udh''kuri","translation_bn":"এবং তুমি স্মরণ করো","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9107,"position":2,"text_uthmani":"ٱسْمَ","transliteration":"is''ma","translation_bn":"নাম","root":"سمو","lemma":"ٱسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":9108,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9109,"position":4,"text_uthmani":"وَتَبَتَّلْ","transliteration":"watabattal","translation_bn":"এবং নিমগ্ন হও","root":"بتل","lemma":"تَبَتَّلْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9110,"position":5,"text_uthmani":"إِلَيْهِ","transliteration":"ilayhi","translation_bn":"তার দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9111,"position":6,"text_uthmani":"تَبْتِيلًۭا","transliteration":"tabtīlan","translation_bn":"খুব নিমগ্ন হয়ে","root":"بتل","lemma":"تَبْتِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":9112,"position":7,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kuri is''ma rabbika watabattal ilayhi tabtīlan', 'কাজেই তুমি তোমার প্রতিপালকের নাম স্মরণ কর এবং একাগ্রচিত্তে তাঁর প্রতি মগ্ন হও।', 'And remember the name of your Lord and devote yourself to Him with [complete] devotion.', 'কাজেই তুমি তোমার প্রতিপালকের নাম স্মরণ কর এবং একাগ্রচিত্তে তাঁর প্রতি মগ্ন হও।', 'And remember the name of your Lord and devote yourself to Him with [complete] devotion.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073008.mp3', now()),
  (73, 9, '', '[{"id":10328,"position":1,"text_uthmani":"رَّبُّ","transliteration":"rabbu","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":10329,"position":2,"text_uthmani":"ٱلْمَشْرِقِ","transliteration":"l-mashriqi","translation_bn":"পূর্ব","root":"شرق","lemma":"مَشْرِق","grammar_bn":"শব্দ"},{"id":10330,"position":3,"text_uthmani":"وَٱلْمَغْرِبِ","transliteration":"wal-maghribi","translation_bn":"ও পশ্চিমের","root":"غرب","lemma":"مَغْرِب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10331,"position":4,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"নেই","root":"—","lemma":"لَا","grammar_bn":"না-বোধক (Negative)"},{"id":10332,"position":5,"text_uthmani":"إِلَـٰهَ","transliteration":"ilāha","translation_bn":"(কোন) ইলাহ","root":"اله","lemma":"إِلَٰه","grammar_bn":"বিশেষ্য (Noun)"},{"id":10333,"position":6,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":10334,"position":7,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10335,"position":8,"text_uthmani":"فَٱتَّخِذْهُ","transliteration":"fa-ittakhidh''hu","translation_bn":"তাকেই গ্রহণ সুতরাং করো","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"কারণবাচক (Cause)"},{"id":10336,"position":9,"text_uthmani":"وَكِيلًۭا","transliteration":"wakīlan","translation_bn":"কর্ম বিধায়ক রূপে","root":"وكل","lemma":"وَكِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":10337,"position":10,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'rabbu l-mashriqi wal-maghribi lā ilāha illā huwa fa-ittakhidh''hu wakīlan', '(তিনি) পূর্ব ও পশ্চিমের সর্বময় কর্তা, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, অতএব তাঁকেই তুমি তোমার কার্য সম্পদানকারী বানিয়ে লও।', '[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.', '(তিনি) পূর্ব ও পশ্চিমের সর্বময় কর্তা, তিনি ছাড়া সত্যিকারের কোন ইলাহ নেই, অতএব তাঁকেই তুমি তোমার কার্য সম্পদানকারী বানিয়ে লও।', '[He is] the Lord of the East and the West; there is no deity except Him, so take Him as Disposer of [your] affairs.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073009.mp3', now()),
  (73, 10, '', '[{"id":11562,"position":1,"text_uthmani":"وَٱصْبِرْ","transliteration":"wa-iṣ''bir","translation_bn":"এবং সবর করো","root":"صبر","lemma":"صَبَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11563,"position":2,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11564,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11565,"position":4,"text_uthmani":"يَقُولُونَ","transliteration":"yaqūlūna","translation_bn":"তারা বলেছে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11566,"position":5,"text_uthmani":"وَٱهْجُرْهُمْ","transliteration":"wa-uh''jur''hum","translation_bn":"এবং তাদের পরিহার করো","root":"هجر","lemma":"ٱهْجُرْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":11567,"position":6,"text_uthmani":"هَجْرًۭا","transliteration":"hajran","translation_bn":"পরিহার","root":"هجر","lemma":"هَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":11568,"position":7,"text_uthmani":"جَمِيلًۭا","transliteration":"jamīlan","translation_bn":"উত্তম","root":"جمل","lemma":"جَمِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":11569,"position":8,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-iṣ''bir ʿalā mā yaqūlūna wa-uh''jur''hum hajran jamīlan', 'তারা যা বলে সে ব্যাপারে ধৈর্য ধারণ কর আর ভদ্রতার সঙ্গে তাদেরকে পরিহার ক’রে চল।', 'And be patient over what they say and avoid them with gracious avoidance.', 'তারা যা বলে সে ব্যাপারে ধৈর্য ধারণ কর আর ভদ্রতার সঙ্গে তাদেরকে পরিহার ক’রে চল।', 'And be patient over what they say and avoid them with gracious avoidance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073010.mp3', now()),
  (73, 11, '', '[{"id":12870,"position":1,"text_uthmani":"وَذَرْنِى","transliteration":"wadharnī","translation_bn":"এবং আমাকে ছাড়","root":"وذر","lemma":"يَذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12871,"position":2,"text_uthmani":"وَٱلْمُكَذِّبِينَ","transliteration":"wal-mukadhibīna","translation_bn":"ও মিথারপকারীদের","root":"كذب","lemma":"مُّكَذِّبِين","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12872,"position":3,"text_uthmani":"أُو۟لِى","transliteration":"ulī","translation_bn":"অধিকারী","root":"اول","lemma":"أُولِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":12873,"position":4,"text_uthmani":"ٱلنَّعْمَةِ","transliteration":"l-naʿmati","translation_bn":"নেয়ামতের","root":"نعم","lemma":"نَّعْمَة","grammar_bn":"শব্দ"},{"id":12874,"position":5,"text_uthmani":"وَمَهِّلْهُمْ","transliteration":"wamahhil''hum","translation_bn":"এবং তাদে্র অবকাশ দাও","root":"مهل","lemma":"مَهِّلِ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12875,"position":6,"text_uthmani":"قَلِيلًا","transliteration":"qalīlan","translation_bn":"সামান্য","root":"قلل","lemma":"قَلِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":12876,"position":7,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'wadharnī wal-mukadhibīna ulī l-naʿmati wamahhil''hum qalīlan', 'আর ছেড়ে দাও আমাকে আর নানান বিলাস সামগ্রীর মালিক ঐ মিথ্যুকদেরকে এবং তাদেরকে কিছুটা সময় অবকাশ দাও।', 'And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little.', 'আর ছেড়ে দাও আমাকে আর নানান বিলাস সামগ্রীর মালিক ঐ মিথ্যুকদেরকে এবং তাদেরকে কিছুটা সময় অবকাশ দাও।', 'And leave Me with [the matter of] the deniers, those of ease [in life], and allow them respite a little.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073011.mp3', now()),
  (73, 12, '', '[{"id":14126,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":14127,"position":2,"text_uthmani":"لَدَيْنَآ","transliteration":"ladaynā","translation_bn":"আমাদের কাছে আছে","root":"—","lemma":"لَدَي\r","grammar_bn":"স্থানবাচক (Location)"},{"id":14128,"position":3,"text_uthmani":"أَنكَالًۭا","transliteration":"ankālan","translation_bn":"শৃংখল","root":"نكل","lemma":"أَنكَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":14129,"position":4,"text_uthmani":"وَجَحِيمًۭا","transliteration":"wajaḥīman","translation_bn":"এবং প্রজ্বলিত আগুন","root":"جحم","lemma":"جَحِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14130,"position":5,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'inna ladaynā ankālan wajaḥīman', 'আমার কাছে আছে শেকল আর দাউ দাউ করে জ্বলা আগুন,', 'Indeed, with Us [for them] are shackles and burning fire', 'আমার কাছে আছে শেকল আর দাউ দাউ করে জ্বলা আগুন,', 'Indeed, with Us [for them] are shackles and burning fire', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073012.mp3', now()),
  (73, 13, '', '[{"id":15254,"position":1,"text_uthmani":"وَطَعَامًۭا","transliteration":"waṭaʿāman","translation_bn":"এবং খাদ্য","root":"طعم","lemma":"طَعَام","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15255,"position":2,"text_uthmani":"ذَا","transliteration":"dhā","translation_bn":"যাওয়া","root":"—","lemma":"ذَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":15256,"position":3,"text_uthmani":"غُصَّةٍۢ","transliteration":"ghuṣṣatin","translation_bn":"আটকে (গলায়ে)","root":"غصص","lemma":"غُصَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15257,"position":4,"text_uthmani":"وَعَذَابًا","transliteration":"waʿadhāban","translation_bn":"ও আযাব","root":"عذب","lemma":"عَذَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15258,"position":5,"text_uthmani":"أَلِيمًۭا","transliteration":"alīman","translation_bn":"কষ্টকর","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":15259,"position":6,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'waṭaʿāman dhā ghuṣṣatin waʿadhāban alīman', 'আর গলায় আটকে যায় এমন খাবার আর মর্মান্তিক শাস্তি।', 'And food that chokes and a painful punishment -', 'আর গলায় আটকে যায় এমন খাবার আর মর্মান্তিক শাস্তি।', 'And food that chokes and a painful punishment -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073013.mp3', now()),
  (73, 14, '', '[{"id":16751,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":16752,"position":2,"text_uthmani":"تَرْجُفُ","transliteration":"tarjufu","translation_bn":"কাঁপবে","root":"رجف","lemma":"تَرْجُفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16753,"position":3,"text_uthmani":"ٱلْأَرْضُ","transliteration":"l-arḍu","translation_bn":"জমিন","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":16754,"position":4,"text_uthmani":"وَٱلْجِبَالُ","transliteration":"wal-jibālu","translation_bn":"ও পাহাড়সমূহ","root":"جبل","lemma":"جَبَل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16755,"position":5,"text_uthmani":"وَكَانَتِ","transliteration":"wakānati","translation_bn":"এবং হবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16756,"position":6,"text_uthmani":"ٱلْجِبَالُ","transliteration":"l-jibālu","translation_bn":"পাহাড়গুলো","root":"جبل","lemma":"جَبَل","grammar_bn":"শব্দ"},{"id":16757,"position":7,"text_uthmani":"كَثِيبًۭا","transliteration":"kathīban","translation_bn":"ধুলার স্তূপ","root":"كثب","lemma":"كَثِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":16758,"position":8,"text_uthmani":"مَّهِيلًا","transliteration":"mahīlan","translation_bn":"বিক্ষিপ্ত হয়ে পড়া","root":"هيل","lemma":"مَّهِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":16759,"position":9,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'yawma tarjufu l-arḍu wal-jibālu wakānati l-jibālu kathīban mahīlan', '(এসব শাস্তি দেয়া হবে) যেদিন যমীন আর পাহাড়গুলো কেঁপে উঠবে, আর পাহাড়গুলো হবে চলমান বালুকারাশি।', 'On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down.', '(এসব শাস্তি দেয়া হবে) যেদিন যমীন আর পাহাড়গুলো কেঁপে উঠবে, আর পাহাড়গুলো হবে চলমান বালুকারাশি।', 'On the Day the earth and the mountains will convulse and the mountains will become a heap of sand pouring down.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073014.mp3', now()),
  (73, 15, '', '[{"id":17873,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"আমরা নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":17874,"position":2,"text_uthmani":"أَرْسَلْنَآ","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17875,"position":3,"text_uthmani":"إِلَيْكُمْ","transliteration":"ilaykum","translation_bn":"তোমাদের প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17876,"position":4,"text_uthmani":"رَسُولًۭا","transliteration":"rasūlan","translation_bn":"একজন রসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":17877,"position":5,"text_uthmani":"شَـٰهِدًا","transliteration":"shāhidan","translation_bn":"সাক্ষ্য দাতা রূপে","root":"شهد","lemma":"شَاهِد","grammar_bn":"বিশেষণ (Adjective)"},{"id":17878,"position":6,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17879,"position":7,"text_uthmani":"كَمَآ","transliteration":"kamā","translation_bn":"যেমন","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17880,"position":8,"text_uthmani":"أَرْسَلْنَآ","transliteration":"arsalnā","translation_bn":"আমরা পাঠিয়েছি","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17881,"position":9,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"প্রতি","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17882,"position":10,"text_uthmani":"فِرْعَوْنَ","transliteration":"fir''ʿawna","translation_bn":"ফিরাআউনের","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":17883,"position":11,"text_uthmani":"رَسُولًۭا","transliteration":"rasūlan","translation_bn":"একজন রসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":17884,"position":12,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'innā arsalnā ilaykum rasūlan shāhidan ʿalaykum kamā arsalnā ilā fir''ʿawna rasūlan', 'আমি তোমাদের কাছে তেমনিভাবে একজন রসূলকে তোমাদের প্রতি সাক্ষ্যদাতা হিসেবে পাঠিয়েছি (যিনি ক্বিয়ামতে সাক্ষ্য দিবেন যে, দ্বীনের দাওয়াত তিনি যথাযথভাবে মানুষের কাছে পৌঁছে দিয়েছেন) যেমনভাবে আমি ফেরাউনের কাছে পাঠিয়েছিলাম একজন রসূলকে।', 'Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger.', 'আমি তোমাদের কাছে তেমনিভাবে একজন রসূলকে তোমাদের প্রতি সাক্ষ্যদাতা হিসেবে পাঠিয়েছি (যিনি ক্বিয়ামতে সাক্ষ্য দিবেন যে, দ্বীনের দাওয়াত তিনি যথাযথভাবে মানুষের কাছে পৌঁছে দিয়েছেন) যেমনভাবে আমি ফেরাউনের কাছে পাঠিয়েছিলাম একজন রসূলকে।', 'Indeed, We have sent to you a Messenger as a witness upon you just as We sent to Pharaoh a messenger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073015.mp3', now()),
  (73, 16, '', '[{"id":18541,"position":1,"text_uthmani":"فَعَصَىٰ","transliteration":"faʿaṣā","translation_bn":"অমান্য করল অতঃপর","root":"عصي","lemma":"عَصَا","grammar_bn":"শব্দ"},{"id":18542,"position":2,"text_uthmani":"فِرْعَوْنُ","transliteration":"fir''ʿawnu","translation_bn":"ফিরাআউন","root":"—","lemma":"فِرْعَوْن","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":18543,"position":3,"text_uthmani":"ٱلرَّسُولَ","transliteration":"l-rasūla","translation_bn":"রসূলকে","root":"رسل","lemma":"رَسُول","grammar_bn":"শব্দ"},{"id":18544,"position":4,"text_uthmani":"فَأَخَذْنَـٰهُ","transliteration":"fa-akhadhnāhu","translation_bn":"তাকে আমরা ধরেছি অতএব","root":"اخذ","lemma":"أَخَذَ","grammar_bn":"কারণবাচক (Cause)"},{"id":18545,"position":5,"text_uthmani":"أَخْذًۭا","transliteration":"akhdhan","translation_bn":"ধরা","root":"اخذ","lemma":"أَخْذ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18546,"position":6,"text_uthmani":"وَبِيلًۭا","transliteration":"wabīlan","translation_bn":"শক্ত","root":"وبل","lemma":"وَبِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":18547,"position":7,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'faʿaṣā fir''ʿawnu l-rasūla fa-akhadhnāhu akhdhan wabīlan', 'তখন ফেরাউন সেই রসূলকে অমান্য করল। ফলে আমি তাকে শক্ত ধরায় ধরলাম।', 'But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure.', 'তখন ফেরাউন সেই রসূলকে অমান্য করল। ফলে আমি তাকে শক্ত ধরায় ধরলাম।', 'But Pharaoh disobeyed the messenger, so We seized him with a ruinous seizure.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073016.mp3', now()),
  (73, 17, '', '[{"id":19545,"position":1,"text_uthmani":"فَكَيْفَ","transliteration":"fakayfa","translation_bn":"কেমনে তখন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"শব্দ"},{"id":19546,"position":2,"text_uthmani":"تَتَّقُونَ","transliteration":"tattaqūna","translation_bn":"তোমরা রক্ষা পাবে","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19547,"position":3,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":19548,"position":4,"text_uthmani":"كَفَرْتُمْ","transliteration":"kafartum","translation_bn":"তোমরা কুফরি করো","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19549,"position":5,"text_uthmani":"يَوْمًۭا","transliteration":"yawman","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":19550,"position":6,"text_uthmani":"يَجْعَلُ","transliteration":"yajʿalu","translation_bn":"বানিয়ে দিবে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19551,"position":7,"text_uthmani":"ٱلْوِلْدَٰنَ","transliteration":"l-wil''dāna","translation_bn":"বালকদেরকে","root":"ولد","lemma":"وَلِيد","grammar_bn":"শব্দ"},{"id":19552,"position":8,"text_uthmani":"شِيبًا","transliteration":"shīban","translation_bn":"বৃদ্ধ","root":"شيب","lemma":"شِيب","grammar_bn":"বিশেষ্য (Noun)"},{"id":19553,"position":9,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'fakayfa tattaqūna in kafartum yawman yajʿalu l-wil''dāna shīban', 'অতএব তোমরা যদি (এই রসূলকে) অস্বীকার কর, তাহলে তোমরা কীভাবে সেদিন আত্মরক্ষা করবে যেদিনটি (তার ভীষণতা ও ভয়াবহতায়) বালককে ক’রে দেবে বুড়ো।', 'Then how can you fear, if you disbelieve, a Day that will make the children white- haired?', 'অতএব তোমরা যদি (এই রসূলকে) অস্বীকার কর, তাহলে তোমরা কীভাবে সেদিন আত্মরক্ষা করবে যেদিনটি (তার ভীষণতা ও ভয়াবহতায়) বালককে ক’রে দেবে বুড়ো।', 'Then how can you fear, if you disbelieve, a Day that will make the children white- haired?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073017.mp3', now()),
  (73, 18, '', '[{"id":21122,"position":1,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"al-samāu","translation_bn":"আসমান","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":21123,"position":2,"text_uthmani":"مُنفَطِرٌۢ","transliteration":"munfaṭirun","translation_bn":"বিদীর্ণ হবে","root":"فطر","lemma":"مُنفَطِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":21124,"position":3,"text_uthmani":"بِهِۦ ۚ","transliteration":"bihi","translation_bn":"এর সাথে","root":"—","lemma":"بِهِۦ ۚ","grammar_bn":"অব্যয় (Preposition)"},{"id":21126,"position":4,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21127,"position":5,"text_uthmani":"وَعْدُهُۥ","transliteration":"waʿduhu","translation_bn":"তার ওয়াদা","root":"وعد","lemma":"وَعْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21128,"position":6,"text_uthmani":"مَفْعُولًا","transliteration":"mafʿūlan","translation_bn":"বাস্তবায়িত","root":"فعل","lemma":"مَفْعُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":21129,"position":7,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'al-samāu munfaṭirun bihi kāna waʿduhu mafʿūlan', 'যার কারণে আকাশ ফেটে যাবে, আল্লাহর ওয়া‘দা পূর্ণ হয়ে যাবে।', 'The heaven will break apart therefrom; ever is His promise fulfilled.', 'যার কারণে আকাশ ফেটে যাবে, আল্লাহর ওয়া‘দা পূর্ণ হয়ে যাবে।', 'The heaven will break apart therefrom; ever is His promise fulfilled.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073018.mp3', now()),
  (73, 19, '', '[{"id":21685,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":21686,"position":2,"text_uthmani":"هَـٰذِهِۦ","transliteration":"hādhihi","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":21687,"position":3,"text_uthmani":"تَذْكِرَةٌۭ ۖ","transliteration":"tadhkiratun","translation_bn":"উপদেশ","root":"ذكر","lemma":"تَذْكِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":21689,"position":4,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"সে অতএব","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":21690,"position":5,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছা করে","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21691,"position":6,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"ধরবে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21692,"position":7,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21693,"position":8,"text_uthmani":"رَبِّهِۦ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21694,"position":9,"text_uthmani":"سَبِيلًا","transliteration":"sabīlan","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":21695,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhihi tadhkiratun faman shāa ittakhadha ilā rabbihi sabīlan', 'এটা উপদেশ। কাজেই যার মন চায় সে তার প্রতিপালকের দিকে পথ ধরুক।', 'Indeed, this is a reminder, so whoever wills may take to his Lord a way.', 'এটা উপদেশ। কাজেই যার মন চায় সে তার প্রতিপালকের দিকে পথ ধরুক।', 'Indeed, this is a reminder, so whoever wills may take to his Lord a way.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/073019.mp3', now()),
