  (74, 1, '', '[{"id":631,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":632,"position":2,"text_uthmani":"ٱلْمُدَّثِّرُ","transliteration":"l-mudathiru","translation_bn":"চাদরাবৃত","root":"دثر","lemma":"مُدَّثِّر","grammar_bn":"শব্দ"},{"id":633,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-mudathiru', 'ওহে বস্ত্র আবৃত (ব্যক্তি)!', 'O you who covers himself [with a garment],', 'ওহে বস্ত্র আবৃত (ব্যক্তি)!', 'O you who covers himself [with a garment],', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074001.mp3', now()),
