  (74, 3, '', '[{"id":2622,"position":1,"text_uthmani":"وَرَبَّكَ","transliteration":"warabbaka","translation_bn":"ও তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2623,"position":2,"text_uthmani":"فَكَبِّرْ","transliteration":"fakabbir","translation_bn":"অতঃপর শ্রেষ্ঠত্ব ঘোষণা কর","root":"كبر","lemma":"كَبِّرْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2624,"position":3,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'warabbaka fakabbir', 'আর তোমার প্রতিপালকের শ্রেষ্ঠত্ব ঘোষণা কর।', 'And your Lord glorify', 'আর তোমার প্রতিপালকের শ্রেষ্ঠত্ব ঘোষণা কর।', 'And your Lord glorify', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074003.mp3', now()),
  (74, 4, '', '[{"id":4045,"position":1,"text_uthmani":"وَثِيَابَكَ","transliteration":"wathiyābaka","translation_bn":"এবং তোমার কাপড়","root":"ثوب","lemma":"ثِيَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4046,"position":2,"text_uthmani":"فَطَهِّرْ","transliteration":"faṭahhir","translation_bn":"অতঃপর পবিত্র কর","root":"طهر","lemma":"طَهَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4047,"position":3,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wathiyābaka faṭahhir', 'তোমার পোশাক পরিচ্ছদ পবিত্র রাখ।', 'And your clothing purify', 'তোমার পোশাক পরিচ্ছদ পবিত্র রাখ।', 'And your clothing purify', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074004.mp3', now()),
