  (74, 50, '', '[{"id":48675,"position":1,"text_uthmani":"كَأَنَّهُمْ","transliteration":"ka-annahum","translation_bn":"তারা যেন","root":"—","lemma":"كَأَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":48676,"position":2,"text_uthmani":"حُمُرٌۭ","transliteration":"ḥumurun","translation_bn":"গর্দভসমূহ","root":"حمر","lemma":"حِمَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":48677,"position":3,"text_uthmani":"مُّسْتَنفِرَةٌۭ","transliteration":"mus''tanfiratun","translation_bn":"ভীতত্রস্ত","root":"نفر","lemma":"مُّسْتَنفِرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":48678,"position":4,"text_uthmani":"٥٠","transliteration":"","translation_bn":"(৫০)","root":"—","lemma":"٥٠","grammar_bn":"মার্কার"}]'::jsonb, 'ka-annahum ḥumurun mus''tanfiratun', 'তারা যেন ভয়ে সন্ত্রস্ত গাধা,', 'As if they were alarmed donkeys', 'তারা যেন ভয়ে সন্ত্রস্ত গাধা,', 'As if they were alarmed donkeys', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074050.mp3', now()),
  (74, 51, '', '[{"id":49281,"position":1,"text_uthmani":"فَرَّتْ","transliteration":"farrat","translation_bn":"পলায়ন করছে","root":"فرر","lemma":"فَرَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49282,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49283,"position":3,"text_uthmani":"قَسْوَرَةٍۭ","transliteration":"qaswaratin","translation_bn":"সিংহ","root":"قسر","lemma":"قَسْوَرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":49284,"position":4,"text_uthmani":"٥١","transliteration":"","translation_bn":"(৫১)","root":"—","lemma":"٥١","grammar_bn":"মার্কার"}]'::jsonb, 'farrat min qaswaratin', 'সিংহের সামনে থেকে পালাচ্ছে।', 'Fleeing from a lion?', 'সিংহের সামনে থেকে পালাচ্ছে।', 'Fleeing from a lion?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074051.mp3', now()),
  (74, 52, '', '[{"id":49933,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":49934,"position":2,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"চায়","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":49935,"position":3,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"প্রত্যেক","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49936,"position":4,"text_uthmani":"ٱمْرِئٍۢ","transliteration":"im''ri-in","translation_bn":"ব্যক্তি","root":"مرا","lemma":"ٱمْرِئ","grammar_bn":"বিশেষ্য (Noun)"},{"id":49937,"position":5,"text_uthmani":"مِّنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":49938,"position":6,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":49939,"position":7,"text_uthmani":"يُؤْتَىٰ","transliteration":"yu''tā","translation_bn":"দেয়া হোক","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":49940,"position":8,"text_uthmani":"صُحُفًۭا","transliteration":"ṣuḥufan","translation_bn":"গ্রন্থসমূহ","root":"صحف","lemma":"صُحُف","grammar_bn":"বিশেষ্য (Noun)"},{"id":49941,"position":9,"text_uthmani":"مُّنَشَّرَةًۭ","transliteration":"munasharatan","translation_bn":"উন্মুক্ত","root":"نشر","lemma":"مُّنَشَّرَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":49942,"position":10,"text_uthmani":"٥٢","transliteration":"","translation_bn":"(৫২)","root":"—","lemma":"٥٢","grammar_bn":"মার্কার"}]'::jsonb, 'bal yurīdu kullu im''ri-in min''hum an yu''tā ṣuḥufan munasharatan', 'বস্তুতঃ তাদের প্রত্যেকেই চায়, তাকে (আল্লাহর পক্ষ থেকে) খোলা চিঠি দেয়া হোক (এই মর্মে যে, তোমরা এই নবীকে মেনে নাও)।', 'Rather, every person among them desires that he would be given scriptures spread about.', 'বস্তুতঃ তাদের প্রত্যেকেই চায়, তাকে (আল্লাহর পক্ষ থেকে) খোলা চিঠি দেয়া হোক (এই মর্মে যে, তোমরা এই নবীকে মেনে নাও)।', 'Rather, every person among them desires that he would be given scriptures spread about.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074052.mp3', now()),
  (74, 53, '', '[{"id":50558,"position":1,"text_uthmani":"كَلَّا ۖ","transliteration":"kallā","translation_bn":"কক্ষণও না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":50560,"position":2,"text_uthmani":"بَل","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":50561,"position":3,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":50562,"position":4,"text_uthmani":"يَخَافُونَ","transliteration":"yakhāfūna","translation_bn":"তারা ভয় করে না","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":50563,"position":5,"text_uthmani":"ٱلْـَٔاخِرَةَ","transliteration":"l-ākhirata","translation_bn":"আখেরাতকে","root":"اخر","lemma":"ا^خِر","grammar_bn":"শব্দ"},{"id":50564,"position":6,"text_uthmani":"٥٣","transliteration":"","translation_bn":"(৫৩)","root":"—","lemma":"٥٣","grammar_bn":"মার্কার"}]'::jsonb, 'kallā bal lā yakhāfūna l-ākhirata', 'না, তা কক্ষনো হতে পারে না, বরং (কথা এই যে) তারা আখিরাতকে ভয় করে না।', 'No! But they do not fear the Hereafter.', 'না, তা কক্ষনো হতে পারে না, বরং (কথা এই যে) তারা আখিরাতকে ভয় করে না।', 'No! But they do not fear the Hereafter.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074053.mp3', now()),
  (74, 54, '', '[{"id":51345,"position":1,"text_uthmani":"كَلَّآ","transliteration":"kallā","translation_bn":"কক্ষণও না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":51346,"position":2,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"তা নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":51347,"position":3,"text_uthmani":"تَذْكِرَةٌۭ","transliteration":"tadhkiratun","translation_bn":"উপদেশ","root":"ذكر","lemma":"تَذْكِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":51348,"position":4,"text_uthmani":"٥٤","transliteration":"","translation_bn":"(৫৪)","root":"—","lemma":"٥٤","grammar_bn":"মার্কার"}]'::jsonb, 'kallā innahu tadhkiratun', 'না, তা হতে পারে না, এটা (অর্থাৎ কুরআন সকলের জন্য) উপদেশবাণী।', 'No! Indeed, the Qur''an is a reminder', 'না, তা হতে পারে না, এটা (অর্থাৎ কুরআন সকলের জন্য) উপদেশবাণী।', 'No! Indeed, the Qur''an is a reminder', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074054.mp3', now()),
  (74, 55, '', '[{"id":51729,"position":1,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"যে অতএব","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":51730,"position":2,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছা করে","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51731,"position":3,"text_uthmani":"ذَكَرَهُۥ","transliteration":"dhakarahu","translation_bn":"তার শিক্ষা নিক","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":51732,"position":4,"text_uthmani":"٥٥","transliteration":"","translation_bn":"(৫৫)","root":"—","lemma":"٥٥","grammar_bn":"মার্কার"}]'::jsonb, 'faman shāa dhakarahu', 'এক্ষনে যার ইচ্ছে তাত্থেকে শিক্ষা গ্রহণ করুক।', 'Then whoever wills will remember it.', 'এক্ষনে যার ইচ্ছে তাত্থেকে শিক্ষা গ্রহণ করুক।', 'Then whoever wills will remember it.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074055.mp3', now()),
  (74, 56, '', '[{"id":52267,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":52268,"position":2,"text_uthmani":"يَذْكُرُونَ","transliteration":"yadhkurūna","translation_bn":"তারা শিক্ষা নেবে","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52269,"position":3,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":52270,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":52271,"position":5,"text_uthmani":"يَشَآءَ","transliteration":"yashāa","translation_bn":"ইচ্ছা করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":52272,"position":6,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":52274,"position":7,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তিনিই","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":52275,"position":8,"text_uthmani":"أَهْلُ","transliteration":"ahlu","translation_bn":"যোগ্য","root":"اهل","lemma":"أَهْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":52276,"position":9,"text_uthmani":"ٱلتَّقْوَىٰ","transliteration":"l-taqwā","translation_bn":"ভয়ের","root":"وقي","lemma":"تَقْوَى","grammar_bn":"শব্দ"},{"id":52277,"position":10,"text_uthmani":"وَأَهْلُ","transliteration":"wa-ahlu","translation_bn":"এবং অধিকারী","root":"اهل","lemma":"أَهْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":52278,"position":11,"text_uthmani":"ٱلْمَغْفِرَةِ","transliteration":"l-maghfirati","translation_bn":"মাফ করার","root":"غفر","lemma":"مَّغْفِرَة","grammar_bn":"শব্দ"},{"id":52279,"position":12,"text_uthmani":"٥٦","transliteration":"","translation_bn":"(৫৬)","root":"—","lemma":"٥٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yadhkurūna illā an yashāa l-lahu huwa ahlu l-taqwā wa-ahlu l-maghfirati', 'আল্লাহর ইচ্ছে ব্যতীত কেউ উপদেশ গ্রহণ করবে না, তিনিই ভয়ের যোগ্য, তিনিই ক্ষমা করার অধিকারী।', 'And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness.', 'আল্লাহর ইচ্ছে ব্যতীত কেউ উপদেশ গ্রহণ করবে না, তিনিই ভয়ের যোগ্য, তিনিই ক্ষমা করার অধিকারী।', 'And they will not remember except that Allah wills. He is worthy of fear and adequate for [granting] forgiveness.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/074056.mp3', now())
