VALUES
  (75, 1, '', '[{"id":634,"position":1,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":635,"position":2,"text_uthmani":"أُقْسِمُ","transliteration":"uq''simu","translation_bn":"কসম খাচ্ছি","root":"قسم","lemma":"أَقْسَمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":636,"position":3,"text_uthmani":"بِيَوْمِ","transliteration":"biyawmi","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"অব্যয় (Preposition)"},{"id":637,"position":4,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"কিয়ামাতের","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":638,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'lā uq''simu biyawmi l-qiyāmati', 'আমি কসম করছি ক্বিয়ামতের দিনের,', 'I swear by the Day of Resurrection', 'আমি কসম করছি ক্বিয়ামতের দিনের,', 'I swear by the Day of Resurrection', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075001.mp3', now()),
  (75, 2, '', '[{"id":1616,"position":1,"text_uthmani":"وَلَآ","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1617,"position":2,"text_uthmani":"أُقْسِمُ","transliteration":"uq''simu","translation_bn":"শপথ করছি আমি","root":"قسم","lemma":"أَقْسَمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1618,"position":3,"text_uthmani":"بِٱلنَّفْسِ","transliteration":"bil-nafsi","translation_bn":"মনের","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":1619,"position":4,"text_uthmani":"ٱللَّوَّامَةِ","transliteration":"l-lawāmati","translation_bn":"তিরস্কারকারী","root":"لوم","lemma":"لَّوَّامَة","grammar_bn":"শব্দ"},{"id":1620,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'walā uq''simu bil-nafsi l-lawāmati', 'আমি আরো কসম করছি সেই মনের যে (অন্যায় কাজ ক’রে বসলে) নিজেকে ধিক্কার দেয় (যে তোমাদেরকে অবশ্যই আবার জীবিত করে উঠানো হবে)।', 'And I swear by the reproaching soul [to the certainty of resurrection].', 'আমি আরো কসম করছি সেই মনের যে (অন্যায় কাজ ক’রে বসলে) নিজেকে ধিক্কার দেয় (যে তোমাদেরকে অবশ্যই আবার জীবিত করে উঠানো হবে)।', 'And I swear by the reproaching soul [to the certainty of resurrection].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075002.mp3', now()),
  (75, 3, '', '[{"id":2639,"position":1,"text_uthmani":"أَيَحْسَبُ","transliteration":"ayaḥsabu","translation_bn":"মনে করেছে কি","root":"حسب","lemma":"حَسِبَ","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":2640,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":2641,"position":3,"text_uthmani":"أَلَّن","transliteration":"allan","translation_bn":"কখন না","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":2642,"position":4,"text_uthmani":"نَّجْمَعَ","transliteration":"najmaʿa","translation_bn":"একত্রিত আমরা করব","root":"جمع","lemma":"جَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2643,"position":5,"text_uthmani":"عِظَامَهُۥ","transliteration":"ʿiẓāmahu","translation_bn":"তার অস্তিগুলকে","root":"عظم","lemma":"عَظِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":2644,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'ayaḥsabu l-insānu allan najmaʿa ʿiẓāmahu', 'মানুষ কি মনে করে যে, আমি তার হাড়গুলোকে একত্রিত করতে পারব না।', 'Does man think that We will not assemble his bones?', 'মানুষ কি মনে করে যে, আমি তার হাড়গুলোকে একত্রিত করতে পারব না।', 'Does man think that We will not assemble his bones?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075003.mp3', now()),
  (75, 4, '', '[{"id":4048,"position":1,"text_uthmani":"بَلَىٰ","transliteration":"balā","translation_bn":"কােনো না","root":"—","lemma":"بَلَىٰ\r","grammar_bn":"উত্তর পদ (Answer)"},{"id":4049,"position":2,"text_uthmani":"قَـٰدِرِينَ","transliteration":"qādirīna","translation_bn":"সক্ষম","root":"قدر","lemma":"قَادِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":4050,"position":3,"text_uthmani":"عَلَىٰٓ","transliteration":"ʿalā","translation_bn":"এতে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4051,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":4052,"position":5,"text_uthmani":"نُّسَوِّىَ","transliteration":"nusawwiya","translation_bn":"পূর্ণবিন্যস্ত আমরা করবো","root":"سوي","lemma":"سَوَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4053,"position":6,"text_uthmani":"بَنَانَهُۥ","transliteration":"banānahu","translation_bn":"তার আঙ্গুলির অগ্রভাগ","root":"بنن","lemma":"بَنَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":4054,"position":7,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'balā qādirīna ʿalā an nusawwiya banānahu', 'কেন নয়, আমি তার আঙ্গুলের ডগা পর্যন্ত সঠিকভাবে বানিয়ে দিতে সক্ষম', 'Yes. [We are] Able [even] to proportion his fingertips.', 'কেন নয়, আমি তার আঙ্গুলের ডগা পর্যন্ত সঠিকভাবে বানিয়ে দিতে সক্ষম', 'Yes. [We are] Able [even] to proportion his fingertips.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075004.mp3', now()),
  (75, 5, '', '[{"id":5339,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":5340,"position":2,"text_uthmani":"يُرِيدُ","transliteration":"yurīdu","translation_bn":"চায়ে","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5341,"position":3,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":5342,"position":4,"text_uthmani":"لِيَفْجُرَ","transliteration":"liyafjura","translation_bn":"কুকর্ম করার জন্য","root":"فجر","lemma":"يَفْجُرَ","grammar_bn":"শব্দ"},{"id":5343,"position":5,"text_uthmani":"أَمَامَهُۥ","transliteration":"amāmahu","translation_bn":"তার ভবিষ্যতেও","root":"امم","lemma":"أَمَام","grammar_bn":"কালবাচক (Time)"},{"id":5344,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'bal yurīdu l-insānu liyafjura amāmahu', 'কিন্তু মানুষ তার আগামী দিনগুলোতেও পাপাচার করতে চায়।', 'But man desires to continue in sin.', 'কিন্তু মানুষ তার আগামী দিনগুলোতেও পাপাচার করতে চায়।', 'But man desires to continue in sin.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075005.mp3', now()),
  (75, 6, '', '[{"id":6555,"position":1,"text_uthmani":"يَسْـَٔلُ","transliteration":"yasalu","translation_bn":"সে জিজ্ঞাস করে","root":"سال","lemma":"سَأَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6556,"position":2,"text_uthmani":"أَيَّانَ","transliteration":"ayyāna","translation_bn":"\"কবে","root":"—","lemma":"أَيَّان\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":6557,"position":3,"text_uthmani":"يَوْمُ","transliteration":"yawmu","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":6558,"position":4,"text_uthmani":"ٱلْقِيَـٰمَةِ","transliteration":"l-qiyāmati","translation_bn":"কিয়ামাতের\"","root":"قوم","lemma":"قِيَٰمَة","grammar_bn":"শব্দ"},{"id":6559,"position":5,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yasalu ayyāna yawmu l-qiyāmati', 'সে জিজ্ঞেস করে, ‘ক্বিয়ামত দিবস কবে?’', 'He asks, "When is the Day of Resurrection?"', 'সে জিজ্ঞেস করে, ‘ক্বিয়ামত দিবস কবে?’', 'He asks, "When is the Day of Resurrection?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075006.mp3', now()),
  (75, 7, '', '[{"id":7950,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"যখন অতঃপর","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":7951,"position":2,"text_uthmani":"بَرِقَ","transliteration":"bariqa","translation_bn":"স্থির হয়ে যাবে","root":"برق","lemma":"بَرِقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7952,"position":3,"text_uthmani":"ٱلْبَصَرُ","transliteration":"l-baṣaru","translation_bn":"চক্ষু","root":"بصر","lemma":"بَصَر","grammar_bn":"শব্দ"},{"id":7953,"position":4,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā bariqa l-baṣaru', 'যখন চোখ ধাঁধিয়ে যাবে,', 'So when vision is dazzled', 'যখন চোখ ধাঁধিয়ে যাবে,', 'So when vision is dazzled', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075007.mp3', now()),
  (75, 8, '', '[{"id":8882,"position":1,"text_uthmani":"وَخَسَفَ","transliteration":"wakhasafa","translation_bn":"এবং আলোকহীন হবে","root":"خسف","lemma":"خَسَفَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8883,"position":2,"text_uthmani":"ٱلْقَمَرُ","transliteration":"l-qamaru","translation_bn":"চাঁদ","root":"قمر","lemma":"قَمَر","grammar_bn":"শব্দ"},{"id":8884,"position":3,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wakhasafa l-qamaru', 'চাঁদ হয়ে যাবে আলোকহীন', 'And the moon darkens', 'চাঁদ হয়ে যাবে আলোকহীন', 'And the moon darkens', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075008.mp3', now()),
  (75, 9, '', '[{"id":10117,"position":1,"text_uthmani":"وَجُمِعَ","transliteration":"wajumiʿa","translation_bn":"এবং একত্রিত করা হবে","root":"جمع","lemma":"جَمَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10118,"position":2,"text_uthmani":"ٱلشَّمْسُ","transliteration":"l-shamsu","translation_bn":"সূর্য","root":"شمس","lemma":"شَمْس","grammar_bn":"শব্দ"},{"id":10119,"position":3,"text_uthmani":"وَٱلْقَمَرُ","transliteration":"wal-qamaru","translation_bn":"ও চাঁদ","root":"قمر","lemma":"قَمَر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10120,"position":4,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'wajumiʿa l-shamsu wal-qamaru', 'সুরুজ আর চাঁদকে একত্রে জুড়ে দেয়া হবে,', 'And the sun and the moon are joined,', 'সুরুজ আর চাঁদকে একত্রে জুড়ে দেয়া হবে,', 'And the sun and the moon are joined,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075009.mp3', now()),
  (75, 10, '', '[{"id":11556,"position":1,"text_uthmani":"يَقُولُ","transliteration":"yaqūlu","translation_bn":"বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11557,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":11558,"position":3,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেই দিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":11559,"position":4,"text_uthmani":"أَيْنَ","transliteration":"ayna","translation_bn":"\"কোথায়","root":"—","lemma":"أَيْن\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":11560,"position":5,"text_uthmani":"ٱلْمَفَرُّ","transliteration":"l-mafaru","translation_bn":"পালাবার জায়গা\"","root":"فرر","lemma":"مَفَرّ","grammar_bn":"শব্দ"},{"id":11561,"position":6,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'yaqūlu l-insānu yawma-idhin ayna l-mafaru', 'সেদিন মানুষ বলবে- ‘আজ পালানোর জায়গা কোথায়?’', 'Man will say on that Day, "Where is the [place of] escape?"', 'সেদিন মানুষ বলবে- ‘আজ পালানোর জায়গা কোথায়?’', 'Man will say on that Day, "Where is the [place of] escape?"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075010.mp3', now()),
  (75, 11, '', '[{"id":12877,"position":1,"text_uthmani":"كَلَّا","transliteration":"kallā","translation_bn":"কক্ষন না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":12878,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"নাই","root":"—","lemma":"لَا","grammar_bn":"না-বোধক (Negative)"},{"id":12879,"position":3,"text_uthmani":"وَزَرَ","transliteration":"wazara","translation_bn":"আশ্রয় স্থল","root":"وزر","lemma":"وَزَر","grammar_bn":"বিশেষ্য (Noun)"},{"id":12880,"position":4,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'kallā lā wazara', 'মোটেই না, আশ্রয়ের কোন জায়গা নেই।', 'No! There is no refuge.', 'মোটেই না, আশ্রয়ের কোন জায়গা নেই।', 'No! There is no refuge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075011.mp3', now()),
  (75, 12, '', '[{"id":14131,"position":1,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14132,"position":2,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":14133,"position":3,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":14134,"position":4,"text_uthmani":"ٱلْمُسْتَقَرُّ","transliteration":"l-mus''taqaru","translation_bn":"অবস্থানহল","root":"قرر","lemma":"مُسْتَقَرّ","grammar_bn":"শব্দ"},{"id":14135,"position":5,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'ilā rabbika yawma-idhin l-mus''taqaru', 'সেদিন ঠাঁই হবে (একমাত্র) তোমার প্রতিপালকেরই নিকট।', 'To your Lord, that Day, is the [place of] permanence.', 'সেদিন ঠাঁই হবে (একমাত্র) তোমার প্রতিপালকেরই নিকট।', 'To your Lord, that Day, is the [place of] permanence.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075012.mp3', now()),
  (75, 13, '', '[{"id":15260,"position":1,"text_uthmani":"يُنَبَّؤُا۟","transliteration":"yunabba-u","translation_bn":"জানিয়ে দেয়া হবে","root":"نبا","lemma":"نَبَّأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15261,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ কে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":15262,"position":3,"text_uthmani":"يَوْمَئِذٍۭ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":15263,"position":4,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা ওই বিষয়ে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15264,"position":5,"text_uthmani":"قَدَّمَ","transliteration":"qaddama","translation_bn":"সে আগে পাঠিয়েছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15265,"position":6,"text_uthmani":"وَأَخَّرَ","transliteration":"wa-akhara","translation_bn":"এবং পিছে ছেড়েছে","root":"اخر","lemma":"أَخَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15266,"position":7,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'yunabba-u l-insānu yawma-idhin bimā qaddama wa-akhara', 'সেদিন মানুষকে জানিয়ে দেয়া হবে সে কী (‘আমাল) আগে পাঠিয়েছে আর কী পেছনে ছেড়ে এসেছে।', 'Man will be informed that Day of what he sent ahead and kept back.', 'সেদিন মানুষকে জানিয়ে দেয়া হবে সে কী (‘আমাল) আগে পাঠিয়েছে আর কী পেছনে ছেড়ে এসেছে।', 'Man will be informed that Day of what he sent ahead and kept back.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075013.mp3', now()),
  (75, 14, '', '[{"id":16283,"position":1,"text_uthmani":"بَلِ","transliteration":"bali","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":16284,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":16285,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"সম্পর্কে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16286,"position":4,"text_uthmani":"نَفْسِهِۦ","transliteration":"nafsihi","translation_bn":"তার নিজের","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":16287,"position":5,"text_uthmani":"بَصِيرَةٌۭ","transliteration":"baṣīratun","translation_bn":"খুব অবগত","root":"بصر","lemma":"بَصِيرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":16288,"position":6,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'bali l-insānu ʿalā nafsihi baṣīratun', 'আসলে মানুষ নিজেই নিজের সম্পর্কে চাক্ষুসভাবে অবগত।', 'Rather, man, against himself, will be a witness,', 'আসলে মানুষ নিজেই নিজের সম্পর্কে চাক্ষুসভাবে অবগত।', 'Rather, man, against himself, will be a witness,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075014.mp3', now()),
  (75, 15, '', '[{"id":17471,"position":1,"text_uthmani":"وَلَوْ","transliteration":"walaw","translation_bn":"এবং যদিও","root":"—","lemma":"لَو\r","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":17472,"position":2,"text_uthmani":"أَلْقَىٰ","transliteration":"alqā","translation_bn":"পেশ করে সে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":17473,"position":3,"text_uthmani":"مَعَاذِيرَهُۥ","transliteration":"maʿādhīrahu","translation_bn":"তার অজুহাত সমূহ","root":"عذر","lemma":"مَعَاذِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":17474,"position":4,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'walaw alqā maʿādhīrahu', 'যদিও সে নানান অজুহাত পেশ করে।', 'Even if he presents his excuses.', 'যদিও সে নানান অজুহাত পেশ করে।', 'Even if he presents his excuses.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075015.mp3', now()),
  (75, 16, '', '[{"id":18555,"position":1,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"নিষেধবাচক (Prohibition)"},{"id":18556,"position":2,"text_uthmani":"تُحَرِّكْ","transliteration":"tuḥarrik","translation_bn":"নাড়াবে","root":"حرك","lemma":"تُحَرِّكْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18557,"position":3,"text_uthmani":"بِهِۦ","transliteration":"bihi","translation_bn":"এর সাথে","root":"—","lemma":"بِهِۦ","grammar_bn":"অব্যয় (Preposition)"},{"id":18558,"position":4,"text_uthmani":"لِسَانَكَ","transliteration":"lisānaka","translation_bn":"তোমার জিহ্বা","root":"لسن","lemma":"لِسَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":18559,"position":5,"text_uthmani":"لِتَعْجَلَ","transliteration":"litaʿjala","translation_bn":"তাড়াতাড়ির জন্য","root":"عجل","lemma":"عَجِلَ","grammar_bn":"শব্দ"},{"id":18560,"position":6,"text_uthmani":"بِهِۦٓ","transliteration":"bihi","translation_bn":"এর সাথে","root":"—","lemma":"بِهِۦٓ","grammar_bn":"অব্যয় (Preposition)"},{"id":18561,"position":7,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'lā tuḥarrik bihi lisānaka litaʿjala bihi', '(এ সূরাহ অবতীর্ণ হওয়ার সময় আল্লাহর রসূল তা মুখস্থ করার জন্য ব্যস্ত হয়ে পড়লে আল্লাহ অভয় দিয়ে বললেন) তুমি তাড়াতাড়ি ওয়াহী আয়ত্ত করার জন্য তোমার জিভ নাড়াবে না।', 'Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur''an.', '(এ সূরাহ অবতীর্ণ হওয়ার সময় আল্লাহর রসূল তা মুখস্থ করার জন্য ব্যস্ত হয়ে পড়লে আল্লাহ অভয় দিয়ে বললেন) তুমি তাড়াতাড়ি ওয়াহী আয়ত্ত করার জন্য তোমার জিভ নাড়াবে না।', 'Move not your tongue with it, [O Muhammad], to hasten with recitation of the Qur''an.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075016.mp3', now()),
  (75, 17, '', '[{"id":19557,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":19558,"position":2,"text_uthmani":"عَلَيْنَا","transliteration":"ʿalaynā","translation_bn":"আমাদের দায়িত্ব","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":19559,"position":3,"text_uthmani":"جَمْعَهُۥ","transliteration":"jamʿahu","translation_bn":"তা মুখস্ত করান","root":"جمع","lemma":"جَمْع","grammar_bn":"বিশেষ্য (Noun)"},{"id":19560,"position":4,"text_uthmani":"وَقُرْءَانَهُۥ","transliteration":"waqur''ānahu","translation_bn":"এবং তা পাঠ করান","root":"قرا","lemma":"قُرْءَان","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19561,"position":5,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'inna ʿalaynā jamʿahu waqur''ānahu', 'এর সংরক্ষণ ও পড়ানোর দায়িত্ব আমারই।', 'Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.', 'এর সংরক্ষণ ও পড়ানোর দায়িত্ব আমারই।', 'Indeed, upon Us is its collection [in your heart] and [to make possible] its recitation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075017.mp3', now()),
  (75, 18, '', '[{"id":20644,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"যখন অতঃপর","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":20645,"position":2,"text_uthmani":"قَرَأْنَـٰهُ","transliteration":"qaranāhu","translation_bn":"তা আমরা পড়ি","root":"قرا","lemma":"قَرَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20646,"position":3,"text_uthmani":"فَٱتَّبِعْ","transliteration":"fa-ittabiʿ","translation_bn":"অনিুসরণ তখন করো","root":"تبع","lemma":"ٱتَّبَعَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":20647,"position":4,"text_uthmani":"قُرْءَانَهُۥ","transliteration":"qur''ānahu","translation_bn":"তা পাঠের","root":"قرا","lemma":"قُرْءَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":20648,"position":5,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā qaranāhu fa-ittabiʿ qur''ānahu', 'কাজেই আমি যখন তা পাঠ করি, তখন তুমি সে পাঠের অনুসরণ কর।', 'So when We have recited it [through Gabriel], then follow its recitation.', 'কাজেই আমি যখন তা পাঠ করি, তখন তুমি সে পাঠের অনুসরণ কর।', 'So when We have recited it [through Gabriel], then follow its recitation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075018.mp3', now()),
