  (75, 22, '', '[{"id":24917,"position":1,"text_uthmani":"وُجُوهٌۭ","transliteration":"wujūhun","translation_bn":"কিছুু মুখ","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":24918,"position":2,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সে দিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":24919,"position":3,"text_uthmani":"نَّاضِرَةٌ","transliteration":"nāḍiratun","translation_bn":"উজ্জ্বল হবে","root":"نضر","lemma":"نَّاضِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":24920,"position":4,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'wujūhun yawma-idhin nāḍiratun', 'কতক মুখ সেদিন উজ্জ্বল হবে।', '[Some] faces, that Day, will be radiant,', 'কতক মুখ সেদিন উজ্জ্বল হবে।', '[Some] faces, that Day, will be radiant,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075022.mp3', now()),
