  (75, 24, '', '[{"id":27414,"position":1,"text_uthmani":"وَوُجُوهٌۭ","transliteration":"wawujūhun","translation_bn":"এবং কিছু মুখ","root":"وجه","lemma":"وَجْه","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27415,"position":2,"text_uthmani":"يَوْمَئِذٍۭ","transliteration":"yawma-idhin","translation_bn":"সে দিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":27416,"position":3,"text_uthmani":"بَاسِرَةٌۭ","transliteration":"bāsiratun","translation_bn":"স্লান হবে","root":"بسر","lemma":"بَاسِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27417,"position":4,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wawujūhun yawma-idhin bāsiratun', 'কতক মুখ সেদিন বিবর্ণ হবে।', 'And [some] faces, that Day, will be contorted,', 'কতক মুখ সেদিন বিবর্ণ হবে।', 'And [some] faces, that Day, will be contorted,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075024.mp3', now()),
  (75, 25, '', '[{"id":27962,"position":1,"text_uthmani":"تَظُنُّ","transliteration":"taẓunnu","translation_bn":"ধারণা করবে","root":"ظنن","lemma":"ظَنَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27963,"position":2,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":27964,"position":3,"text_uthmani":"يُفْعَلَ","transliteration":"yuf''ʿala","translation_bn":"করা হবে","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27965,"position":4,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"তার সাথে","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":27966,"position":5,"text_uthmani":"فَاقِرَةٌۭ","transliteration":"fāqiratun","translation_bn":"কোমর চূর্ণ আচরণ","root":"فقر","lemma":"فَاقِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27967,"position":6,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'taẓunnu an yuf''ʿala bihā fāqiratun', 'তারা ধারণা করবে যে, তাদের সঙ্গে কোমর-ভাঙ্গা আচরণ করা হবে।', 'Expecting that there will be done to them [something] backbreaking.', 'তারা ধারণা করবে যে, তাদের সঙ্গে কোমর-ভাঙ্গা আচরণ করা হবে।', 'Expecting that there will be done to them [something] backbreaking.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/075025.mp3', now()),
