  (76, 1, '', '[{"id":639,"position":1,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":640,"position":2,"text_uthmani":"أَتَىٰ","transliteration":"atā","translation_bn":"এসেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":641,"position":3,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":642,"position":4,"text_uthmani":"ٱلْإِنسَـٰنِ","transliteration":"l-insāni","translation_bn":"মানুষের","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":643,"position":5,"text_uthmani":"حِينٌۭ","transliteration":"ḥīnun","translation_bn":"এক সময়","root":"حين","lemma":"حِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":644,"position":6,"text_uthmani":"مِّنَ","transliteration":"mina","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":645,"position":7,"text_uthmani":"ٱلدَّهْرِ","transliteration":"l-dahri","translation_bn":"সীমাহীন কালের","root":"دهر","lemma":"دَّهْر","grammar_bn":"শব্দ"},{"id":646,"position":8,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"না","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":647,"position":9,"text_uthmani":"يَكُن","transliteration":"yakun","translation_bn":"সে ছিল","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":648,"position":10,"text_uthmani":"شَيْـًۭٔا","transliteration":"shayan","translation_bn":"কিছুই","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":649,"position":11,"text_uthmani":"مَّذْكُورًا","transliteration":"madhkūran","translation_bn":"উল্লেখযোগ্য","root":"ذكر","lemma":"مَّذْكُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":650,"position":12,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'hal atā ʿalā l-insāni ḥīnun mina l-dahri lam yakun shayan madhkūran', 'মহাকালের মধ্য হতে মানুষের উপর কি এমন একটা সময় অতিবাহিত হয়নি যখন সে উল্লেখ করার যোগ্য কোন বস্তুই ছিল না?', 'Has there [not] come upon man a period of time when he was not a thing [even] mentioned?', 'মহাকালের মধ্য হতে মানুষের উপর কি এমন একটা সময় অতিবাহিত হয়নি যখন সে উল্লেখ করার যোগ্য কোন বস্তুই ছিল না?', 'Has there [not] come upon man a period of time when he was not a thing [even] mentioned?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076001.mp3', now()),
  (76, 2, '', '[{"id":1621,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1622,"position":2,"text_uthmani":"خَلَقْنَا","transliteration":"khalaqnā","translation_bn":"আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1623,"position":3,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষকে","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":1624,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1625,"position":5,"text_uthmani":"نُّطْفَةٍ","transliteration":"nuṭ''fatin","translation_bn":"শুক্রের ফোটা","root":"نطف","lemma":"نُّطْفَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":1626,"position":6,"text_uthmani":"أَمْشَاجٍۢ","transliteration":"amshājin","translation_bn":"মিশ্রিত","root":"مشج","lemma":"أَمْشَاج","grammar_bn":"বিশেষণ (Adjective)"},{"id":1627,"position":7,"text_uthmani":"نَّبْتَلِيهِ","transliteration":"nabtalīhi","translation_bn":"তাকে পরীক্ষা আমরা করবো","root":"بلو","lemma":"ٱبْتَلَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":1628,"position":8,"text_uthmani":"فَجَعَلْنَـٰهُ","transliteration":"fajaʿalnāhu","translation_bn":"অতঃপর তাকে আমরা বানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1629,"position":9,"text_uthmani":"سَمِيعًۢا","transliteration":"samīʿan","translation_bn":"শ্রবণ শক্তি সম্পন্ন","root":"سمع","lemma":"سَمِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":1630,"position":10,"text_uthmani":"بَصِيرًا","transliteration":"baṣīran","translation_bn":"দৃষ্টি শক্তি সম্পন্ন","root":"بصر","lemma":"بَصِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":1631,"position":11,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'innā khalaqnā l-insāna min nuṭ''fatin amshājin nabtalīhi fajaʿalnāhu samīʿan baṣīran', 'আমি মানুষকে সৃষ্টি করেছি সংমিশ্রিত শুক্রবিন্দু থেকে তাকে পরীক্ষা করার জন্য, এজন্য তাকে করেছি শ্রবণশক্তি ও দৃষ্টিশক্তির অধিকারী।', 'Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing.', 'আমি মানুষকে সৃষ্টি করেছি সংমিশ্রিত শুক্রবিন্দু থেকে তাকে পরীক্ষা করার জন্য, এজন্য তাকে করেছি শ্রবণশক্তি ও দৃষ্টিশক্তির অধিকারী।', 'Indeed, We created man from a sperm-drop mixture that We may try him; and We made him hearing and seeing.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076002.mp3', now()),
  (76, 3, '', '[{"id":2751,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2752,"position":2,"text_uthmani":"هَدَيْنَـٰهُ","transliteration":"hadaynāhu","translation_bn":"তাকে আমরা দেখিয়েছি","root":"هدي","lemma":"هَدَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":2753,"position":3,"text_uthmani":"ٱلسَّبِيلَ","transliteration":"l-sabīla","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"শব্দ"},{"id":2754,"position":4,"text_uthmani":"إِمَّا","transliteration":"immā","translation_bn":"হয়","root":"—","lemma":"إِمَّا\r","grammar_bn":"শব্দ"},{"id":2755,"position":5,"text_uthmani":"شَاكِرًۭا","transliteration":"shākiran","translation_bn":"শুকুর কারি হবে","root":"شكر","lemma":"شَاكِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2756,"position":6,"text_uthmani":"وَإِمَّا","transliteration":"wa-immā","translation_bn":"আর না হয়","root":"—","lemma":"إِمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2757,"position":7,"text_uthmani":"كَفُورًا","transliteration":"kafūran","translation_bn":"অকৃতজ্ঞ হবে","root":"كفر","lemma":"كَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":2758,"position":8,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'innā hadaynāhu l-sabīla immā shākiran wa-immā kafūran', 'আমি তাকে পথ দেখিয়ে দিয়েছি, হয় সে কৃতজ্ঞ হবে, না হয় সে অকৃতজ্ঞ হবে।', 'Indeed, We guided him to the way, be he grateful or be he ungrateful.', 'আমি তাকে পথ দেখিয়ে দিয়েছি, হয় সে কৃতজ্ঞ হবে, না হয় সে অকৃতজ্ঞ হবে।', 'Indeed, We guided him to the way, be he grateful or be he ungrateful.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076003.mp3', now()),
  (76, 4, '', '[{"id":4055,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"আমরা নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":4056,"position":2,"text_uthmani":"أَعْتَدْنَا","transliteration":"aʿtadnā","translation_bn":"আমরা প্রস্তুত","root":"عتد","lemma":"أَعْتَدَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4057,"position":3,"text_uthmani":"لِلْكَـٰفِرِينَ","transliteration":"lil''kāfirīna","translation_bn":"কাফির দের জন্যে","root":"كفر","lemma":"كَٰفِرُون","grammar_bn":"অব্যয় (Preposition)"},{"id":4058,"position":4,"text_uthmani":"سَلَـٰسِلَا۟","transliteration":"salāsilā","translation_bn":"শিকলসমূহ","root":"سلسل","lemma":"سِلْسِلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4059,"position":5,"text_uthmani":"وَأَغْلَـٰلًۭا","transliteration":"wa-aghlālan","translation_bn":"এবং গলারবেড়ী সমূহ","root":"غلل","lemma":"غِلّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4060,"position":6,"text_uthmani":"وَسَعِيرًا","transliteration":"wasaʿīran","translation_bn":"এবং প্রজ্জলিত আগুন","root":"سعر","lemma":"سَعِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4061,"position":7,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'innā aʿtadnā lil''kāfirīna salāsilā wa-aghlālan wasaʿīran', 'আমি (অকৃতজ্ঞ) কাফিরদের জন্য প্রস্তুত করে রেখেছি শেকল, বেড়ি আর জ্বলন্ত আগুন।', 'Indeed, We have prepared for the disbelievers chains and shackles and a blaze.', 'আমি (অকৃতজ্ঞ) কাফিরদের জন্য প্রস্তুত করে রেখেছি শেকল, বেড়ি আর জ্বলন্ত আগুন।', 'Indeed, We have prepared for the disbelievers chains and shackles and a blaze.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076004.mp3', now()),
  (76, 5, '', '[{"id":5392,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":5393,"position":2,"text_uthmani":"ٱلْأَبْرَارَ","transliteration":"l-abrāra","translation_bn":"নেক বান্দারা","root":"برر","lemma":"بَرّ","grammar_bn":"শব্দ"},{"id":5394,"position":3,"text_uthmani":"يَشْرَبُونَ","transliteration":"yashrabūna","translation_bn":"পান করবে","root":"شرب","lemma":"شَرِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5395,"position":4,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5396,"position":5,"text_uthmani":"كَأْسٍۢ","transliteration":"kasin","translation_bn":"পেয়ালা","root":"كاس","lemma":"كَأْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":5397,"position":6,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5398,"position":7,"text_uthmani":"مِزَاجُهَا","transliteration":"mizājuhā","translation_bn":"তার সংমিশ্রণ","root":"مزج","lemma":"مِزَاج","grammar_bn":"বিশেষ্য (Noun)"},{"id":5399,"position":8,"text_uthmani":"كَافُورًا","transliteration":"kāfūran","translation_bn":"কর্পূরের","root":"كفر","lemma":"كَافُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":5400,"position":9,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-abrāra yashrabūna min kasin kāna mizājuhā kāfūran', '(অপরদিকে) নেককার লোকেরা এমন পানপাত্র থেকে পান করবে যাতে কর্পুরের সংমিশ্রণ থাকবে।', 'Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kafur,', '(অপরদিকে) নেককার লোকেরা এমন পানপাত্র থেকে পান করবে যাতে কর্পুরের সংমিশ্রণ থাকবে।', 'Indeed, the righteous will drink from a cup [of wine] whose mixture is of Kafur,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076005.mp3', now()),
  (76, 6, '', '[{"id":6625,"position":1,"text_uthmani":"عَيْنًۭا","transliteration":"ʿaynan","translation_bn":"একটি ঝর্না","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":6626,"position":2,"text_uthmani":"يَشْرَبُ","transliteration":"yashrabu","translation_bn":"পান করবে","root":"شرب","lemma":"شَرِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6627,"position":3,"text_uthmani":"بِهَا","transliteration":"bihā","translation_bn":"তা থেকে","root":"—","lemma":"بِهَا","grammar_bn":"অব্যয় (Preposition)"},{"id":6628,"position":4,"text_uthmani":"عِبَادُ","transliteration":"ʿibādu","translation_bn":"বান্দারা","root":"عبد","lemma":"عَبْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":6629,"position":5,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6630,"position":6,"text_uthmani":"يُفَجِّرُونَهَا","transliteration":"yufajjirūnahā","translation_bn":"তাকে তারা প্রবাহিত করবে","root":"فجر","lemma":"فُجِّرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6631,"position":7,"text_uthmani":"تَفْجِيرًۭا","transliteration":"tafjīran","translation_bn":"প্রবাহিত(যথা ইচ্ছা)","root":"فجر","lemma":"تَفْجِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":6632,"position":8,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'ʿaynan yashrabu bihā ʿibādu l-lahi yufajjirūnahā tafjīran', 'আল্লাহর বান্দারা একটি ঝর্ণা থেকে পান করবে। তারা এই ঝর্ণাকে (তাদের) ইচ্ছেমত প্রবাহিত করবে।', 'A spring of which the [righteous] servants of Allah will drink; they will make it gush forth in force [and abundance].', 'আল্লাহর বান্দারা একটি ঝর্ণা থেকে পান করবে। তারা এই ঝর্ণাকে (তাদের) ইচ্ছেমত প্রবাহিত করবে।', 'A spring of which the [righteous] servants of Allah will drink; they will make it gush forth in force [and abundance].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076006.mp3', now()),
  (76, 7, '', '[{"id":7959,"position":1,"text_uthmani":"يُوفُونَ","transliteration":"yūfūna","translation_bn":"তারা পূর্ণ করে","root":"وفي","lemma":"أَوْفَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7960,"position":2,"text_uthmani":"بِٱلنَّذْرِ","transliteration":"bil-nadhri","translation_bn":"মানতকে","root":"نذر","lemma":"نَّذْر","grammar_bn":"অব্যয় (Preposition)"},{"id":7961,"position":3,"text_uthmani":"وَيَخَافُونَ","transliteration":"wayakhāfūna","translation_bn":"এবং তারা ভয় করে","root":"خوف","lemma":"خَافَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7962,"position":4,"text_uthmani":"يَوْمًۭا","transliteration":"yawman","translation_bn":"একদিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":7963,"position":5,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7964,"position":6,"text_uthmani":"شَرُّهُۥ","transliteration":"sharruhu","translation_bn":"তার বিপত্তি","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":7965,"position":7,"text_uthmani":"مُسْتَطِيرًۭا","transliteration":"mus''taṭīran","translation_bn":"সর্বত্রবিস্ত্রিত","root":"طير","lemma":"مُسْتَطِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":7966,"position":8,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'yūfūna bil-nadhri wayakhāfūna yawman kāna sharruhu mus''taṭīran', 'যারা মানত পূরণ করে আর সেই দিনকে ভয় করে যার অনিষ্ট হবে সুদূরপ্রসারী।', 'They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread.', 'যারা মানত পূরণ করে আর সেই দিনকে ভয় করে যার অনিষ্ট হবে সুদূরপ্রসারী।', 'They [are those who] fulfill [their] vows and fear a Day whose evil will be widespread.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076007.mp3', now()),
  (76, 8, '', '[{"id":9123,"position":1,"text_uthmani":"وَيُطْعِمُونَ","transliteration":"wayuṭ''ʿimūna","translation_bn":"এবং তারা খাওয়ায়","root":"طعم","lemma":"أَطْعَمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9124,"position":2,"text_uthmani":"ٱلطَّعَامَ","transliteration":"l-ṭaʿāma","translation_bn":"খাবার","root":"طعم","lemma":"طَعَام","grammar_bn":"শব্দ"},{"id":9125,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"জন্য","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9126,"position":4,"text_uthmani":"حُبِّهِۦ","transliteration":"ḥubbihi","translation_bn":"তাঁর ভালবাসার","root":"حبب","lemma":"حُبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9127,"position":5,"text_uthmani":"مِسْكِينًۭا","transliteration":"mis''kīnan","translation_bn":"অভাবগ্রস্থকে","root":"سكن","lemma":"مِسْكِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":9128,"position":6,"text_uthmani":"وَيَتِيمًۭا","transliteration":"wayatīman","translation_bn":"ও ইয়াতীমকে","root":"يتم","lemma":"يَتِيم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9129,"position":7,"text_uthmani":"وَأَسِيرًا","transliteration":"wa-asīran","translation_bn":"ও বন্দীকে","root":"اسر","lemma":"أَسِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9130,"position":8,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wayuṭ''ʿimūna l-ṭaʿāma ʿalā ḥubbihi mis''kīnan wayatīman wa-asīran', 'আর তারা আল্লাহর প্রতি তাদের ভালবাসার কারণে মিসকীন, ইয়াতীম ও কয়েদীকে খাবার খাওয়ায়।', 'And they give food in spite of love for it to the needy, the orphan, and the captive,', 'আর তারা আল্লাহর প্রতি তাদের ভালবাসার কারণে মিসকীন, ইয়াতীম ও কয়েদীকে খাবার খাওয়ায়।', 'And they give food in spite of love for it to the needy, the orphan, and the captive,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076008.mp3', now()),
  (76, 9, '', '[{"id":10343,"position":1,"text_uthmani":"إِنَّمَا","transliteration":"innamā","translation_bn":"\"মূলত (আর বলে)","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":10344,"position":2,"text_uthmani":"نُطْعِمُكُمْ","transliteration":"nuṭ''ʿimukum","translation_bn":"তোমাাদের আহার্য দেই আমরা","root":"طعم","lemma":"أَطْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10345,"position":3,"text_uthmani":"لِوَجْهِ","transliteration":"liwajhi","translation_bn":"সন্তুষ্টির জন্যে","root":"وجه","lemma":"وَجْه","grammar_bn":"অব্যয় (Preposition)"},{"id":10346,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহ্‌র","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":10347,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":10348,"position":6,"text_uthmani":"نُرِيدُ","transliteration":"nurīdu","translation_bn":"চাই আমরা","root":"رود","lemma":"أَرَادَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10349,"position":7,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"তোমাদের থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10350,"position":8,"text_uthmani":"جَزَآءًۭ","transliteration":"jazāan","translation_bn":"প্রতিদান","root":"جزي","lemma":"جَزَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":10351,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10352,"position":10,"text_uthmani":"شُكُورًا","transliteration":"shukūran","translation_bn":"কৃতজ্ঞতা","root":"شكر","lemma":"شُكُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":10353,"position":11,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'innamā nuṭ''ʿimukum liwajhi l-lahi lā nurīdu minkum jazāan walā shukūran', 'তারা বলে- ‘আমরা তোমাদেরকে খাবার খাওয়াচ্ছি কেবল আল্লাহর চেহারা (সন্তুষ্টি) লাভের জন্য, আমরা তোমাদের থেকে কোন প্রতিদান চাই না, চাই না কোন কৃতজ্ঞতা (জ্ঞাপন ও ধন্যবাদ)।', '[Saying], "We feed you only for the countenance of Allah. We wish not from you reward or gratitude.', 'তারা বলে- ‘আমরা তোমাদেরকে খাবার খাওয়াচ্ছি কেবল আল্লাহর চেহারা (সন্তুষ্টি) লাভের জন্য, আমরা তোমাদের থেকে কোন প্রতিদান চাই না, চাই না কোন কৃতজ্ঞতা (জ্ঞাপন ও ধন্যবাদ)।', '[Saying], "We feed you only for the countenance of Allah. We wish not from you reward or gratitude.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076009.mp3', now()),
  (76, 10, '', '[{"id":11585,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":11586,"position":2,"text_uthmani":"نَخَافُ","transliteration":"nakhāfu","translation_bn":"ভয় করি আমরা","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11587,"position":3,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11588,"position":4,"text_uthmani":"رَّبِّنَا","transliteration":"rabbinā","translation_bn":"আমাদের রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":11589,"position":5,"text_uthmani":"يَوْمًا","transliteration":"yawman","translation_bn":"সেই দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":11590,"position":6,"text_uthmani":"عَبُوسًۭا","transliteration":"ʿabūsan","translation_bn":"ভয়ংকর (যা)","root":"عبس","lemma":"عَبُوس","grammar_bn":"বিশেষণ (Adjective)"},{"id":11591,"position":7,"text_uthmani":"قَمْطَرِيرًۭا","transliteration":"qamṭarīran","translation_bn":"ক্লেশকর\"","root":"قمطر","lemma":"قَمْطَرِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":11592,"position":8,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'innā nakhāfu min rabbinā yawman ʿabūsan qamṭarīran', 'আমরা কেবল ভয় করি আমাদের প্রতিপালকের পক্ষ হতে এক ভীতিপ্রদ ভয়ানক দিনের।', 'Indeed, We fear from our Lord a Day austere and distressful."', 'আমরা কেবল ভয় করি আমাদের প্রতিপালকের পক্ষ হতে এক ভীতিপ্রদ ভয়ানক দিনের।', 'Indeed, We fear from our Lord a Day austere and distressful."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076010.mp3', now()),
  (76, 11, '', '[{"id":12886,"position":1,"text_uthmani":"فَوَقَىٰهُمُ","transliteration":"fawaqāhumu","translation_bn":"তাদের বাচাবেন অতএব","root":"وقي","lemma":"وَقَىٰ","grammar_bn":"কারণবাচক (Cause)"},{"id":12887,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":12888,"position":3,"text_uthmani":"شَرَّ","transliteration":"sharra","translation_bn":"অনিষ্ঠতা (থেকে)","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":12889,"position":4,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"সেই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":12890,"position":5,"text_uthmani":"ٱلْيَوْمِ","transliteration":"l-yawmi","translation_bn":"দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":12891,"position":6,"text_uthmani":"وَلَقَّىٰهُمْ","transliteration":"walaqqāhum","translation_bn":"এবং তাদের দান করবেন","root":"لقي","lemma":"لَقَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12892,"position":7,"text_uthmani":"نَضْرَةًۭ","transliteration":"naḍratan","translation_bn":"উৎফুল্লতা","root":"نضر","lemma":"نَضْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":12893,"position":8,"text_uthmani":"وَسُرُورًۭا","transliteration":"wasurūran","translation_bn":"ও আনন্দ","root":"سرر","lemma":"سُرُور","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":12894,"position":9,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'fawaqāhumu l-lahu sharra dhālika l-yawmi walaqqāhum naḍratan wasurūran', 'যার ফলে আল্লাহ তাদেরকে সে দিনের অনিষ্ট হতে রক্ষা করবেন আর তাদেরকে দিবেন সজীবতা ও আনন্দ।', 'So Allah will protect them from the evil of that Day and give them radiance and happiness', 'যার ফলে আল্লাহ তাদেরকে সে দিনের অনিষ্ট হতে রক্ষা করবেন আর তাদেরকে দিবেন সজীবতা ও আনন্দ।', 'So Allah will protect them from the evil of that Day and give them radiance and happiness', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076011.mp3', now()),
  (76, 12, '', '[{"id":14499,"position":1,"text_uthmani":"وَجَزَىٰهُم","transliteration":"wajazāhum","translation_bn":"এবং তাদের প্রতিদান","root":"جزي","lemma":"جَزَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14500,"position":2,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"যা বিনিময়ে","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14501,"position":3,"text_uthmani":"صَبَرُوا۟","transliteration":"ṣabarū","translation_bn":"তারা সবর করেছে","root":"صبر","lemma":"صَبَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14502,"position":4,"text_uthmani":"جَنَّةًۭ","transliteration":"jannatan","translation_bn":"জান্নাত","root":"جنن","lemma":"جَنَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":14503,"position":5,"text_uthmani":"وَحَرِيرًۭا","transliteration":"waḥarīran","translation_bn":"এবং রেশমীপোশাক","root":"حرر","lemma":"حَرِير","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14504,"position":6,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'wajazāhum bimā ṣabarū jannatan waḥarīran', 'আর তাদের ধৈর্য সহিষ্ণুতার বিনিময়ে তাদেরকে দিবেন জান্নাত ও রেশমী পোশাক।', 'And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments].', 'আর তাদের ধৈর্য সহিষ্ণুতার বিনিময়ে তাদেরকে দিবেন জান্নাত ও রেশমী পোশাক।', 'And will reward them for what they patiently endured [with] a garden [in Paradise] and silk [garments].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076012.mp3', now()),
  (76, 13, '', '[{"id":15270,"position":1,"text_uthmani":"مُّتَّكِـِٔينَ","transliteration":"muttakiīna","translation_bn":"হেলান দিয়ে বসবে","root":"وكا","lemma":"مُتَّكِـ#ِين","grammar_bn":"বিশেষ্য (Noun)"},{"id":15271,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15272,"position":3,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15273,"position":4,"text_uthmani":"ٱلْأَرَآئِكِ ۖ","transliteration":"l-arāiki","translation_bn":"উচ্চাসনসমুহের","root":"ارك","lemma":"أَرَا^ئِك","grammar_bn":"শব্দ"},{"id":15275,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15276,"position":6,"text_uthmani":"يَرَوْنَ","transliteration":"yarawna","translation_bn":"তারা দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":15277,"position":7,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তারমধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15278,"position":8,"text_uthmani":"شَمْسًۭا","transliteration":"shamsan","translation_bn":"রোদ্রতাপ","root":"شمس","lemma":"شَمْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":15279,"position":9,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15280,"position":10,"text_uthmani":"زَمْهَرِيرًۭا","transliteration":"zamharīran","translation_bn":"শীতের প্রকোপ","root":"زمهر","lemma":"زَمْهَرِير","grammar_bn":"বিশেষ্য (Noun)"},{"id":15281,"position":11,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'muttakiīna fīhā ʿalā l-arāiki lā yarawna fīhā shamsan walā zamharīran', 'সেখানে তারা উচ্চ আসনগুলোতে হেলান দিয়ে বসবে, সেখানে তারা দেখবে না অতি গরম, আর অতি শীত।', '[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold.', 'সেখানে তারা উচ্চ আসনগুলোতে হেলান দিয়ে বসবে, সেখানে তারা দেখবে না অতি গরম, আর অতি শীত।', '[They will be] reclining therein on adorned couches. They will not see therein any [burning] sun or [freezing] cold.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076013.mp3', now()),
  (76, 14, '', '[{"id":16329,"position":1,"text_uthmani":"وَدَانِيَةً","transliteration":"wadāniyatan","translation_bn":"এবং নিকটে থাকবে","root":"دنو","lemma":"دَانِيَة","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16330,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":16331,"position":3,"text_uthmani":"ظِلَـٰلُهَا","transliteration":"ẓilāluhā","translation_bn":"তার ছায়া","root":"ظلل","lemma":"ظِلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16332,"position":4,"text_uthmani":"وَذُلِّلَتْ","transliteration":"wadhullilat","translation_bn":"এবং আয়ত্তাধীন করা হবে","root":"ذلل","lemma":"ذُلِّلَتْ","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":16333,"position":5,"text_uthmani":"قُطُوفُهَا","transliteration":"quṭūfuhā","translation_bn":"তার ফলসমূহ","root":"قطف","lemma":"قُطُوف","grammar_bn":"বিশেষ্য (Noun)"},{"id":16334,"position":6,"text_uthmani":"تَذْلِيلًۭا","transliteration":"tadhlīlan","translation_bn":"আয়ত্তাধীন (পূর্ণ)","root":"ذلل","lemma":"تَذْلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":16335,"position":7,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'wadāniyatan ʿalayhim ẓilāluhā wadhullilat quṭūfuhā tadhlīlan', 'জান্নাতের বৃক্ষরাজির ছায়া তাদের উপর থাকবে, আর ফলের গুচ্ছ একেবারে তাদের নাগালের মধ্যে রাখা হবে।', 'And near above them are its shades, and its [fruit] to be picked will be lowered in compliance.', 'জান্নাতের বৃক্ষরাজির ছায়া তাদের উপর থাকবে, আর ফলের গুচ্ছ একেবারে তাদের নাগালের মধ্যে রাখা হবে।', 'And near above them are its shades, and its [fruit] to be picked will be lowered in compliance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076014.mp3', now()),
  (76, 15, '', '[{"id":17475,"position":1,"text_uthmani":"وَيُطَافُ","transliteration":"wayuṭāfu","translation_bn":"এবং আবর্তিত করানো হবে","root":"طوف","lemma":"طَافَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17476,"position":2,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17477,"position":3,"text_uthmani":"بِـَٔانِيَةٍۢ","transliteration":"biāniyatin","translation_bn":"পান পাত্রকে","root":"اني","lemma":"ءَانِيَة","grammar_bn":"অব্যয় (Preposition)"},{"id":17478,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"(নির্মিত)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":17479,"position":5,"text_uthmani":"فِضَّةٍۢ","transliteration":"fiḍḍatin","translation_bn":"রোপ্যের","root":"فضض","lemma":"فِضَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":17480,"position":6,"text_uthmani":"وَأَكْوَابٍۢ","transliteration":"wa-akwābin","translation_bn":"ও পেয়ালাগুলো","root":"كوب","lemma":"أَكْوَاب","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17481,"position":7,"text_uthmani":"كَانَتْ","transliteration":"kānat","translation_bn":"হবে","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17482,"position":8,"text_uthmani":"قَوَارِيرَا۠","transliteration":"qawārīrā","translation_bn":"কাঁচের (মত)","root":"قرر","lemma":"قَوَارِيرَا","grammar_bn":"বিশেষ্য (Noun)"},{"id":17483,"position":9,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wayuṭāfu ʿalayhim biāniyatin min fiḍḍatin wa-akwābin kānat qawārīrā', 'তাদের সামনে ঘুরে ঘুরে রুপার পাত্র পরিবেশন করা হবে আর সাদা পাথরের পানপাত্র।', 'And there will be circulated among them vessels of silver and cups having been [created] clear [as glass],', 'তাদের সামনে ঘুরে ঘুরে রুপার পাত্র পরিবেশন করা হবে আর সাদা পাথরের পানপাত্র।', 'And there will be circulated among them vessels of silver and cups having been [created] clear [as glass],', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076015.mp3', now()),
