  (76, 18, '', '[{"id":20655,"position":1,"text_uthmani":"عَيْنًۭا","transliteration":"ʿaynan","translation_bn":"ঝর্ণা (এমন এক)","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":20656,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":20657,"position":3,"text_uthmani":"تُسَمَّىٰ","transliteration":"tusammā","translation_bn":"নাম দেয়া হয়েছে (যার)","root":"سمو","lemma":"سَمَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20658,"position":4,"text_uthmani":"سَلْسَبِيلًۭا","transliteration":"salsabīlan","translation_bn":"সালসাবীল","root":"—","lemma":"سَلْسَبِيل","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":20659,"position":5,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'ʿaynan fīhā tusammā salsabīlan', 'সেখানে আছে একটা ঝর্ণা, যার নাম সালসাবীল।', '[From] a fountain within Paradise named Salsabeel.', 'সেখানে আছে একটা ঝর্ণা, যার নাম সালসাবীল।', '[From] a fountain within Paradise named Salsabeel.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076018.mp3', now()),
  (76, 19, '', '[{"id":21711,"position":1,"text_uthmani":"۞ وَيَطُوفُ","transliteration":"wayaṭūfu","translation_bn":"এবং ফিরতে থাকবে","root":"طوف","lemma":"طَافَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21712,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের নিকট","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21713,"position":3,"text_uthmani":"وِلْدَٰنٌۭ","transliteration":"wil''dānun","translation_bn":"কিশোররা","root":"ولد","lemma":"وَلِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":21714,"position":4,"text_uthmani":"مُّخَلَّدُونَ","transliteration":"mukhalladūna","translation_bn":"চির","root":"خلد","lemma":"مُّخَلَّدُون","grammar_bn":"বিশেষণ (Adjective)"},{"id":21715,"position":5,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":21716,"position":6,"text_uthmani":"رَأَيْتَهُمْ","transliteration":"ra-aytahum","translation_bn":"তাদের তুমি দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":21717,"position":7,"text_uthmani":"حَسِبْتَهُمْ","transliteration":"ḥasib''tahum","translation_bn":"তাদের তুুমি মনে করবে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21718,"position":8,"text_uthmani":"لُؤْلُؤًۭا","transliteration":"lu''lu-an","translation_bn":"মুক্তা","root":"لالا","lemma":"لُؤْلُؤ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21719,"position":9,"text_uthmani":"مَّنثُورًۭا","transliteration":"manthūran","translation_bn":"বিক্ষিপ্ত","root":"نثر","lemma":"مَّنثُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":21720,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'wayaṭūfu ʿalayhim wil''dānun mukhalladūna idhā ra-aytahum ḥasib''tahum lu''lu-an manthūran', 'ঘুরে ঘুরে তাদের সেবাদান কার্যে নিয়োজিত থাকবে চিরকিশোরগণ। তুমি যখন তাদেরকে দেখবে, তুমি মনে করবে, তারা যেন ছড়ানো মুক্তা।', 'There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls.', 'ঘুরে ঘুরে তাদের সেবাদান কার্যে নিয়োজিত থাকবে চিরকিশোরগণ। তুমি যখন তাদেরকে দেখবে, তুমি মনে করবে, তারা যেন ছড়ানো মুক্তা।', 'There will circulate among them young boys made eternal. When you see them, you would think them [as beautiful as] scattered pearls.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076019.mp3', now()),
  (76, 20, '', '[{"id":23150,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23151,"position":2,"text_uthmani":"رَأَيْتَ","transliteration":"ra-ayta","translation_bn":"তুমি দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":23152,"position":3,"text_uthmani":"ثَمَّ","transliteration":"thamma","translation_bn":"সেখানে","root":"—","lemma":"ثَمّ\r","grammar_bn":"স্থানবাচক (Location)"},{"id":23153,"position":4,"text_uthmani":"رَأَيْتَ","transliteration":"ra-ayta","translation_bn":"দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":23154,"position":5,"text_uthmani":"نَعِيمًۭا","transliteration":"naʿīman","translation_bn":"নিয়ামত","root":"نعم","lemma":"نَعِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":23155,"position":6,"text_uthmani":"وَمُلْكًۭا","transliteration":"wamul''kan","translation_bn":"এবং সম্রাজ্য","root":"ملك","lemma":"مُلْك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23156,"position":7,"text_uthmani":"كَبِيرًا","transliteration":"kabīran","translation_bn":"বিরাট","root":"كبر","lemma":"كَبِير","grammar_bn":"বিশেষণ (Adjective)"},{"id":23157,"position":8,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā ra-ayta thamma ra-ayta naʿīman wamul''kan kabīran', 'তুমি যখন দেখবে তখন দেখতে পাবে ভোগ বিলাসের নানান সামগ্রী আর এক বিশাল রাজ্য।', 'And when you look there [in Paradise], you will see pleasure and great dominion.', 'তুমি যখন দেখবে তখন দেখতে পাবে ভোগ বিলাসের নানান সামগ্রী আর এক বিশাল রাজ্য।', 'And when you look there [in Paradise], you will see pleasure and great dominion.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076020.mp3', now()),
  (76, 21, '', '[{"id":23965,"position":1,"text_uthmani":"عَـٰلِيَهُمْ","transliteration":"ʿāliyahum","translation_bn":"তাদের উপর","root":"علو","lemma":"عَالِي","grammar_bn":"বিশেষ্য (Noun)"},{"id":23966,"position":2,"text_uthmani":"ثِيَابُ","transliteration":"thiyābu","translation_bn":"পোশাক","root":"ثوب","lemma":"ثِيَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23967,"position":3,"text_uthmani":"سُندُسٍ","transliteration":"sundusin","translation_bn":"সুক্ষ রেশমের","root":"—","lemma":"سُندُس","grammar_bn":"বিশেষ্য (Noun)"},{"id":23968,"position":4,"text_uthmani":"خُضْرٌۭ","transliteration":"khuḍ''run","translation_bn":"সবুজ","root":"خضر","lemma":"خُضْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":23969,"position":5,"text_uthmani":"وَإِسْتَبْرَقٌۭ ۖ","transliteration":"wa-is''tabraqun","translation_bn":"এবং বুটিদার","root":"—","lemma":"إِسْتَبْرَق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23971,"position":6,"text_uthmani":"وَحُلُّوٓا۟","transliteration":"waḥullū","translation_bn":"এবং তাদের অলংকার","root":"حلي","lemma":"حُلُّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23972,"position":7,"text_uthmani":"أَسَاوِرَ","transliteration":"asāwira","translation_bn":"কংকনের","root":"سور","lemma":"أَسَاوِر","grammar_bn":"বিশেষ্য (Noun)"},{"id":23973,"position":8,"text_uthmani":"مِن","transliteration":"min","translation_bn":"(নির্মিত)","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23974,"position":9,"text_uthmani":"فِضَّةٍۢ","transliteration":"fiḍḍatin","translation_bn":"রৌপ্য","root":"فضض","lemma":"فِضَّة","grammar_bn":"বিশেষ্য (Noun)"},{"id":23975,"position":10,"text_uthmani":"وَسَقَىٰهُمْ","transliteration":"wasaqāhum","translation_bn":"এবং তাদের পান করাবেন","root":"سقي","lemma":"سَقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23976,"position":11,"text_uthmani":"رَبُّهُمْ","transliteration":"rabbuhum","translation_bn":"তাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":23977,"position":12,"text_uthmani":"شَرَابًۭا","transliteration":"sharāban","translation_bn":"পানীয়","root":"شرب","lemma":"شَرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":23978,"position":13,"text_uthmani":"طَهُورًا","transliteration":"ṭahūran","translation_bn":"পবিত্র","root":"طهر","lemma":"طَهُور","grammar_bn":"বিশেষণ (Adjective)"},{"id":23979,"position":14,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'ʿāliyahum thiyābu sundusin khuḍ''run wa-is''tabraqun waḥullū asāwira min fiḍḍatin wasaqāhum rabbuhum sharāban ṭahūran', 'তাদের আবরণ হবে চিকন সবুজ রেশম ও মোটা রেশম, আর তাদেরকে অলংকারে সজ্জিত করা হবে রুপার কঙ্কণ দ্বারা, আর তাদের রব্ব তাদেরকে পান করাবেন পবিত্র পরিচ্ছন্ন পানীয়।', 'Upon the inhabitants will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink.', 'তাদের আবরণ হবে চিকন সবুজ রেশম ও মোটা রেশম, আর তাদেরকে অলংকারে সজ্জিত করা হবে রুপার কঙ্কণ দ্বারা, আর তাদের রব্ব তাদেরকে পান করাবেন পবিত্র পরিচ্ছন্ন পানীয়।', 'Upon the inhabitants will be green garments of fine silk and brocade. And they will be adorned with bracelets of silver, and their Lord will give them a purifying drink.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076021.mp3', now()),
  (76, 22, '', '[{"id":25129,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"\"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":25130,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":25131,"position":3,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলো","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25132,"position":4,"text_uthmani":"لَكُمْ","transliteration":"lakum","translation_bn":"তোমাদের জন্যে","root":"—","lemma":"لَكُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":25133,"position":5,"text_uthmani":"جَزَآءًۭ","transliteration":"jazāan","translation_bn":"প্রতিদান","root":"جزي","lemma":"جَزَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":25134,"position":6,"text_uthmani":"وَكَانَ","transliteration":"wakāna","translation_bn":"এবং হবে","root":"كون","lemma":"كَانَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25135,"position":7,"text_uthmani":"سَعْيُكُم","transliteration":"saʿyukum","translation_bn":"তোমাদের প্রচেষ্টা","root":"سعي","lemma":"سَعْي","grammar_bn":"বিশেষ্য (Noun)"},{"id":25136,"position":8,"text_uthmani":"مَّشْكُورًا","transliteration":"mashkūran","translation_bn":"প্রশংসীত\"","root":"شكر","lemma":"مَّشْكُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":25137,"position":9,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhā kāna lakum jazāan wakāna saʿyukum mashkūran', '‘এটাই তোমাদের প্রতিদান, তোমাদের চেষ্টা-সাধনা সাদরে গৃহীত হয়েছে।’', '[And it will be said], "Indeed, this is for you a reward, and your effort has been appreciated."', '‘এটাই তোমাদের প্রতিদান, তোমাদের চেষ্টা-সাধনা সাদরে গৃহীত হয়েছে।’', '[And it will be said], "Indeed, this is for you a reward, and your effort has been appreciated."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076022.mp3', now()),
  (76, 23, '', '[{"id":26005,"position":1,"text_uthmani":"إِنَّا","transliteration":"innā","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":26006,"position":2,"text_uthmani":"نَحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":26007,"position":3,"text_uthmani":"نَزَّلْنَا","transliteration":"nazzalnā","translation_bn":"আমরা নাযিল করেছি","root":"نزل","lemma":"نَزَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":26008,"position":4,"text_uthmani":"عَلَيْكَ","transliteration":"ʿalayka","translation_bn":"তোমার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26009,"position":5,"text_uthmani":"ٱلْقُرْءَانَ","transliteration":"l-qur''āna","translation_bn":"কুরআন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":26010,"position":6,"text_uthmani":"تَنزِيلًۭا","transliteration":"tanzīlan","translation_bn":"নাযিল (অল্প অল্প করে)","root":"نزل","lemma":"تَنزِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":26011,"position":7,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'innā naḥnu nazzalnā ʿalayka l-qur''āna tanzīlan', '(হে নবী!) আমি তোমার কাছে কুরআন অবতীর্ণ করেছি ক্রমে ক্রমে (অল্প অল্প করে)।', 'Indeed, it is We who have sent down to you, [O Muhammad], the Qur''an progressively.', '(হে নবী!) আমি তোমার কাছে কুরআন অবতীর্ণ করেছি ক্রমে ক্রমে (অল্প অল্প করে)।', 'Indeed, it is We who have sent down to you, [O Muhammad], the Qur''an progressively.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076023.mp3', now()),
  (76, 24, '', '[{"id":27292,"position":1,"text_uthmani":"فَٱصْبِرْ","transliteration":"fa-iṣ''bir","translation_bn":"অতএব তুমি সবর কর","root":"صبر","lemma":"صَبَرَ","grammar_bn":"শব্দ"},{"id":27293,"position":2,"text_uthmani":"لِحُكْمِ","transliteration":"liḥuk''mi","translation_bn":"হুকুমের জন্য","root":"حكم","lemma":"حُكْم","grammar_bn":"অব্যয় (Preposition)"},{"id":27294,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":27295,"position":4,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27296,"position":5,"text_uthmani":"تُطِعْ","transliteration":"tuṭiʿ","translation_bn":"তুমি অনুসরন কর","root":"طوع","lemma":"أَطَاعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27297,"position":6,"text_uthmani":"مِنْهُمْ","transliteration":"min''hum","translation_bn":"তাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27298,"position":7,"text_uthmani":"ءَاثِمًا","transliteration":"āthiman","translation_bn":"পাপিষ্ঠ (যারা)","root":"اثم","lemma":"ا^ثِم","grammar_bn":"বিশেষ্য (Noun)"},{"id":27299,"position":8,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27300,"position":9,"text_uthmani":"كَفُورًۭا","transliteration":"kafūran","translation_bn":"কাফির","root":"كفر","lemma":"كَفُور","grammar_bn":"বিশেষ্য (Noun)"},{"id":27301,"position":10,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'fa-iṣ''bir liḥuk''mi rabbika walā tuṭiʿ min''hum āthiman aw kafūran', 'কাজেই তুমি ধৈর্য ধ’রে, তোমার প্রতিপালকের নির্দেশের অপেক্ষা কর আর তাদের মধ্যেকার পাপাচারী অথবা কাফিরের আনুগত্য কর না।', 'So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever].', 'কাজেই তুমি ধৈর্য ধ’রে, তোমার প্রতিপালকের নির্দেশের অপেক্ষা কর আর তাদের মধ্যেকার পাপাচারী অথবা কাফিরের আনুগত্য কর না।', 'So be patient for the decision of your Lord and do not obey from among them a sinner or ungrateful [disbeliever].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076024.mp3', now()),
  (76, 25, '', '[{"id":28101,"position":1,"text_uthmani":"وَٱذْكُرِ","transliteration":"wa-udh''kuri","translation_bn":"এবং স্মরন কর","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28102,"position":2,"text_uthmani":"ٱسْمَ","transliteration":"is''ma","translation_bn":"নামের","root":"سمو","lemma":"ٱسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":28103,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":28104,"position":4,"text_uthmani":"بُكْرَةًۭ","transliteration":"buk''ratan","translation_bn":"সকাল","root":"بكر","lemma":"بُكْرَة","grammar_bn":"কালবাচক (Time)"},{"id":28105,"position":5,"text_uthmani":"وَأَصِيلًۭا","transliteration":"wa-aṣīlan","translation_bn":"ও সন্ধ্যায়","root":"اصل","lemma":"أَصِيل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28106,"position":6,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-udh''kuri is''ma rabbika buk''ratan wa-aṣīlan', 'আর সকাল-সন্ধ্যায় তোমার রব্ব এর নাম স্মরণ কর।', 'And mention the name of your Lord [in prayer] morning and evening', 'আর সকাল-সন্ধ্যায় তোমার রব্ব এর নাম স্মরণ কর।', 'And mention the name of your Lord [in prayer] morning and evening', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076025.mp3', now()),
  (76, 26, '', '[{"id":29162,"position":1,"text_uthmani":"وَمِنَ","transliteration":"wamina","translation_bn":"মধ্য হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29163,"position":2,"text_uthmani":"ٱلَّيْلِ","transliteration":"al-layli","translation_bn":"রাতে","root":"ليل","lemma":"لَيْل","grammar_bn":"শব্দ"},{"id":29164,"position":3,"text_uthmani":"فَٱسْجُدْ","transliteration":"fa-us''jud","translation_bn":"সিজদা অতঃপর করো","root":"سجد","lemma":"سَجَدَ","grammar_bn":"শব্দ"},{"id":29165,"position":4,"text_uthmani":"لَهُۥ","transliteration":"lahu","translation_bn":"তাকে","root":"—","lemma":"لَهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":29166,"position":5,"text_uthmani":"وَسَبِّحْهُ","transliteration":"wasabbiḥ''hu","translation_bn":"এবং তাঁর তসবিহ কর","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29167,"position":6,"text_uthmani":"لَيْلًۭا","transliteration":"laylan","translation_bn":"রাতে","root":"ليل","lemma":"لَيْل","grammar_bn":"কালবাচক (Time)"},{"id":29168,"position":7,"text_uthmani":"طَوِيلًا","transliteration":"ṭawīlan","translation_bn":"দীর্ঘ","root":"طول","lemma":"طَوِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":29169,"position":8,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamina al-layli fa-us''jud lahu wasabbiḥ''hu laylan ṭawīlan', 'আর রাতের কিছু অংশে তাঁর জন্য সেজদায় অবনত হও আর রাতের দীর্ঘ সময় ধরে তাঁর মহিমা বর্ণনা কর।', 'And during the night prostrate to Him and exalt Him a long [part of the] night.', 'আর রাতের কিছু অংশে তাঁর জন্য সেজদায় অবনত হও আর রাতের দীর্ঘ সময় ধরে তাঁর মহিমা বর্ণনা কর।', 'And during the night prostrate to Him and exalt Him a long [part of the] night.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076026.mp3', now()),
  (76, 27, '', '[{"id":29906,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":29907,"position":2,"text_uthmani":"هَـٰٓؤُلَآءِ","transliteration":"hāulāi","translation_bn":"ঐসব লোক","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":29908,"position":3,"text_uthmani":"يُحِبُّونَ","transliteration":"yuḥibbūna","translation_bn":"ভালবাসে","root":"حبب","lemma":"أَحْبَبْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29909,"position":4,"text_uthmani":"ٱلْعَاجِلَةَ","transliteration":"l-ʿājilata","translation_bn":"দ্রুত অর্জিত ( বৈষয়িক স্বার্থ)","root":"عجل","lemma":"عَاجِلَةٌ","grammar_bn":"শব্দ"},{"id":29910,"position":5,"text_uthmani":"وَيَذَرُونَ","transliteration":"wayadharūna","translation_bn":"এবং তারা উপেক্ষা করে","root":"وذر","lemma":"يَذَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29911,"position":6,"text_uthmani":"وَرَآءَهُمْ","transliteration":"warāahum","translation_bn":"তাদের পিছনে","root":"وري","lemma":"وَرَا^ء","grammar_bn":"স্থানবাচক (Location)"},{"id":29912,"position":7,"text_uthmani":"يَوْمًۭا","transliteration":"yawman","translation_bn":"দিনকে","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":29913,"position":8,"text_uthmani":"ثَقِيلًۭا","transliteration":"thaqīlan","translation_bn":"ভারী","root":"ثقل","lemma":"ثَقِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":29914,"position":9,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'inna hāulāi yuḥibbūna l-ʿājilata wayadharūna warāahum yawman thaqīlan', 'এ লোকেরা তো পার্থিব জীবনকে ভালবাসে আর তাদের আড়ালে যে (কিয়ামাতের) কঠিন দিন (আসছে) তাকে উপেক্ষা করে।', 'Indeed, these [disbelievers] love the immediate and leave behind them a grave Day.', 'এ লোকেরা তো পার্থিব জীবনকে ভালবাসে আর তাদের আড়ালে যে (কিয়ামাতের) কঠিন দিন (আসছে) তাকে উপেক্ষা করে।', 'Indeed, these [disbelievers] love the immediate and leave behind them a grave Day.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076027.mp3', now()),
  (76, 28, '', '[{"id":31141,"position":1,"text_uthmani":"نَّحْنُ","transliteration":"naḥnu","translation_bn":"আমরা","root":"—","lemma":"نَّحْنُ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":31142,"position":2,"text_uthmani":"خَلَقْنَـٰهُمْ","transliteration":"khalaqnāhum","translation_bn":"তাদের আমরা সৃষ্টি করেছি","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31143,"position":3,"text_uthmani":"وَشَدَدْنَآ","transliteration":"washadadnā","translation_bn":"এবং আমরা সুদৃঢ় করেছি","root":"شدد","lemma":"شَدَدْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":31144,"position":4,"text_uthmani":"أَسْرَهُمْ ۖ","transliteration":"asrahum","translation_bn":"তাদের জোড়ন","root":"اسر","lemma":"أَسْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":31146,"position":5,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":31147,"position":6,"text_uthmani":"شِئْنَا","transliteration":"shi''nā","translation_bn":"আমরা চাইবো","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31148,"position":7,"text_uthmani":"بَدَّلْنَآ","transliteration":"baddalnā","translation_bn":"আমরা বদলে দেবো","root":"بدل","lemma":"بَدَّلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31149,"position":8,"text_uthmani":"أَمْثَـٰلَهُمْ","transliteration":"amthālahum","translation_bn":"তাদের আকৃতি সমূহ","root":"مثل","lemma":"مَثَل","grammar_bn":"বিশেষ্য (Noun)"},{"id":31150,"position":9,"text_uthmani":"تَبْدِيلًا","transliteration":"tabdīlan","translation_bn":"পরিবর্তন করে","root":"بدل","lemma":"تَبْدِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":31151,"position":10,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'naḥnu khalaqnāhum washadadnā asrahum wa-idhā shi''nā baddalnā amthālahum tabdīlan', 'আমিই তাদেরকে সৃষ্টি করেছি আর তাদের গঠন মজবুত করেছি। আমি যখন চাইব তখন তাদের স্থলে তাদের মত অন্য লোক আনব।', 'We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration.', 'আমিই তাদেরকে সৃষ্টি করেছি আর তাদের গঠন মজবুত করেছি। আমি যখন চাইব তখন তাদের স্থলে তাদের মত অন্য লোক আনব।', 'We have created them and strengthened their forms, and when We will, We can change their likenesses with [complete] alteration.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076028.mp3', now()),
  (76, 29, '', '[{"id":31985,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":31986,"position":2,"text_uthmani":"هَـٰذِهِۦ","transliteration":"hādhihi","translation_bn":"এটা","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":31987,"position":3,"text_uthmani":"تَذْكِرَةٌۭ ۖ","transliteration":"tadhkiratun","translation_bn":"নসীহত","root":"ذكر","lemma":"تَذْكِرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":31989,"position":4,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"যে অতএব","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":31990,"position":5,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"চায়","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31991,"position":6,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"গ্রহন করবে","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31992,"position":7,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31993,"position":8,"text_uthmani":"رَبِّهِۦ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":31994,"position":9,"text_uthmani":"سَبِيلًۭا","transliteration":"sabīlan","translation_bn":"পথ","root":"سبل","lemma":"سَبِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":31995,"position":10,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhihi tadhkiratun faman shāa ittakhadha ilā rabbihi sabīlan', 'এটা এক উপদেশ, কাজেই যার ইচ্ছে সে (এ উপদেশ মান্য ক’রে) তার প্রতিপালকের পথ ধরুক।', 'Indeed, this is a reminder, so he who wills may take to his Lord a way.', 'এটা এক উপদেশ, কাজেই যার ইচ্ছে সে (এ উপদেশ মান্য ক’রে) তার প্রতিপালকের পথ ধরুক।', 'Indeed, this is a reminder, so he who wills may take to his Lord a way.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076029.mp3', now()),
  (76, 30, '', '[{"id":32874,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":32875,"position":2,"text_uthmani":"تَشَآءُونَ","transliteration":"tashāūna","translation_bn":"তোমরা চাও","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32876,"position":3,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":32877,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":32878,"position":5,"text_uthmani":"يَشَآءَ","transliteration":"yashāa","translation_bn":"চান","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32879,"position":6,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32881,"position":7,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":32882,"position":8,"text_uthmani":"ٱللَّهَ","transliteration":"l-laha","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32883,"position":9,"text_uthmani":"كَانَ","transliteration":"kāna","translation_bn":"হলেন","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32884,"position":10,"text_uthmani":"عَلِيمًا","transliteration":"ʿalīman","translation_bn":"সর্বজ্ঞ","root":"علم","lemma":"عَلِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":32885,"position":11,"text_uthmani":"حَكِيمًۭا","transliteration":"ḥakīman","translation_bn":"প্রজ্ঞাময়","root":"حكم","lemma":"حَكِيم","grammar_bn":"বিশেষ্য (Noun)"},{"id":32886,"position":12,"text_uthmani":"٣٠","transliteration":"","translation_bn":"(৩০)","root":"—","lemma":"٣٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā tashāūna illā an yashāa l-lahu inna l-laha kāna ʿalīman ḥakīman', 'তোমরা ইচ্ছে কর না আল্লাহর ইচ্ছে ব্যতীত। (অর্থাৎ আল্লাহ কোন কিছু কার্যকর করতে চাইলে তোমাদের মাঝে ইচ্ছে ও শক্তি সঞ্চার করতঃ তোমাদের মাধ্যমে তা কার্যকর করেন)। আল্লাহ সর্বজ্ঞাতা মহাবিজ্ঞানী।', 'And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise.', 'তোমরা ইচ্ছে কর না আল্লাহর ইচ্ছে ব্যতীত। (অর্থাৎ আল্লাহ কোন কিছু কার্যকর করতে চাইলে তোমাদের মাঝে ইচ্ছে ও শক্তি সঞ্চার করতঃ তোমাদের মাধ্যমে তা কার্যকর করেন)। আল্লাহ সর্বজ্ঞাতা মহাবিজ্ঞানী।', 'And you do not will except that Allah wills. Indeed, Allah is ever Knowing and Wise.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076030.mp3', now()),
  (76, 31, '', '[{"id":33277,"position":1,"text_uthmani":"يُدْخِلُ","transliteration":"yud''khilu","translation_bn":"প্রবেশ করান","root":"دخل","lemma":"أُدْخِلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33278,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":33279,"position":3,"text_uthmani":"يَشَآءُ","transliteration":"yashāu","translation_bn":"তিনি চান","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33280,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":33281,"position":5,"text_uthmani":"رَحْمَتِهِۦ ۚ","transliteration":"raḥmatihi","translation_bn":"তাঁর রহমতের","root":"رحم","lemma":"رَحْمَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":33283,"position":6,"text_uthmani":"وَٱلظَّـٰلِمِينَ","transliteration":"wal-ẓālimīna","translation_bn":"এবং যালেমদের","root":"ظلم","lemma":"ظَالِم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":33284,"position":7,"text_uthmani":"أَعَدَّ","transliteration":"aʿadda","translation_bn":"প্রস্তুত রেখেছেন","root":"عدد","lemma":"أَعَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":33285,"position":8,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":33286,"position":9,"text_uthmani":"عَذَابًا","transliteration":"ʿadhāban","translation_bn":"আযাব","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":33287,"position":10,"text_uthmani":"أَلِيمًۢا","transliteration":"alīman","translation_bn":"বড় পীড়াদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":33288,"position":11,"text_uthmani":"٣١","transliteration":"","translation_bn":"(৩১)","root":"—","lemma":"٣١","grammar_bn":"মার্কার"}]'::jsonb, 'yud''khilu man yashāu fī raḥmatihi wal-ẓālimīna aʿadda lahum ʿadhāban alīman', 'তিনি যাকে ইচ্ছে তাঁর রাহমাতে দাখিল করেন। আর যালিমরা- তাদের জন্য তিনি প্রস্তুত করে রেখেছেন বড়ই পীড়াদায়ক শাস্তি।', 'He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment.', 'তিনি যাকে ইচ্ছে তাঁর রাহমাতে দাখিল করেন। আর যালিমরা- তাদের জন্য তিনি প্রস্তুত করে রেখেছেন বড়ই পীড়াদায়ক শাস্তি।', 'He admits whom He wills into His mercy; but the wrongdoers - He has prepared for them a painful punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/076031.mp3', now())
