  (77, 1, '', '[{"id":673,"position":1,"text_uthmani":"وَٱلْمُرْسَلَـٰتِ","transliteration":"wal-mur''salāti","translation_bn":"শপথ প্রেরিত (বায়ুর)","root":"رسل","lemma":"مُرْسَلَٰت","grammar_bn":"অব্যয় (Preposition)"},{"id":674,"position":2,"text_uthmani":"عُرْفًۭا","transliteration":"ʿur''fan","translation_bn":"কল্যাণ সুরূপ","root":"عرف","lemma":"عُرْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":675,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wal-mur''salāti ʿur''fan', 'পর পর পাঠানো বাতাসের শপথ যা উপকার সাধন করে,', 'By those [winds] sent forth in gusts', 'পর পর পাঠানো বাতাসের শপথ যা উপকার সাধন করে,', 'By those [winds] sent forth in gusts', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/077001.mp3', now()),
  (77, 2, '', '[{"id":1659,"position":1,"text_uthmani":"فَٱلْعَـٰصِفَـٰتِ","transliteration":"fal-ʿāṣifāti","translation_bn":"অতঃপর ঝটিকার","root":"عصف","lemma":"عَٰصِفَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1660,"position":2,"text_uthmani":"عَصْفًۭا","transliteration":"ʿaṣfan","translation_bn":"প্রলংকরী","root":"عصف","lemma":"عَصْف2","grammar_bn":"বিশেষ্য (Noun)"},{"id":1661,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'fal-ʿāṣifāti ʿaṣfan', 'অতঃপর তা প্রচন্ড ঝড়ের বেগে বইতে থাকে,', 'And the winds that blow violently', 'অতঃপর তা প্রচন্ড ঝড়ের বেগে বইতে থাকে,', 'And the winds that blow violently', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/077002.mp3', now()),
  (77, 3, '', '[{"id":2790,"position":1,"text_uthmani":"وَٱلنَّـٰشِرَٰتِ","transliteration":"wal-nāshirāti","translation_bn":"এবং (মেঘপুঞ্জ) বিস্তারকারী (বায়ুর)","root":"نشر","lemma":"نَّٰشِرَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2791,"position":2,"text_uthmani":"نَشْرًۭا","transliteration":"nashran","translation_bn":"বিস্তার করা","root":"نشر","lemma":"نَشْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2792,"position":3,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wal-nāshirāti nashran', 'শপথ সেই বায়ুর যা (মেঘমালাকে) ছড়িয়ে দেয় দূর দূরান্তে,', 'And [by] the winds that spread [clouds]', 'শপথ সেই বায়ুর যা (মেঘমালাকে) ছড়িয়ে দেয় দূর দূরান্তে,', 'And [by] the winds that spread [clouds]', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/077003.mp3', now()),
  (77, 4, '', '[{"id":4142,"position":1,"text_uthmani":"فَٱلْفَـٰرِقَـٰتِ","transliteration":"fal-fāriqāti","translation_bn":"প্রৃথককারী (বায়ুর) অতংপর","root":"فرق","lemma":"فَٰرِقَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4143,"position":2,"text_uthmani":"فَرْقًۭا","transliteration":"farqan","translation_bn":"পৃথক করা (মেঘকে)","root":"فرق","lemma":"فَرْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":4144,"position":3,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'fal-fāriqāti farqan', 'আর বিচ্ছিন্নকারী বাতাসের শপথ যা (মেঘমালাকে) বিচ্ছিন্ন করে,', 'And those [angels] who bring criterion', 'আর বিচ্ছিন্নকারী বাতাসের শপথ যা (মেঘমালাকে) বিচ্ছিন্ন করে,', 'And those [angels] who bring criterion', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/077004.mp3', now()),
  (77, 5, '', '[{"id":5433,"position":1,"text_uthmani":"فَٱلْمُلْقِيَـٰتِ","transliteration":"fal-mul''qiyāti","translation_bn":"অতংপর জাগ্রতকারীদের (অন্তরে)","root":"لقي","lemma":"مُلْقِيَٰت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5434,"position":2,"text_uthmani":"ذِكْرًا","transliteration":"dhik''ran","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":5435,"position":3,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fal-mul''qiyāti dhik''ran', 'অতঃপর (মানুষের অন্তরে) পৌঁছে দেয় (আল্লাহর) স্মরণ,', 'And those [angels] who deliver a message', 'অতঃপর (মানুষের অন্তরে) পৌঁছে দেয় (আল্লাহর) স্মরণ,', 'And those [angels] who deliver a message', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/077005.mp3', now()),
