  (77, 27, '', '[{"id":29898,"position":1,"text_uthmani":"وَجَعَلْنَا","transliteration":"wajaʿalnā","translation_bn":"এবং আমরা বাানিয়েছি","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29899,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":29900,"position":3,"text_uthmani":"رَوَٰسِىَ","transliteration":"rawāsiya","translation_bn":"পর্বতমালা","root":"رسو","lemma":"رَوَٰسِى","grammar_bn":"বিশেষ্য (Noun)"},{"id":29901,"position":4,"text_uthmani":"شَـٰمِخَـٰتٍۢ","transliteration":"shāmikhātin","translation_bn":"সুদৃৃঢ় উচ্চ","root":"شمخ","lemma":"شَٰمِخَٰت","grammar_bn":"বিশেষণ (Adjective)"},{"id":29902,"position":5,"text_uthmani":"وَأَسْقَيْنَـٰكُم","transliteration":"wa-asqaynākum","translation_bn":"ও তোমাদেরকে পান করিয়েছি","root":"سقي","lemma":"أَسْقَيْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":29903,"position":6,"text_uthmani":"مَّآءًۭ","transliteration":"māan","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":29904,"position":7,"text_uthmani":"فُرَاتًۭا","transliteration":"furātan","translation_bn":"সুমিষ্ট","root":"فرت","lemma":"فُرَات","grammar_bn":"বিশেষণ (Adjective)"},{"id":29905,"position":8,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'wajaʿalnā fīhā rawāsiya shāmikhātin wa-asqaynākum māan furātan', 'আর আমি তাতে স্থাপন করেছি অনড় সুউচ্চ পবর্তমালা আর তোমাদেরকে পান করিয়েছি সুমিষ্ট সুপেয় পানি।', 'And We placed therein lofty, firmly set mountains and have given you to drink sweet water.', 'আর আমি তাতে স্থাপন করেছি অনড় সুউচ্চ পবর্তমালা আর তোমাদেরকে পান করিয়েছি সুমিষ্ট সুপেয় পানি।', 'And We placed therein lofty, firmly set mountains and have given you to drink sweet water.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/077027.mp3', now()),
