  (78, 1, '', '[{"id":676,"position":1,"text_uthmani":"عَمَّ","transliteration":"ʿamma","translation_bn":"কি সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":677,"position":2,"text_uthmani":"يَتَسَآءَلُونَ","transliteration":"yatasāalūna","translation_bn":"তারা পরস্পরকে জিজ্ঞাসা করছে","root":"سال","lemma":"يَتَسَا^ءَلُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":678,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'ʿamma yatasāalūna', 'লোকেরা কোন বিষয়ে একে অন্যের কাছে জিজ্ঞাসাবাদ করছে?', 'About what are they asking one another?', 'লোকেরা কোন বিষয়ে একে অন্যের কাছে জিজ্ঞাসাবাদ করছে?', 'About what are they asking one another?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078001.mp3', now()),
  (78, 2, '', '[{"id":1691,"position":1,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1692,"position":2,"text_uthmani":"ٱلنَّبَإِ","transliteration":"l-naba-i","translation_bn":"সংবাদ","root":"نبا","lemma":"نَبَأ","grammar_bn":"শব্দ"},{"id":1693,"position":3,"text_uthmani":"ٱلْعَظِيمِ","transliteration":"l-ʿaẓīmi","translation_bn":"মহা (অর্থাৎ কিয়ামত)","root":"عظم","lemma":"عَظِيم","grammar_bn":"শব্দ"},{"id":1694,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'ʿani l-naba-i l-ʿaẓīmi', '(ক্বিয়ামত সংঘটিত হওয়ার) সেই মহা সংবাদের বিষয়ে,', 'About the great news -', '(ক্বিয়ামত সংঘটিত হওয়ার) সেই মহা সংবাদের বিষয়ে,', 'About the great news -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078002.mp3', now()),
  (78, 3, '', '[{"id":2799,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"তা (এমন যে)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2800,"position":2,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":2801,"position":3,"text_uthmani":"فِيهِ","transliteration":"fīhi","translation_bn":"সে বিষয়ে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2802,"position":4,"text_uthmani":"مُخْتَلِفُونَ","transliteration":"mukh''talifūna","translation_bn":"(নিজেরাই) মতানৈক্যকারী","root":"خلف","lemma":"مُّخْتَلِف","grammar_bn":"বিশেষ্য (Noun)"},{"id":2803,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī hum fīhi mukh''talifūna', 'যে বিষয়ে তাদের মাঝে মতপার্থক্য আছে।', 'That over which they are in disagreement.', 'যে বিষয়ে তাদের মাঝে মতপার্থক্য আছে।', 'That over which they are in disagreement.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078003.mp3', now()),
