  (78, 36, '', '[{"id":38535,"position":1,"text_uthmani":"جَزَآءًۭ","transliteration":"jazāan","translation_bn":"পুরস্কার","root":"جزي","lemma":"جَزَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":38536,"position":2,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"পক্ষ হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":38537,"position":3,"text_uthmani":"رَّبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":38538,"position":4,"text_uthmani":"عَطَآءً","transliteration":"ʿaṭāan","translation_bn":"(এ ছাড়াও) দান","root":"عطو","lemma":"عَطَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":38539,"position":5,"text_uthmani":"حِسَابًۭا","transliteration":"ḥisāban","translation_bn":"যথোচিত","root":"حسب","lemma":"حِسَاب","grammar_bn":"বিশেষণ (Adjective)"},{"id":38540,"position":6,"text_uthmani":"٣٦","transliteration":"","translation_bn":"(৩৬)","root":"—","lemma":"٣٦","grammar_bn":"মার্কার"}]'::jsonb, 'jazāan min rabbika ʿaṭāan ḥisāban', 'এটা তোমার প্রতিপালকের পক্ষ থেকে প্রতিফল, যথোচিত দান।', '[As] reward from your Lord, [a generous] gift [made due by] account,', 'এটা তোমার প্রতিপালকের পক্ষ থেকে প্রতিফল, যথোচিত দান।', '[As] reward from your Lord, [a generous] gift [made due by] account,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078036.mp3', now()),
  (78, 37, '', '[{"id":39402,"position":1,"text_uthmani":"رَّبِّ","transliteration":"rabbi","translation_bn":"(পক্ষ হতে) রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":39403,"position":2,"text_uthmani":"ٱلسَّمَـٰوَٰتِ","transliteration":"l-samāwāti","translation_bn":"আকাশসমূহের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":39404,"position":3,"text_uthmani":"وَٱلْأَرْضِ","transliteration":"wal-arḍi","translation_bn":"এবং পৃথিবীর","root":"ارض","lemma":"أَرْض","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39405,"position":4,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":39406,"position":5,"text_uthmani":"بَيْنَهُمَا","transliteration":"baynahumā","translation_bn":"তাদের দু''য়ের মাঝে আছে","root":"بين","lemma":"بَيْن","grammar_bn":"স্থানবাচক (Location)"},{"id":39407,"position":6,"text_uthmani":"ٱلرَّحْمَـٰنِ ۖ","transliteration":"l-raḥmāni","translation_bn":"অশেষ দয়াবানের (পক্ষ হতে)","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":39409,"position":7,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":39410,"position":8,"text_uthmani":"يَمْلِكُونَ","transliteration":"yamlikūna","translation_bn":"তারা সক্ষম হবে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":39411,"position":9,"text_uthmani":"مِنْهُ","transliteration":"min''hu","translation_bn":"তাঁর সাথে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":39412,"position":10,"text_uthmani":"خِطَابًۭا","transliteration":"khiṭāban","translation_bn":"কথা বলতে","root":"خطب","lemma":"خِطَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":39413,"position":11,"text_uthmani":"٣٧","transliteration":"","translation_bn":"(৩৭)","root":"—","lemma":"٣٧","grammar_bn":"মার্কার"}]'::jsonb, 'rabbi l-samāwāti wal-arḍi wamā baynahumā l-raḥmāni lā yamlikūna min''hu khiṭāban', 'যিনি আকাশ, পৃথিবী আর এগুলোর মাঝে যা কিছু আছে সব কিছুর প্রতিপালক, তিনি অতি দয়াময়, তাঁর সম্মুখে কথা বলার সাহস কারো হবে না।', '[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.', 'যিনি আকাশ, পৃথিবী আর এগুলোর মাঝে যা কিছু আছে সব কিছুর প্রতিপালক, তিনি অতি দয়াময়, তাঁর সম্মুখে কথা বলার সাহস কারো হবে না।', '[From] the Lord of the heavens and the earth and whatever is between them, the Most Merciful. They possess not from Him [authority for] speech.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078037.mp3', now()),
  (78, 38, '', '[{"id":40124,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":40125,"position":2,"text_uthmani":"يَقُومُ","transliteration":"yaqūmu","translation_bn":"দাঁড়াবে","root":"قوم","lemma":"قَامَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40126,"position":3,"text_uthmani":"ٱلرُّوحُ","transliteration":"l-rūḥu","translation_bn":"রূহ (জিবরাইল)","root":"روح","lemma":"رُوح","grammar_bn":"শব্দ"},{"id":40127,"position":4,"text_uthmani":"وَٱلْمَلَـٰٓئِكَةُ","transliteration":"wal-malāikatu","translation_bn":"ও ফেরেশতারা","root":"ملك","lemma":"مَلَك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40128,"position":5,"text_uthmani":"صَفًّۭا ۖ","transliteration":"ṣaffan","translation_bn":"সারিবদ্ধ ভাবে","root":"صفف","lemma":"صَفّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40130,"position":6,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":40131,"position":7,"text_uthmani":"يَتَكَلَّمُونَ","transliteration":"yatakallamūna","translation_bn":"তারা কথা বলবে","root":"كلم","lemma":"يَتَكَلَّمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40132,"position":8,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"(সে) ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":40133,"position":9,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":40134,"position":10,"text_uthmani":"أَذِنَ","transliteration":"adhina","translation_bn":"অনুমতি দেবেন","root":"اذن","lemma":"أَذِنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40135,"position":11,"text_uthmani":"لَهُ","transliteration":"lahu","translation_bn":"তার জন্যে","root":"—","lemma":"لَهُ","grammar_bn":"অব্যয় (Preposition)"},{"id":40136,"position":12,"text_uthmani":"ٱلرَّحْمَـٰنُ","transliteration":"l-raḥmānu","translation_bn":"দয়াময়","root":"رحم","lemma":"رَّحْمَٰن","grammar_bn":"শব্দ"},{"id":40137,"position":13,"text_uthmani":"وَقَالَ","transliteration":"waqāla","translation_bn":"এবং বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":40138,"position":14,"text_uthmani":"صَوَابًۭا","transliteration":"ṣawāban","translation_bn":"যথাযথ","root":"صوب","lemma":"صَوَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":40139,"position":15,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'yawma yaqūmu l-rūḥu wal-malāikatu ṣaffan lā yatakallamūna illā man adhina lahu l-raḥmānu waqāla ṣawāban', 'সেদিন রূহ (জিবরাঈল) আর ফেরেশতারা সারিবদ্ধ হয়ে দাঁড়াবে, কেউ কোন কথা বলতে পারবে না, সে ব্যতীত যাকে পরম করুণাময় অনুমতি দিবেন, আর সে যথার্থ কথাই বলবে।', 'The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct.', 'সেদিন রূহ (জিবরাঈল) আর ফেরেশতারা সারিবদ্ধ হয়ে দাঁড়াবে, কেউ কোন কথা বলতে পারবে না, সে ব্যতীত যাকে পরম করুণাময় অনুমতি দিবেন, আর সে যথার্থ কথাই বলবে।', 'The Day that the Spirit and the angels will stand in rows, they will not speak except for one whom the Most Merciful permits, and he will say what is correct.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078038.mp3', now()),
  (78, 39, '', '[{"id":40931,"position":1,"text_uthmani":"ذَٰلِكَ","transliteration":"dhālika","translation_bn":"সে-ই","root":"—","lemma":"ذَٰلِك","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":40932,"position":2,"text_uthmani":"ٱلْيَوْمُ","transliteration":"l-yawmu","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"শব্দ"},{"id":40933,"position":3,"text_uthmani":"ٱلْحَقُّ ۖ","transliteration":"l-ḥaqu","translation_bn":"সুনিশ্চিত","root":"حقق","lemma":"حَقّ","grammar_bn":"শব্দ"},{"id":40935,"position":4,"text_uthmani":"فَمَن","transliteration":"faman","translation_bn":"অতএব যে","root":"—","lemma":"مَن\r","grammar_bn":"শব্দ"},{"id":40936,"position":5,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"চায়","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40937,"position":6,"text_uthmani":"ٱتَّخَذَ","transliteration":"ittakhadha","translation_bn":"গ্রহণ করুক (আজ)","root":"اخذ","lemma":"ٱتَّخَذَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":40938,"position":7,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":40939,"position":8,"text_uthmani":"رَبِّهِۦ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":40940,"position":9,"text_uthmani":"مَـَٔابًا","transliteration":"maāban","translation_bn":"প্রত্যাবর্তনের (পথ)","root":"اوب","lemma":"مَـ#َاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":40941,"position":10,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'dhālika l-yawmu l-ḥaqu faman shāa ittakhadha ilā rabbihi maāban', 'এ দিনটি সত্য, সুনিশ্চিত, অতএব যার ইচ্ছে সে তার প্রতিপালকের দিকে আশ্রয় গ্রহণ করুক।', 'That is the True Day; so he who wills may take to his Lord a [way of] return.', 'এ দিনটি সত্য, সুনিশ্চিত, অতএব যার ইচ্ছে সে তার প্রতিপালকের দিকে আশ্রয় গ্রহণ করুক।', 'That is the True Day; so he who wills may take to his Lord a [way of] return.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078039.mp3', now()),
  (78, 40, '', '[{"id":41863,"position":1,"text_uthmani":"إِنَّآ","transliteration":"innā","translation_bn":"নিশ্চয়ই আমরা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":41864,"position":2,"text_uthmani":"أَنذَرْنَـٰكُمْ","transliteration":"andharnākum","translation_bn":"তোমাদেরকে আমরা সতর্ক করছি","root":"نذر","lemma":"أَنذَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41865,"position":3,"text_uthmani":"عَذَابًۭا","transliteration":"ʿadhāban","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":41866,"position":4,"text_uthmani":"قَرِيبًۭا","transliteration":"qarīban","translation_bn":"আসন্ন","root":"قرب","lemma":"قَرِيب","grammar_bn":"বিশেষণ (Adjective)"},{"id":41867,"position":5,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":41868,"position":6,"text_uthmani":"يَنظُرُ","transliteration":"yanẓuru","translation_bn":"দেখবে","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41869,"position":7,"text_uthmani":"ٱلْمَرْءُ","transliteration":"l-maru","translation_bn":"মানুষ","root":"مرا","lemma":"مَرْء","grammar_bn":"শব্দ"},{"id":41870,"position":8,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":41871,"position":9,"text_uthmani":"قَدَّمَتْ","transliteration":"qaddamat","translation_bn":"আগে পাঠিয়েছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41872,"position":10,"text_uthmani":"يَدَاهُ","transliteration":"yadāhu","translation_bn":"তার দু''হাত","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":41873,"position":11,"text_uthmani":"وَيَقُولُ","transliteration":"wayaqūlu","translation_bn":"এবং বলবে","root":"قول","lemma":"قَالَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":41874,"position":12,"text_uthmani":"ٱلْكَافِرُ","transliteration":"l-kāfiru","translation_bn":"কাফের","root":"كفر","lemma":"كَافِر","grammar_bn":"শব্দ"},{"id":41875,"position":13,"text_uthmani":"يَـٰلَيْتَنِى","transliteration":"yālaytanī","translation_bn":"\"হায় আমার আফসোস","root":"—","lemma":"لَيْت","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":41876,"position":14,"text_uthmani":"كُنتُ","transliteration":"kuntu","translation_bn":"যদি আমি হতাম","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":41877,"position":15,"text_uthmani":"تُرَٰبًۢا","transliteration":"turāban","translation_bn":"মাটি\"","root":"ترب","lemma":"تُرَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":41878,"position":16,"text_uthmani":"٤٠","transliteration":"","translation_bn":"(৪০)","root":"—","lemma":"٤٠","grammar_bn":"মার্কার"}]'::jsonb, 'innā andharnākum ʿadhāban qarīban yawma yanẓuru l-maru mā qaddamat yadāhu wayaqūlu l-kāfiru yālaytanī kuntu turāban', 'আমি তোমাদেরকে নিকটবর্তী শাস্তি সম্পর্কে সতর্ক করছি, যেদিন মানুষ দেখতে পাবে তার হাতগুলো আগেই কী (‘আমাল) পাঠিয়েছে আর কাফির বলবে- ‘হায়! আমি যদি মাটি হতাম (তাহলে আমাকে আজকের এ ‘আযাবের সম্মুখীন হতে হত না)।', 'Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, "Oh, I wish that I were dust!"', 'আমি তোমাদেরকে নিকটবর্তী শাস্তি সম্পর্কে সতর্ক করছি, যেদিন মানুষ দেখতে পাবে তার হাতগুলো আগেই কী (‘আমাল) পাঠিয়েছে আর কাফির বলবে- ‘হায়! আমি যদি মাটি হতাম (তাহলে আমাকে আজকের এ ‘আযাবের সম্মুখীন হতে হত না)।', 'Indeed, We have warned you of a near punishment on the Day when a man will observe what his hands have put forth and the disbeliever will say, "Oh, I wish that I were dust!"', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/078040.mp3', now())
