  (79, 32, '', '[{"id":34778,"position":1,"text_uthmani":"وَٱلْجِبَالَ","transliteration":"wal-jibāla","translation_bn":"এবং পর্বতমালাকে","root":"جبل","lemma":"جَبَل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":34779,"position":2,"text_uthmani":"أَرْسَىٰهَا","transliteration":"arsāhā","translation_bn":"তা দৃঢ়ভাবে প্রোথিত করেছেন","root":"رسو","lemma":"أَرْسَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":34780,"position":3,"text_uthmani":"٣٢","transliteration":"","translation_bn":"(৩২)","root":"—","lemma":"٣٢","grammar_bn":"মার্কার"}]'::jsonb, 'wal-jibāla arsāhā', 'পবর্তকে তিনি দৃঢ়ভাবে প্রতিষ্ঠিত করেছেন,', 'And the mountains He set firmly', 'পবর্তকে তিনি দৃঢ়ভাবে প্রতিষ্ঠিত করেছেন,', 'And the mountains He set firmly', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/079032.mp3', now()),
