  (79, 34, '', '[{"id":36515,"position":1,"text_uthmani":"فَإِذَا","transliteration":"fa-idhā","translation_bn":"অতঃপর যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"শব্দ"},{"id":36516,"position":2,"text_uthmani":"جَآءَتِ","transliteration":"jāati","translation_bn":"আসবে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":36517,"position":3,"text_uthmani":"ٱلطَّآمَّةُ","transliteration":"l-ṭāmatu","translation_bn":"মহাসংকট","root":"طمم","lemma":"طَّا^مَّة","grammar_bn":"শব্দ"},{"id":36518,"position":4,"text_uthmani":"ٱلْكُبْرَىٰ","transliteration":"l-kub''rā","translation_bn":"মহা","root":"كبر","lemma":"كُبْرَىٰ","grammar_bn":"শব্দ"},{"id":36519,"position":5,"text_uthmani":"٣٤","transliteration":"","translation_bn":"(৩৪)","root":"—","lemma":"٣٤","grammar_bn":"মার্কার"}]'::jsonb, 'fa-idhā jāati l-ṭāmatu l-kub''rā', 'অতঃপর যখন মহাসংকট এসে যাবে।', 'But when there comes the greatest Overwhelming Calamity -', 'অতঃপর যখন মহাসংকট এসে যাবে।', 'But when there comes the greatest Overwhelming Calamity -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/079034.mp3', now()),
