  (79, 38, '', '[{"id":39875,"position":1,"text_uthmani":"وَءَاثَرَ","transliteration":"waāthara","translation_bn":"এবং অগ্রাধিকার দিয়েছে","root":"اثر","lemma":"ا^ثَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":39876,"position":2,"text_uthmani":"ٱلْحَيَوٰةَ","transliteration":"l-ḥayata","translation_bn":"জীবনকে","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":39877,"position":3,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"দুনিয়ার","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":39878,"position":4,"text_uthmani":"٣٨","transliteration":"","translation_bn":"(৩৮)","root":"—","lemma":"٣٨","grammar_bn":"মার্কার"}]'::jsonb, 'waāthara l-ḥayata l-dun''yā', 'আর পার্থিব জীবনকে (পরকালের উপর) প্রাধান্য দিয়েছিল', 'And preferred the life of the world,', 'আর পার্থিব জীবনকে (পরকালের উপর) প্রাধান্য দিয়েছিল', 'And preferred the life of the world,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/079038.mp3', now()),
  (79, 39, '', '[{"id":40439,"position":1,"text_uthmani":"فَإِنَّ","transliteration":"fa-inna","translation_bn":"অতঃপর নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":40440,"position":2,"text_uthmani":"ٱلْجَحِيمَ","transliteration":"l-jaḥīma","translation_bn":"দোযখই (হবে)","root":"جحم","lemma":"جَحِيم","grammar_bn":"শব্দ"},{"id":40441,"position":3,"text_uthmani":"هِىَ","transliteration":"hiya","translation_bn":"তাই","root":"—","lemma":"هِىَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":40442,"position":4,"text_uthmani":"ٱلْمَأْوَىٰ","transliteration":"l-mawā","translation_bn":"(তার) বাসস্থান","root":"اوي","lemma":"مَأْوَىٰ","grammar_bn":"শব্দ"},{"id":40443,"position":5,"text_uthmani":"٣٩","transliteration":"","translation_bn":"(৩৯)","root":"—","lemma":"٣٩","grammar_bn":"মার্কার"}]'::jsonb, 'fa-inna l-jaḥīma hiya l-mawā', 'জাহান্নামই হবে তার আবাসস্থল।', 'Then indeed, Hellfire will be [his] refuge.', 'জাহান্নামই হবে তার আবাসস্থল।', 'Then indeed, Hellfire will be [his] refuge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/079039.mp3', now()),
