  (80, 1, '', '[{"id":692,"position":1,"text_uthmani":"عَبَسَ","transliteration":"ʿabasa","translation_bn":"সে ভ্রুকুঞ্চিত করল","root":"عبس","lemma":"عَبَسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":693,"position":2,"text_uthmani":"وَتَوَلَّىٰٓ","transliteration":"watawallā","translation_bn":"ও (মুখ ফিরালো) অনাগ্রহ দেখালো","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":694,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'ʿabasa watawallā', '(নবী) মুখ ভার করল আর মুখ ঘুরিয়ে নিল।', 'The Prophet frowned and turned away', '(নবী) মুখ ভার করল আর মুখ ঘুরিয়ে নিল।', 'The Prophet frowned and turned away', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/080001.mp3', now()),
  (80, 2, '', '[{"id":1718,"position":1,"text_uthmani":"أَن","transliteration":"an","translation_bn":"(এ জন্যে) যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":1719,"position":2,"text_uthmani":"جَآءَهُ","transliteration":"jāahu","translation_bn":"তার (কাছে) এসেছে","root":"جيا","lemma":"جَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1720,"position":3,"text_uthmani":"ٱلْأَعْمَىٰ","transliteration":"l-aʿmā","translation_bn":"এক অন্ধ","root":"عمي","lemma":"أَعْمَىٰ","grammar_bn":"শব্দ"},{"id":1721,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'an jāahu l-aʿmā', '(কারণ সে যখন কুরায়শ সরদারদের সাথে আলোচনায় রত ছিল তখন) তার কাছে এক অন্ধ ব্যক্তি আসল।', 'Because there came to him the blind man, [interrupting].', '(কারণ সে যখন কুরায়শ সরদারদের সাথে আলোচনায় রত ছিল তখন) তার কাছে এক অন্ধ ব্যক্তি আসল।', 'Because there came to him the blind man, [interrupting].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/080002.mp3', now()),
  (80, 3, '', '[{"id":2814,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং কিসে","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":2815,"position":2,"text_uthmani":"يُدْرِيكَ","transliteration":"yud''rīka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2816,"position":3,"text_uthmani":"لَعَلَّهُۥ","transliteration":"laʿallahu","translation_bn":"সে হয়তো","root":"—","lemma":"لَعَلّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2817,"position":4,"text_uthmani":"يَزَّكَّىٰٓ","transliteration":"yazzakkā","translation_bn":"পরিশুদ্ধ হতো","root":"زكو","lemma":"تَزَكَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2818,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamā yud''rīka laʿallahu yazzakkā', '(হে নবী!) তুমি কি জান, সে হয়ত পরিশুদ্ধ হত।', 'But what would make you perceive, [O Muhammad], that perhaps he might be purified', '(হে নবী!) তুমি কি জান, সে হয়ত পরিশুদ্ধ হত।', 'But what would make you perceive, [O Muhammad], that perhaps he might be purified', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/080003.mp3', now()),
  (80, 4, '', '[{"id":4187,"position":1,"text_uthmani":"أَوْ","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4188,"position":2,"text_uthmani":"يَذَّكَّرُ","transliteration":"yadhakkaru","translation_bn":"উপদেশ গ্রহণ করতো","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4189,"position":3,"text_uthmani":"فَتَنفَعَهُ","transliteration":"fatanfaʿahu","translation_bn":"তাকে অতঃপর উপকার দিত","root":"نفع","lemma":"نَفَعَ","grammar_bn":"কারণবাচক (Cause)"},{"id":4190,"position":4,"text_uthmani":"ٱلذِّكْرَىٰٓ","transliteration":"l-dhik''rā","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"শব্দ"},{"id":4191,"position":5,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'aw yadhakkaru fatanfaʿahu l-dhik''rā', 'কিংবা উপদেশ গ্রহণ করত, ফলে উপদেশ তার উপকারে লাগত।', 'Or be reminded and the remembrance would benefit him?', 'কিংবা উপদেশ গ্রহণ করত, ফলে উপদেশ তার উপকারে লাগত।', 'Or be reminded and the remembrance would benefit him?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/080004.mp3', now()),
  (80, 5, '', '[{"id":5455,"position":1,"text_uthmani":"أَمَّا","transliteration":"ammā","translation_bn":"পক্ষান্তরে","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":5456,"position":2,"text_uthmani":"مَنِ","transliteration":"mani","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":5457,"position":3,"text_uthmani":"ٱسْتَغْنَىٰ","transliteration":"is''taghnā","translation_bn":"বেপরোয়া হলো (উন্নাসিকতা দেখালো)","root":"غني","lemma":"ٱسْتَغْنَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5458,"position":4,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ammā mani is''taghnā', 'পক্ষান্তরে যে পরোয়া করে না,', 'As for he who thinks himself without need,', 'পক্ষান্তরে যে পরোয়া করে না,', 'As for he who thinks himself without need,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/080005.mp3', now()),
