  (81, 24, '', '[{"id":27140,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":27141,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"সে","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":27142,"position":3,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"ব্যাপারে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27143,"position":4,"text_uthmani":"ٱلْغَيْبِ","transliteration":"l-ghaybi","translation_bn":"অদৃশ্যের","root":"غيب","lemma":"غَيْب","grammar_bn":"শব্দ"},{"id":27144,"position":5,"text_uthmani":"بِضَنِينٍۢ","transliteration":"biḍanīnin","translation_bn":"কৃপণ","root":"ضنن","lemma":"ضَنِين","grammar_bn":"অব্যয় (Preposition)"},{"id":27145,"position":6,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamā huwa ʿalā l-ghaybi biḍanīnin', 'সে গায়বের (জ্ঞান মানুষের কাছে পৌঁছে দেয়ার) ব্যাপারে কৃপণতা করে না।', 'And Muhammad is not a withholder of [knowledge of] the unseen.', 'সে গায়বের (জ্ঞান মানুষের কাছে পৌঁছে দেয়ার) ব্যাপারে কৃপণতা করে না।', 'And Muhammad is not a withholder of [knowledge of] the unseen.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/081024.mp3', now()),
  (81, 25, '', '[{"id":28153,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28154,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":28155,"position":3,"text_uthmani":"بِقَوْلِ","transliteration":"biqawli","translation_bn":"কথা","root":"قول","lemma":"قَوْل","grammar_bn":"অব্যয় (Preposition)"},{"id":28156,"position":4,"text_uthmani":"شَيْطَـٰنٍۢ","transliteration":"shayṭānin","translation_bn":"শয়তানের","root":"شطن","lemma":"شَيْطَٰن","grammar_bn":"বিশেষ্য (Noun)"},{"id":28157,"position":5,"text_uthmani":"رَّجِيمٍۢ","transliteration":"rajīmin","translation_bn":"অভিশপ্ত","root":"رجم","lemma":"رَجِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":28158,"position":6,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamā huwa biqawli shayṭānin rajīmin', 'আর তা কোন অভিশপ্ত শয়ত্বানের বাণী নয়।', 'And the Qur''an is not the word of a devil, expelled [from the heavens].', 'আর তা কোন অভিশপ্ত শয়ত্বানের বাণী নয়।', 'And the Qur''an is not the word of a devil, expelled [from the heavens].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/081025.mp3', now()),
  (81, 26, '', '[{"id":29117,"position":1,"text_uthmani":"فَأَيْنَ","transliteration":"fa-ayna","translation_bn":"অতএব কোথায়","root":"—","lemma":"أَيْن\r","grammar_bn":"শব্দ"},{"id":29118,"position":2,"text_uthmani":"تَذْهَبُونَ","transliteration":"tadhhabūna","translation_bn":"তোমরা চলেছ","root":"ذهب","lemma":"ذَهَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":29119,"position":3,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ayna tadhhabūna', 'কাজেই তোমরা (সত্যকে প্রত্যাখ্যান করে) কোথায় চলেছ?', 'So where are you going?', 'কাজেই তোমরা (সত্যকে প্রত্যাখ্যান করে) কোথায় চলেছ?', 'So where are you going?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/081026.mp3', now()),
  (81, 27, '', '[{"id":30297,"position":1,"text_uthmani":"إِنْ","transliteration":"in","translation_bn":"নয়","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":30298,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"তা","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":30299,"position":3,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":30300,"position":4,"text_uthmani":"ذِكْرٌۭ","transliteration":"dhik''run","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":30301,"position":5,"text_uthmani":"لِّلْعَـٰلَمِينَ","transliteration":"lil''ʿālamīna","translation_bn":"বিশ্ব-জগতের জন্যে","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"অব্যয় (Preposition)"},{"id":30302,"position":6,"text_uthmani":"٢٧","transliteration":"","translation_bn":"(২৭)","root":"—","lemma":"٢٧","grammar_bn":"মার্কার"}]'::jsonb, 'in huwa illā dhik''run lil''ʿālamīna', 'এটা তো কেবল বিশ্ববাসীদের জন্য উপদেশ।', 'It is not except a reminder to the worlds', 'এটা তো কেবল বিশ্ববাসীদের জন্য উপদেশ।', 'It is not except a reminder to the worlds', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/081027.mp3', now()),
  (81, 28, '', '[{"id":31325,"position":1,"text_uthmani":"لِمَن","transliteration":"liman","translation_bn":"তার জন্যে","root":"—","lemma":"مَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31326,"position":2,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"যে চায়","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31327,"position":3,"text_uthmani":"مِنكُمْ","transliteration":"minkum","translation_bn":"তোমাদের মধ্যে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":31328,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":31329,"position":5,"text_uthmani":"يَسْتَقِيمَ","transliteration":"yastaqīma","translation_bn":"সোজা চলতে","root":"قوم","lemma":"ٱسْتَقَٰمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":31330,"position":6,"text_uthmani":"٢٨","transliteration":"","translation_bn":"(২৮)","root":"—","lemma":"٢٨","grammar_bn":"মার্কার"}]'::jsonb, 'liman shāa minkum an yastaqīma', 'তার জন্য- যে তোমাদের মধ্যে সরল সঠিক পথে চলতে চায়।', 'For whoever wills among you to take a right course.', 'তার জন্য- যে তোমাদের মধ্যে সরল সঠিক পথে চলতে চায়।', 'For whoever wills among you to take a right course.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/081028.mp3', now()),
  (81, 29, '', '[{"id":32049,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":32050,"position":2,"text_uthmani":"تَشَآءُونَ","transliteration":"tashāūna","translation_bn":"(যা) তোমরা চাও (তা কিছু হয়)","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32051,"position":3,"text_uthmani":"إِلَّآ","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"সীমাবদ্ধতা (Restriction)"},{"id":32052,"position":4,"text_uthmani":"أَن","transliteration":"an","translation_bn":"যে","root":"—","lemma":"أَن\r","grammar_bn":"অধীনস্থ যোজক (Subordinating)"},{"id":32053,"position":5,"text_uthmani":"يَشَآءَ","transliteration":"yashāa","translation_bn":"চান","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":32054,"position":6,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":32055,"position":7,"text_uthmani":"رَبُّ","transliteration":"rabbu","translation_bn":"রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":32056,"position":8,"text_uthmani":"ٱلْعَـٰلَمِينَ","transliteration":"l-ʿālamīna","translation_bn":"জগতসমূহের","root":"علم","lemma":"عَٰلَمِين","grammar_bn":"শব্দ"},{"id":32057,"position":9,"text_uthmani":"٢٩","transliteration":"","translation_bn":"(২৯)","root":"—","lemma":"٢٩","grammar_bn":"মার্কার"}]'::jsonb, 'wamā tashāūna illā an yashāa l-lahu rabbu l-ʿālamīna', 'তোমরা ইচ্ছে কর না যদি বিশ্বজগতের প্রতিপালক আল্লাহ ইচ্ছে না করেন।', 'And you do not will except that Allah wills - Lord of the worlds.', 'তোমরা ইচ্ছে কর না যদি বিশ্বজগতের প্রতিপালক আল্লাহ ইচ্ছে না করেন।', 'And you do not will except that Allah wills - Lord of the worlds.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/081029.mp3', now())
