  (82, 1, '', '[{"id":699,"position":1,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":700,"position":2,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"l-samāu","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":701,"position":3,"text_uthmani":"ٱنفَطَرَتْ","transliteration":"infaṭarat","translation_bn":"ফেটে যাবে","root":"فطر","lemma":"ٱنفَطَرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":702,"position":4,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'idhā l-samāu infaṭarat', 'যখন আসমান ফেটে যাবে,', 'When the sky breaks apart', 'যখন আসমান ফেটে যাবে,', 'When the sky breaks apart', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082001.mp3', now()),
  (82, 2, '', '[{"id":1726,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1727,"position":2,"text_uthmani":"ٱلْكَوَاكِبُ","transliteration":"l-kawākibu","translation_bn":"তারাগুলো","root":"كوكب","lemma":"كَوْكَب","grammar_bn":"শব্দ"},{"id":1728,"position":3,"text_uthmani":"ٱنتَثَرَتْ","transliteration":"intatharat","translation_bn":"বিক্ষিপ্ত হবে","root":"نثر","lemma":"ٱنتَثَرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1729,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā l-kawākibu intatharat', 'যখন তারকাগুলো বিক্ষিপ্ত হয়ে (ঝরে) পড়বে,', 'And when the stars fall, scattering,', 'যখন তারকাগুলো বিক্ষিপ্ত হয়ে (ঝরে) পড়বে,', 'And when the stars fall, scattering,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082002.mp3', now()),
  (82, 3, '', '[{"id":2849,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2850,"position":2,"text_uthmani":"ٱلْبِحَارُ","transliteration":"l-biḥāru","translation_bn":"সাগরগুলো","root":"بحر","lemma":"بَحْر","grammar_bn":"শব্দ"},{"id":2851,"position":3,"text_uthmani":"فُجِّرَتْ","transliteration":"fujjirat","translation_bn":"উথলে উঠবে","root":"فجر","lemma":"فُجِّرَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2852,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā l-biḥāru fujjirat', 'সমুদ্রকে যখন উত্তাল করে তোলা হবে,', 'And when the seas are erupted', 'সমুদ্রকে যখন উত্তাল করে তোলা হবে,', 'And when the seas are erupted', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082003.mp3', now()),
  (82, 4, '', '[{"id":4214,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4215,"position":2,"text_uthmani":"ٱلْقُبُورُ","transliteration":"l-qubūru","translation_bn":"কবরগুলো","root":"قبر","lemma":"قَبْر","grammar_bn":"শব্দ"},{"id":4216,"position":3,"text_uthmani":"بُعْثِرَتْ","transliteration":"buʿ''thirat","translation_bn":"উন্মোচিত হবে","root":"بعثر","lemma":"بُعْثِرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4217,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā l-qubūru buʿ''thirat', 'যখন কবরস্থ মানুষদেরকে উঠানো হবে,', 'And when the [contents of] graves are scattered,', 'যখন কবরস্থ মানুষদেরকে উঠানো হবে,', 'And when the [contents of] graves are scattered,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082004.mp3', now()),
  (82, 5, '', '[{"id":5479,"position":1,"text_uthmani":"عَلِمَتْ","transliteration":"ʿalimat","translation_bn":"জানবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5480,"position":2,"text_uthmani":"نَفْسٌۭ","transliteration":"nafsun","translation_bn":"প্রত্যেক ব্যক্তি","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":5481,"position":3,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5482,"position":4,"text_uthmani":"قَدَّمَتْ","transliteration":"qaddamat","translation_bn":"সে আগে পাঠিয়েছে","root":"قدم","lemma":"قَدَّمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5483,"position":5,"text_uthmani":"وَأَخَّرَتْ","transliteration":"wa-akharat","translation_bn":"এবং পিছনে ছেড়েছে","root":"اخر","lemma":"أَخَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5484,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'ʿalimat nafsun mā qaddamat wa-akharat', 'তখন প্রত্যেকে জেনে নিবে সে কী আগে পাঠিয়েছিল, আর কী পেছনে ছেড়ে এসেছিল।', 'A soul will [then] know what it has put forth and kept back.', 'তখন প্রত্যেকে জেনে নিবে সে কী আগে পাঠিয়েছিল, আর কী পেছনে ছেড়ে এসেছিল।', 'A soul will [then] know what it has put forth and kept back.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082005.mp3', now()),
  (82, 6, '', '[{"id":6707,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":6708,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":6709,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কিসে","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6710,"position":4,"text_uthmani":"غَرَّكَ","transliteration":"gharraka","translation_bn":"তোমাকে ধোঁকা দিয়েছে","root":"غرر","lemma":"غَرَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6711,"position":5,"text_uthmani":"بِرَبِّكَ","transliteration":"birabbika","translation_bn":"তোমার রবের ব্যাপারে","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":6712,"position":6,"text_uthmani":"ٱلْكَرِيمِ","transliteration":"l-karīmi","translation_bn":"মহান","root":"كرم","lemma":"كَرِيم","grammar_bn":"শব্দ"},{"id":6713,"position":7,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-insānu mā gharraka birabbika l-karīmi', 'হে মানুষ! কিসে তোমাকে তোমার মহান প্রতিপালক সম্পর্কে ধোঁকায় ফেলে দিয়েছে?', 'O mankind, what has deceived you concerning your Lord, the Generous,', 'হে মানুষ! কিসে তোমাকে তোমার মহান প্রতিপালক সম্পর্কে ধোঁকায় ফেলে দিয়েছে?', 'O mankind, what has deceived you concerning your Lord, the Generous,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082006.mp3', now()),
  (82, 7, '', '[{"id":8056,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8057,"position":2,"text_uthmani":"خَلَقَكَ","transliteration":"khalaqaka","translation_bn":"তোমাকে সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8058,"position":3,"text_uthmani":"فَسَوَّىٰكَ","transliteration":"fasawwāka","translation_bn":"অতঃপর তোমাকে সুঠাম করেছেন","root":"سوي","lemma":"سَوَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8059,"position":4,"text_uthmani":"فَعَدَلَكَ","transliteration":"faʿadalaka","translation_bn":"অতঃপর তোমাকে  সুসামঞ্জস্য করেছেন","root":"عدل","lemma":"عَدَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8060,"position":5,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī khalaqaka fasawwāka faʿadalaka', 'যিনি তোমাকে সৃষ্টি করেছেন, অতঃপর তোমাকে সুঠাম করেছেন, অতঃপর তোমাকে করেছেন ভারসাম্যপূর্ণ।', 'Who created you, proportioned you, and balanced you?', 'যিনি তোমাকে সৃষ্টি করেছেন, অতঃপর তোমাকে সুঠাম করেছেন, অতঃপর তোমাকে করেছেন ভারসাম্যপূর্ণ।', 'Who created you, proportioned you, and balanced you?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082007.mp3', now()),
  (82, 8, '', '[{"id":9226,"position":1,"text_uthmani":"فِىٓ","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":9227,"position":2,"text_uthmani":"أَىِّ","transliteration":"ayyi","translation_bn":"যে","root":"—","lemma":"أَىّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":9228,"position":3,"text_uthmani":"صُورَةٍۢ","transliteration":"ṣūratin","translation_bn":"আকৃতিতে","root":"صور","lemma":"صُورَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9229,"position":4,"text_uthmani":"مَّا","transliteration":"mā","translation_bn":"(যা) যেমন","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":9230,"position":5,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"তিনি চেয়েছেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9231,"position":6,"text_uthmani":"رَكَّبَكَ","transliteration":"rakkabaka","translation_bn":"তোমাকে গঠন করেছেন","root":"ركب","lemma":"رَكَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":9232,"position":7,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'fī ayyi ṣūratin mā shāa rakkabaka', 'তিনি তোমাকে তাঁর ইচ্ছেমত আকৃতিতে গঠন করেছেন।', 'In whatever form He willed has He assembled you.', 'তিনি তোমাকে তাঁর ইচ্ছেমত আকৃতিতে গঠন করেছেন।', 'In whatever form He willed has He assembled you.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082008.mp3', now()),
  (82, 9, '', '[{"id":10425,"position":1,"text_uthmani":"كَلَّا","transliteration":"kallā","translation_bn":"কখনও নয়","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":10426,"position":2,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":10427,"position":3,"text_uthmani":"تُكَذِّبُونَ","transliteration":"tukadhibūna","translation_bn":"তোমারা মিথ্যা মনে করছ","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10428,"position":4,"text_uthmani":"بِٱلدِّينِ","transliteration":"bil-dīni","translation_bn":"শেষ বিচারকে","root":"دين","lemma":"دِين","grammar_bn":"অব্যয় (Preposition)"},{"id":10429,"position":5,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'kallā bal tukadhibūna bil-dīni', 'না (তোমাদের এই বিভ্রান্তি মোটেই সঠিক নয়), তোমরা তো (আখেরাতের) শাস্তি ও পুরস্কারকে অস্বীকার করে থাক;', 'No! But you deny the Recompense.', 'না (তোমাদের এই বিভ্রান্তি মোটেই সঠিক নয়), তোমরা তো (আখেরাতের) শাস্তি ও পুরস্কারকে অস্বীকার করে থাক;', 'No! But you deny the Recompense.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082009.mp3', now()),
  (82, 10, '', '[{"id":11831,"position":1,"text_uthmani":"وَإِنَّ","transliteration":"wa-inna","translation_bn":"এবং নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"শব্দ"},{"id":11832,"position":2,"text_uthmani":"عَلَيْكُمْ","transliteration":"ʿalaykum","translation_bn":"তোমাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":11833,"position":3,"text_uthmani":"لَحَـٰفِظِينَ","transliteration":"laḥāfiẓīna","translation_bn":"সংরক্ষক দল অবশ্যই (আছে)","root":"حفظ","lemma":"حَٰفِظ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":11834,"position":4,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wa-inna ʿalaykum laḥāfiẓīna', 'অবশ্যই তোমাদের উপর নিযুক্ত আছে তত্ত্বাবধায়কগণ;', 'And indeed, [appointed] over you are keepers,', 'অবশ্যই তোমাদের উপর নিযুক্ত আছে তত্ত্বাবধায়কগণ;', 'And indeed, [appointed] over you are keepers,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082010.mp3', now()),
