  (82, 15, '', '[{"id":17585,"position":1,"text_uthmani":"يَصْلَوْنَهَا","transliteration":"yaṣlawnahā","translation_bn":"সেখানে তারা প্রবেশ করবে","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":17586,"position":2,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"দিনে","root":"يوم","lemma":"يَوْم","grammar_bn":"কালবাচক (Time)"},{"id":17587,"position":3,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"বিচার","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":17588,"position":4,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'yaṣlawnahā yawma l-dīni', 'কর্মফলের দিন তারা তাতে প্রবেশ করবে।', 'They will [enter to] burn therein on the Day of Recompense,', 'কর্মফলের দিন তারা তাতে প্রবেশ করবে।', 'They will [enter to] burn therein on the Day of Recompense,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082015.mp3', now()),
  (82, 16, '', '[{"id":18628,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"এবং না","root":"—","lemma":"مَا","grammar_bn":"অবস্থাবাচক (Circumstantial)"},{"id":18629,"position":2,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":18630,"position":3,"text_uthmani":"عَنْهَا","transliteration":"ʿanhā","translation_bn":"তা থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18631,"position":4,"text_uthmani":"بِغَآئِبِينَ","transliteration":"bighāibīna","translation_bn":"অনুপস্থিত (থাকতে সক্ষম হবে)","root":"غيب","lemma":"غَا^ئِبِين","grammar_bn":"অব্যয় (Preposition)"},{"id":18632,"position":5,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wamā hum ʿanhā bighāibīna', 'তারা সেখান থেকে কক্ষনো উধাও হয়ে যেতে পারবে না।', 'And never therefrom will they be absent.', 'তারা সেখান থেকে কক্ষনো উধাও হয়ে যেতে পারবে না।', 'And never therefrom will they be absent.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082016.mp3', now()),
  (82, 17, '', '[{"id":19681,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং কিসে","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19682,"position":2,"text_uthmani":"أَدْرَىٰكَ","transliteration":"adrāka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19683,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি (সেই)","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":19684,"position":4,"text_uthmani":"يَوْمُ","transliteration":"yawmu","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":19685,"position":5,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"বিচারের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":19686,"position":6,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wamā adrāka mā yawmu l-dīni', 'তুমি কি জান কর্মফলের দিনটি কী?', 'And what can make you know what is the Day of Recompense?', 'তুমি কি জান কর্মফলের দিনটি কী?', 'And what can make you know what is the Day of Recompense?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082017.mp3', now()),
  (82, 18, '', '[{"id":20783,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":20784,"position":2,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"কিসে","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":20785,"position":3,"text_uthmani":"أَدْرَىٰكَ","transliteration":"adrāka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":20786,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি সেই","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":20787,"position":5,"text_uthmani":"يَوْمُ","transliteration":"yawmu","translation_bn":"দিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":20788,"position":6,"text_uthmani":"ٱلدِّينِ","transliteration":"l-dīni","translation_bn":"বিচারের","root":"دين","lemma":"دِين","grammar_bn":"শব্দ"},{"id":20789,"position":7,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'thumma mā adrāka mā yawmu l-dīni', 'আবার বলি, তুমি কি জান কর্মফলের দিনটি কী?', 'Then, what can make you know what is the Day of Recompense?', 'আবার বলি, তুমি কি জান কর্মফলের দিনটি কী?', 'Then, what can make you know what is the Day of Recompense?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082018.mp3', now()),
  (82, 19, '', '[{"id":21813,"position":1,"text_uthmani":"يَوْمَ","transliteration":"yawma","translation_bn":"সেদিন","root":"يوم","lemma":"يَوْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":21814,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":21815,"position":3,"text_uthmani":"تَمْلِكُ","transliteration":"tamliku","translation_bn":"সক্ষম হবে","root":"ملك","lemma":"مَلَكَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":21816,"position":4,"text_uthmani":"نَفْسٌۭ","transliteration":"nafsun","translation_bn":"কেউ","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":21817,"position":5,"text_uthmani":"لِّنَفْسٍۢ","transliteration":"linafsin","translation_bn":"কারও জন্যে","root":"نفس","lemma":"نَفْس","grammar_bn":"অব্যয় (Preposition)"},{"id":21818,"position":6,"text_uthmani":"شَيْـًۭٔا ۖ","transliteration":"shayan","translation_bn":"কিছু (করতে)","root":"شيا","lemma":"شَىْء","grammar_bn":"বিশেষ্য (Noun)"},{"id":21820,"position":7,"text_uthmani":"وَٱلْأَمْرُ","transliteration":"wal-amru","translation_bn":"এবং কর্তৃত্ব","root":"امر","lemma":"أَمْر","grammar_bn":"শব্দ"},{"id":21821,"position":8,"text_uthmani":"يَوْمَئِذٍۢ","transliteration":"yawma-idhin","translation_bn":"সেদিন (হবে কেবল)","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":21822,"position":9,"text_uthmani":"لِّلَّهِ","transliteration":"lillahi","translation_bn":"আল্লাহর জন্যে","root":"اله","lemma":"ٱللَّه","grammar_bn":"অব্যয় (Preposition)"},{"id":21823,"position":10,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'yawma lā tamliku nafsun linafsin shayan wal-amru yawma-idhin lillahi', 'সেদিন কোন মানুষ অপরের জন্য কিছু করার সামর্থ্য রাখবে না, সেদিন সকল কর্তৃত্ব থাকবে একমাত্র আল্লাহরই (ইখতিয়ারে)।', 'It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.', 'সেদিন কোন মানুষ অপরের জন্য কিছু করার সামর্থ্য রাখবে না, সেদিন সকল কর্তৃত্ব থাকবে একমাত্র আল্লাহরই (ইখতিয়ারে)।', 'It is the Day when a soul will not possess for another soul [power to do] a thing; and the command, that Day, is [entirely] with Allah.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/082019.mp3', now())
