  (83, 1, '', '[{"id":703,"position":1,"text_uthmani":"وَيْلٌۭ","transliteration":"waylun","translation_bn":"দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":704,"position":2,"text_uthmani":"لِّلْمُطَفِّفِينَ","transliteration":"lil''muṭaffifīna","translation_bn":"যারা ওজনে/ মাপে কম দেয়","root":"طفف","lemma":"مُطَفِّفِين","grammar_bn":"অব্যয় (Preposition)"},{"id":705,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'waylun lil''muṭaffifīna', 'দুর্ভোগ ঠকবাজদের জন্য (যারা মাপে বা ওজনে কম দেয়),', 'Woe to those who give less [than due],', 'দুর্ভোগ ঠকবাজদের জন্য (যারা মাপে বা ওজনে কম দেয়),', 'Woe to those who give less [than due],', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/083001.mp3', now()),
  (83, 2, '', '[{"id":1730,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1731,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":1732,"position":3,"text_uthmani":"ٱكْتَالُوا۟","transliteration":"ik''tālū","translation_bn":"মেপে নেয়","root":"كيل","lemma":"ٱكْتَالُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1733,"position":4,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"থেকে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1734,"position":5,"text_uthmani":"ٱلنَّاسِ","transliteration":"l-nāsi","translation_bn":"লোকদের","root":"نوس","lemma":"نَّاس","grammar_bn":"শব্দ"},{"id":1735,"position":6,"text_uthmani":"يَسْتَوْفُونَ","transliteration":"yastawfūna","translation_bn":"তারা পূর্ণমাত্রায় নেয়","root":"وفي","lemma":"يَسْتَوْفُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1736,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna idhā ik''tālū ʿalā l-nāsi yastawfūna', 'যারা লোকের কাছ থেকে মেপে নেয়ার সময় পুরামাত্রায় নেয়,', 'Who, when they take a measure from people, take in full.', 'যারা লোকের কাছ থেকে মেপে নেয়ার সময় পুরামাত্রায় নেয়,', 'Who, when they take a measure from people, take in full.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/083002.mp3', now()),
  (83, 3, '', '[{"id":2853,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"কিন্তু যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2854,"position":2,"text_uthmani":"كَالُوهُمْ","transliteration":"kālūhum","translation_bn":"তাদের মেপে দেয়","root":"كيل","lemma":"كَالُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2855,"position":3,"text_uthmani":"أَو","transliteration":"aw","translation_bn":"বা","root":"—","lemma":"أَو\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2856,"position":4,"text_uthmani":"وَّزَنُوهُمْ","transliteration":"wazanūhum","translation_bn":"তাদের ওজন করে দেয়","root":"وزن","lemma":"وَّزَنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2857,"position":5,"text_uthmani":"يُخْسِرُونَ","transliteration":"yukh''sirūna","translation_bn":"তারা কম করে দেয়","root":"خسر","lemma":"يُخْسِرُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2858,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā kālūhum aw wazanūhum yukh''sirūna', 'আর যখন তাদেরকে মেপে দেয় বা ওজন ক’রে দেয় তখন কম দেয়।', 'But if they give by measure or by weight to them, they cause loss.', 'আর যখন তাদেরকে মেপে দেয় বা ওজন ক’রে দেয় তখন কম দেয়।', 'But if they give by measure or by weight to them, they cause loss.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/083003.mp3', now()),
