  (83, 24, '', '[{"id":27146,"position":1,"text_uthmani":"تَعْرِفُ","transliteration":"taʿrifu","translation_bn":"তুমি চিনবে","root":"عرف","lemma":"عَرَفَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":27147,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27148,"position":3,"text_uthmani":"وُجُوهِهِمْ","transliteration":"wujūhihim","translation_bn":"তাদের চেহারার","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":27149,"position":4,"text_uthmani":"نَضْرَةَ","transliteration":"naḍrata","translation_bn":"দীপ্তি","root":"نضر","lemma":"نَضْرَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":27150,"position":5,"text_uthmani":"ٱلنَّعِيمِ","transliteration":"l-naʿīmi","translation_bn":"স্বাচ্ছন্দ্যের","root":"نعم","lemma":"نَعِيم","grammar_bn":"শব্দ"},{"id":27151,"position":6,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'taʿrifu fī wujūhihim naḍrata l-naʿīmi', 'তুমি তাদের মুখে আরাম আয়েশের উজ্জ্বলতা দেখতে পাবে।', 'You will recognize in their faces the radiance of pleasure.', 'তুমি তাদের মুখে আরাম আয়েশের উজ্জ্বলতা দেখতে পাবে।', 'You will recognize in their faces the radiance of pleasure.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/083024.mp3', now()),
  (83, 25, '', '[{"id":28159,"position":1,"text_uthmani":"يُسْقَوْنَ","transliteration":"yus''qawna","translation_bn":"তাদের পান করানো হবে","root":"سقي","lemma":"أَسْقَيْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28160,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28161,"position":3,"text_uthmani":"رَّحِيقٍۢ","transliteration":"raḥīqin","translation_bn":"বিশুদ্ধ পানীয়","root":"رحق","lemma":"رَّحِيق","grammar_bn":"বিশেষ্য (Noun)"},{"id":28162,"position":4,"text_uthmani":"مَّخْتُومٍ","transliteration":"makhtūmin","translation_bn":"মোহর করা","root":"ختم","lemma":"مَّخْتُوم","grammar_bn":"বিশেষণ (Adjective)"},{"id":28163,"position":5,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'yus''qawna min raḥīqin makhtūmin', 'তাদেরকে পান করানো হবে সীল-আঁটা উৎকৃষ্ট পানীয়।', 'They will be given to drink [pure] wine [which was] sealed.', 'তাদেরকে পান করানো হবে সীল-আঁটা উৎকৃষ্ট পানীয়।', 'They will be given to drink [pure] wine [which was] sealed.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/083025.mp3', now()),
