  (84, 1, '', '[{"id":706,"position":1,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":707,"position":2,"text_uthmani":"ٱلسَّمَآءُ","transliteration":"l-samāu","translation_bn":"আকাশ","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"শব্দ"},{"id":708,"position":3,"text_uthmani":"ٱنشَقَّتْ","transliteration":"inshaqqat","translation_bn":"ফেটে পড়বে","root":"شقق","lemma":"ٱنشَقَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":709,"position":4,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'idhā l-samāu inshaqqat', 'যখন আসমান ফেটে যাবে,', 'When the sky has split [open]', 'যখন আসমান ফেটে যাবে,', 'When the sky has split [open]', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084001.mp3', now()),
  (84, 2, '', '[{"id":1737,"position":1,"text_uthmani":"وَأَذِنَتْ","transliteration":"wa-adhinat","translation_bn":"এবং সে নির্দেশ পালন করবে","root":"اذن","lemma":"أَذِنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1738,"position":2,"text_uthmani":"لِرَبِّهَا","transliteration":"lirabbihā","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":1739,"position":3,"text_uthmani":"وَحُقَّتْ","transliteration":"waḥuqqat","translation_bn":"ও এটাই তার করণীয়","root":"حقق","lemma":"حَقَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1740,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-adhinat lirabbihā waḥuqqat', 'এবং স্বীয় রব-এর নির্দেশ পালন করবে, আর তাই তার করণীয়।', 'And has responded to its Lord and was obligated [to do so]', 'এবং স্বীয় রব-এর নির্দেশ পালন করবে, আর তাই তার করণীয়।', 'And has responded to its Lord and was obligated [to do so]', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084002.mp3', now()),
  (84, 3, '', '[{"id":2889,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2890,"position":2,"text_uthmani":"ٱلْأَرْضُ","transliteration":"l-arḍu","translation_bn":"পৃথিবী","root":"ارض","lemma":"أَرْض","grammar_bn":"শব্দ"},{"id":2891,"position":3,"text_uthmani":"مُدَّتْ","transliteration":"muddat","translation_bn":"সম্প্রসারিত করা হবে","root":"مدد","lemma":"مَدَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2892,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā l-arḍu muddat', 'এবং যমীনকে যখন প্রসারিত করা হবে,', 'And when the earth has been extended', 'এবং যমীনকে যখন প্রসারিত করা হবে,', 'And when the earth has been extended', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084003.mp3', now()),
  (84, 4, '', '[{"id":4224,"position":1,"text_uthmani":"وَأَلْقَتْ","transliteration":"wa-alqat","translation_bn":"এবং নিক্ষেপ করবে","root":"لقي","lemma":"أَلْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4225,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":4226,"position":3,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে আছে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4227,"position":4,"text_uthmani":"وَتَخَلَّتْ","transliteration":"watakhallat","translation_bn":"এবং তা শূন্য হয়ে যাবে","root":"خلو","lemma":"تَخَلَّتْ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4228,"position":5,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alqat mā fīhā watakhallat', 'আর তা তার ভেতরে যা আছে তা বাইরে নিক্ষেপ করবে ও খালি হয়ে যাবে।', 'And has cast out that within it and relinquished [it]', 'আর তা তার ভেতরে যা আছে তা বাইরে নিক্ষেপ করবে ও খালি হয়ে যাবে।', 'And has cast out that within it and relinquished [it]', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084004.mp3', now()),
  (84, 5, '', '[{"id":5488,"position":1,"text_uthmani":"وَأَذِنَتْ","transliteration":"wa-adhinat","translation_bn":"এবং সে নির্দেশ পালন করবে","root":"اذن","lemma":"أَذِنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5489,"position":2,"text_uthmani":"لِرَبِّهَا","transliteration":"lirabbihā","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":5490,"position":3,"text_uthmani":"وَحُقَّتْ","transliteration":"waḥuqqat","translation_bn":"এবং এটাই তার জন্য করণীয়","root":"حقق","lemma":"حَقَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5491,"position":4,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wa-adhinat lirabbihā waḥuqqat', 'এবং স্বীয় রব-এর নির্দেশ পালন করবে আর তাই তার করণীয়।', 'And has responded to its Lord and was obligated [to do so] -', 'এবং স্বীয় রব-এর নির্দেশ পালন করবে আর তাই তার করণীয়।', 'And has responded to its Lord and was obligated [to do so] -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084005.mp3', now()),
  (84, 6, '', '[{"id":6720,"position":1,"text_uthmani":"يَـٰٓأَيُّهَا","transliteration":"yāayyuhā","translation_bn":"হে","root":"—","lemma":"أَيُّهَا","grammar_bn":"সম্বোধন পদ (Vocative)"},{"id":6721,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":6722,"position":3,"text_uthmani":"إِنَّكَ","transliteration":"innaka","translation_bn":"নিশ্চয়ই তুমি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":6723,"position":4,"text_uthmani":"كَادِحٌ","transliteration":"kādiḥun","translation_bn":"পরিশ্রমকারী","root":"كدح","lemma":"كَادِح","grammar_bn":"বিশেষ্য (Noun)"},{"id":6724,"position":5,"text_uthmani":"إِلَىٰ","transliteration":"ilā","translation_bn":"দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6725,"position":6,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":6726,"position":7,"text_uthmani":"كَدْحًۭا","transliteration":"kadḥan","translation_bn":"কঠোর পরিশ্রম","root":"كدح","lemma":"كَدْح","grammar_bn":"বিশেষ্য (Noun)"},{"id":6727,"position":8,"text_uthmani":"فَمُلَـٰقِيهِ","transliteration":"famulāqīhi","translation_bn":"অতঃপর তাঁর (সাথে) সাক্ষাত করবে","root":"لقي","lemma":"مُلَٰقِي","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":6728,"position":9,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'yāayyuhā l-insānu innaka kādiḥun ilā rabbika kadḥan famulāqīhi', 'হে মানুষ! তোমাকে তোমার রব পর্যন্ত পৌঁছতে বহু কষ্ট স্বীকার করতে হবে, অতঃপর তুমি তাঁর সাক্ষাৎ লাভ করবে।', 'O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.', 'হে মানুষ! তোমাকে তোমার রব পর্যন্ত পৌঁছতে বহু কষ্ট স্বীকার করতে হবে, অতঃপর তুমি তাঁর সাক্ষাৎ লাভ করবে।', 'O mankind, indeed you are laboring toward your Lord with [great] exertion and will meet it.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084006.mp3', now()),
  (84, 7, '', '[{"id":8068,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"অতঃপর (তার) ব্যাপার","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":8069,"position":2,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যাকে","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":8070,"position":3,"text_uthmani":"أُوتِىَ","transliteration":"ūtiya","translation_bn":"দেয়া হবে","root":"اتي","lemma":"ا^تَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":8071,"position":4,"text_uthmani":"كِتَـٰبَهُۥ","transliteration":"kitābahu","translation_bn":"তার আমলনামা","root":"كتب","lemma":"كِتَٰب","grammar_bn":"বিশেষ্য (Noun)"},{"id":8072,"position":5,"text_uthmani":"بِيَمِينِهِۦ","transliteration":"biyamīnihi","translation_bn":"তার ডান হাতে","root":"يمن","lemma":"يَمِين","grammar_bn":"অব্যয় (Preposition)"},{"id":8073,"position":6,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā man ūtiya kitābahu biyamīnihi', 'অতঃপর যার ‘আমালনামা তার ডান হাতে দেয়া হবে।', 'Then as for he who is given his record in his right hand,', 'অতঃপর যার ‘আমালনামা তার ডান হাতে দেয়া হবে।', 'Then as for he who is given his record in his right hand,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084007.mp3', now()),
