  (84, 19, '', '[{"id":21524,"position":1,"text_uthmani":"لَتَرْكَبُنَّ","transliteration":"latarkabunna","translation_bn":"তোমরা অবশ্যই আরোহণ করবে","root":"ركب","lemma":"رَكِبَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":21525,"position":2,"text_uthmani":"طَبَقًا","transliteration":"ṭabaqan","translation_bn":"স্তর","root":"طبق","lemma":"طَبَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":21526,"position":3,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"থেকে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":21527,"position":4,"text_uthmani":"طَبَقٍۢ","transliteration":"ṭabaqin","translation_bn":"স্তরে","root":"طبق","lemma":"طَبَق","grammar_bn":"বিশেষ্য (Noun)"},{"id":21528,"position":5,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'latarkabunna ṭabaqan ʿan ṭabaqin', 'অবশ্যই তোমরা (আধ্যাত্মিক ও জাগতিক সর্বক্ষেত্রে) স্তরে স্তরে উন্নতির সিঁড়ি বেয়ে উর্ধ্বে উঠবে।', '[That] you will surely experience state after state.', 'অবশ্যই তোমরা (আধ্যাত্মিক ও জাগতিক সর্বক্ষেত্রে) স্তরে স্তরে উন্নতির সিঁড়ি বেয়ে উর্ধ্বে উঠবে।', '[That] you will surely experience state after state.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084019.mp3', now()),
  (84, 20, '', '[{"id":22967,"position":1,"text_uthmani":"فَمَا","transliteration":"famā","translation_bn":"অতএব হলো কি","root":"—","lemma":"مَا\r","grammar_bn":"শব্দ"},{"id":22968,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":22969,"position":3,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":22970,"position":4,"text_uthmani":"يُؤْمِنُونَ","transliteration":"yu''minūna","translation_bn":"তারা ঈমান আনে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":22971,"position":5,"text_uthmani":"٢٠","transliteration":"","translation_bn":"(২০)","root":"—","lemma":"٢٠","grammar_bn":"মার্কার"}]'::jsonb, 'famā lahum lā yu''minūna', 'অতএব তাদের কী হল যে তারা ঈমান আনে না?', 'So what is [the matter] with them [that] they do not believe,', 'অতএব তাদের কী হল যে তারা ঈমান আনে না?', 'So what is [the matter] with them [that] they do not believe,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084020.mp3', now()),
  (84, 21, '', '[{"id":23990,"position":1,"text_uthmani":"وَإِذَا","transliteration":"wa-idhā","translation_bn":"এবং যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23991,"position":2,"text_uthmani":"قُرِئَ","transliteration":"quri-a","translation_bn":"পাঠ করা হয়","root":"قرا","lemma":"قَرَأَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23992,"position":3,"text_uthmani":"عَلَيْهِمُ","transliteration":"ʿalayhimu","translation_bn":"তাদের কাছে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":23993,"position":4,"text_uthmani":"ٱلْقُرْءَانُ","transliteration":"l-qur''ānu","translation_bn":"কুর''আন","root":"قرا","lemma":"قُرْءَان","grammar_bn":"শব্দ"},{"id":23994,"position":5,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":23995,"position":6,"text_uthmani":"يَسْجُدُونَ ۩","transliteration":"yasjudūna","translation_bn":"তারা সিজদা করে","root":"سجد","lemma":"سَجَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":23997,"position":7,"text_uthmani":"٢١","transliteration":"","translation_bn":"(২১)","root":"—","lemma":"٢١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-idhā quri-a ʿalayhimu l-qur''ānu lā yasjudūna', 'আর তাদের কাছে যখন কুরআন পাঠ করা হয় তখন সাজদাহ করে না?[সাজদাহ]', 'And when the Qur''an is recited to them, they do not prostrate [to Allah]?', 'আর তাদের কাছে যখন কুরআন পাঠ করা হয় তখন সাজদাহ করে না?[সাজদাহ]', 'And when the Qur''an is recited to them, they do not prostrate [to Allah]?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084021.mp3', now()),
  (84, 22, '', '[{"id":25018,"position":1,"text_uthmani":"بَلِ","transliteration":"bali","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":25019,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25020,"position":3,"text_uthmani":"كَفَرُوا۟","transliteration":"kafarū","translation_bn":"কুফরি করেছে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25021,"position":4,"text_uthmani":"يُكَذِّبُونَ","transliteration":"yukadhibūna","translation_bn":"মিথ্যারোপ করছে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25022,"position":5,"text_uthmani":"٢٢","transliteration":"","translation_bn":"(২২)","root":"—","lemma":"٢٢","grammar_bn":"মার্কার"}]'::jsonb, 'bali alladhīna kafarū yukadhibūna', '(কুরআন শুনে সেজদা করা তো দূরের কথা) বরং কাফিররা ওটাকে অস্বীকারই করে।', 'But those who have disbelieved deny,', '(কুরআন শুনে সেজদা করা তো দূরের কথা) বরং কাফিররা ওটাকে অস্বীকারই করে।', 'But those who have disbelieved deny,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084022.mp3', now()),
  (84, 23, '', '[{"id":26088,"position":1,"text_uthmani":"وَٱللَّهُ","transliteration":"wal-lahu","translation_bn":"এবং আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"শব্দ"},{"id":26089,"position":2,"text_uthmani":"أَعْلَمُ","transliteration":"aʿlamu","translation_bn":"ভালো জানেন","root":"علم","lemma":"أَعْلَم","grammar_bn":"বিশেষ্য (Noun)"},{"id":26090,"position":3,"text_uthmani":"بِمَا","transliteration":"bimā","translation_bn":"ঐ বিষয়ে যা","root":"—","lemma":"مَا\r","grammar_bn":"অব্যয় (Preposition)"},{"id":26091,"position":4,"text_uthmani":"يُوعُونَ","transliteration":"yūʿūna","translation_bn":"তারা পোষণ করছে","root":"وعي","lemma":"أَوْعَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":26092,"position":5,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'wal-lahu aʿlamu bimā yūʿūna', 'আল্লাহ খুব ভাল করেই জানেন তারা (তাদের অন্তরে) কী লুকিয়ে রাখে।', 'And Allah is most knowing of what they keep within themselves.', 'আল্লাহ খুব ভাল করেই জানেন তারা (তাদের অন্তরে) কী লুকিয়ে রাখে।', 'And Allah is most knowing of what they keep within themselves.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084023.mp3', now()),
  (84, 24, '', '[{"id":26816,"position":1,"text_uthmani":"فَبَشِّرْهُم","transliteration":"fabashir''hum","translation_bn":"কাজেই তাদের সুসংবাদ দাও","root":"بشر","lemma":"بُشِّرَ","grammar_bn":"কারণবাচক (Cause)"},{"id":26817,"position":2,"text_uthmani":"بِعَذَابٍ","transliteration":"biʿadhābin","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"অব্যয় (Preposition)"},{"id":26818,"position":3,"text_uthmani":"أَلِيمٍ","transliteration":"alīmin","translation_bn":"যন্ত্রণাদায়ক","root":"الم","lemma":"أَلِيم","grammar_bn":"বিশেষণ (Adjective)"},{"id":26819,"position":4,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'fabashir''hum biʿadhābin alīmin', 'কাজেই তাদেরকে মর্মান্তিক ‘আযাবের সুসংবাদ দাও।', 'So give them tidings of a painful punishment,', 'কাজেই তাদেরকে মর্মান্তিক ‘আযাবের সুসংবাদ দাও।', 'So give them tidings of a painful punishment,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084024.mp3', now()),
  (84, 25, '', '[{"id":28164,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"তার ব্যতিক্রম","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":28165,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"(ঐসব লোক) যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":28166,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":28167,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"ও করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28168,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎকর্ম","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":28169,"position":6,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্য রয়েছে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":28170,"position":7,"text_uthmani":"أَجْرٌ","transliteration":"ajrun","translation_bn":"পুরস্কার","root":"اجر","lemma":"أَجْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":28171,"position":8,"text_uthmani":"غَيْرُ","transliteration":"ghayru","translation_bn":"অশেষ","root":"غير","lemma":"غَيْر","grammar_bn":"বিশেষণ (Adjective)"},{"id":28172,"position":9,"text_uthmani":"مَمْنُونٍۭ","transliteration":"mamnūnin","translation_bn":"অশেষ","root":"منن","lemma":"مَمْنُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":28173,"position":10,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'illā alladhīna āmanū waʿamilū l-ṣāliḥāti lahum ajrun ghayru mamnūnin', 'কিন্তু যারা ঈমান আনে আর সৎকাজ করে তারা বাদে; তাদের জন্য আছে অফুরন্ত প্রতিদান।', 'Except for those who believe and do righteous deeds. For them is a reward uninterrupted.', 'কিন্তু যারা ঈমান আনে আর সৎকাজ করে তারা বাদে; তাদের জন্য আছে অফুরন্ত প্রতিদান।', 'Except for those who believe and do righteous deeds. For them is a reward uninterrupted.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/084025.mp3', now())
