  (85, 1, '', '[{"id":712,"position":1,"text_uthmani":"وَٱلسَّمَآءِ","transliteration":"wal-samāi","translation_bn":"শপথ আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":713,"position":2,"text_uthmani":"ذَاتِ","transliteration":"dhāti","translation_bn":"বিশিষ্ট","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":714,"position":3,"text_uthmani":"ٱلْبُرُوجِ","transliteration":"l-burūji","translation_bn":"বুরুজ/ গ্রহ-নক্ষত্র","root":"برج","lemma":"بُرُوج","grammar_bn":"শব্দ"},{"id":715,"position":4,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wal-samāi dhāti l-burūji', 'শপথ গ্রহ-নক্ষত্র শোভিত আকাশের', 'By the sky containing great stars', 'শপথ গ্রহ-নক্ষত্র শোভিত আকাশের', 'By the sky containing great stars', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/085001.mp3', now()),
  (85, 2, '', '[{"id":1746,"position":1,"text_uthmani":"وَٱلْيَوْمِ","transliteration":"wal-yawmi","translation_bn":"এবং দিনের","root":"يوم","lemma":"يَوْم","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1747,"position":2,"text_uthmani":"ٱلْمَوْعُودِ","transliteration":"l-mawʿūdi","translation_bn":"প্রতিশ্রুত","root":"وعد","lemma":"مَوْعُود","grammar_bn":"শব্দ"},{"id":1748,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wal-yawmi l-mawʿūdi', 'আর সেদিনের যার ও‘য়াদা করা হয়েছে,', 'And [by] the promised Day', 'আর সেদিনের যার ও‘য়াদা করা হয়েছে,', 'And [by] the promised Day', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/085002.mp3', now()),
