  (86, 1, '', '[{"id":716,"position":1,"text_uthmani":"وَٱلسَّمَآءِ","transliteration":"wal-samāi","translation_bn":"শপথ আকাশের","root":"سمو","lemma":"سَمَا^ء","grammar_bn":"অব্যয় (Preposition)"},{"id":717,"position":2,"text_uthmani":"وَٱلطَّارِقِ","transliteration":"wal-ṭāriqi","translation_bn":"এবং রাত্রে আত্মপ্রকাশকারী (নক্ষত্রের)","root":"طرق","lemma":"طَّارِق","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":718,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wal-samāi wal-ṭāriqi', 'শপথ আসমানের আর যা রাতে আসে তার,', 'By the sky and the night comer -', 'শপথ আসমানের আর যা রাতে আসে তার,', 'By the sky and the night comer -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/086001.mp3', now()),
  (86, 2, '', '[{"id":1764,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং কিসে","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1765,"position":2,"text_uthmani":"أَدْرَىٰكَ","transliteration":"adrāka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1766,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি সেই","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":1767,"position":4,"text_uthmani":"ٱلطَّارِقُ","transliteration":"l-ṭāriqu","translation_bn":"রাতে আত্মপ্রকাশকারী","root":"طرق","lemma":"طَّارِق","grammar_bn":"শব্দ"},{"id":1768,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wamā adrāka mā l-ṭāriqu', 'তুমি কি জান যা রাতে আসে তা কী?', 'And what can make you know what is the night comer?', 'তুমি কি জান যা রাতে আসে তা কী?', 'And what can make you know what is the night comer?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/086002.mp3', now()),
  (86, 3, '', '[{"id":2882,"position":1,"text_uthmani":"ٱلنَّجْمُ","transliteration":"al-najmu","translation_bn":"নক্ষত্র","root":"نجم","lemma":"نَّجْم","grammar_bn":"শব্দ"},{"id":2883,"position":2,"text_uthmani":"ٱلثَّاقِبُ","transliteration":"l-thāqibu","translation_bn":"উজ্জ্বল","root":"ثقب","lemma":"ثَاقِب","grammar_bn":"শব্দ"},{"id":2884,"position":3,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'al-najmu l-thāqibu', 'উজ্জ্বল নক্ষত্র।', 'It is the piercing star -', 'উজ্জ্বল নক্ষত্র।', 'It is the piercing star -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/086003.mp3', now()),
  (86, 4, '', '[{"id":4239,"position":1,"text_uthmani":"إِن","transliteration":"in","translation_bn":"নেই","root":"—","lemma":"إِن\r","grammar_bn":"না-বোধক (Negative)"},{"id":4240,"position":2,"text_uthmani":"كُلُّ","transliteration":"kullu","translation_bn":"কোন","root":"كلل","lemma":"كُلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4241,"position":3,"text_uthmani":"نَفْسٍۢ","transliteration":"nafsin","translation_bn":"ব্যক্তি","root":"نفس","lemma":"نَفْس","grammar_bn":"বিশেষ্য (Noun)"},{"id":4242,"position":4,"text_uthmani":"لَّمَّا","transliteration":"lammā","translation_bn":"এ ছাড়া যে","root":"—","lemma":"لَّمَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":4243,"position":5,"text_uthmani":"عَلَيْهَا","transliteration":"ʿalayhā","translation_bn":"তার উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4244,"position":6,"text_uthmani":"حَافِظٌۭ","transliteration":"ḥāfiẓun","translation_bn":"তত্ত্বাবধায়ক","root":"حفظ","lemma":"حَٰفِظ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4245,"position":7,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'in kullu nafsin lammā ʿalayhā ḥāfiẓun', 'প্রত্যেক আত্মার সাথে একজন সংরক্ষক আছে।', 'There is no soul but that it has over it a protector.', 'প্রত্যেক আত্মার সাথে একজন সংরক্ষক আছে।', 'There is no soul but that it has over it a protector.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/086004.mp3', now()),
  (86, 5, '', '[{"id":5502,"position":1,"text_uthmani":"فَلْيَنظُرِ","transliteration":"falyanẓuri","translation_bn":"অতএব লক্ষ করা উচিৎ","root":"نظر","lemma":"نَّظَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5503,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষের","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":5504,"position":3,"text_uthmani":"مِمَّ","transliteration":"mimma","translation_bn":"কি থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5505,"position":4,"text_uthmani":"خُلِقَ","transliteration":"khuliqa","translation_bn":"সৃষ্টি করা হয়েছে (তাকে)","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5506,"position":5,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'falyanẓuri l-insānu mimma khuliqa', 'অতঃপর মানুষ চিন্তা করে দেখুক কোন জিনিস থেকে তাকে সৃষ্টি করা হয়েছে।', 'So let man observe from what he was created.', 'অতঃপর মানুষ চিন্তা করে দেখুক কোন জিনিস থেকে তাকে সৃষ্টি করা হয়েছে।', 'So let man observe from what he was created.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/086005.mp3', now()),
  (86, 6, '', '[{"id":6738,"position":1,"text_uthmani":"خُلِقَ","transliteration":"khuliqa","translation_bn":"সৃষ্টি করা হয়েছে","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6739,"position":2,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":6740,"position":3,"text_uthmani":"مَّآءٍۢ","transliteration":"māin","translation_bn":"পানি","root":"موه","lemma":"مَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":6741,"position":4,"text_uthmani":"دَافِقٍۢ","transliteration":"dāfiqin","translation_bn":"সবেগে স্খলিত","root":"دفق","lemma":"دَافِق","grammar_bn":"বিশেষণ (Adjective)"},{"id":6742,"position":5,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'khuliqa min māin dāfiqin', 'তাকে সৃষ্টি করা হয়েছে সবেগে বের হয়ে আসা পানি থেকে।', 'He was created from a fluid, ejected,', 'তাকে সৃষ্টি করা হয়েছে সবেগে বের হয়ে আসা পানি থেকে।', 'He was created from a fluid, ejected,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/086006.mp3', now()),
