VALUES
  (87, 1, '', '[{"id":719,"position":1,"text_uthmani":"سَبِّحِ","transliteration":"sabbiḥi","translation_bn":"মহিমা ঘোষণা করো","root":"سبح","lemma":"سَبَّحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":720,"position":2,"text_uthmani":"ٱسْمَ","transliteration":"is''ma","translation_bn":"নামের","root":"سمو","lemma":"ٱسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":721,"position":3,"text_uthmani":"رَبِّكَ","transliteration":"rabbika","translation_bn":"তোমার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":722,"position":4,"text_uthmani":"ٱلْأَعْلَى","transliteration":"l-aʿlā","translation_bn":"সুমহান","root":"علو","lemma":"أَعْلَىٰ","grammar_bn":"শব্দ"},{"id":723,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'sabbiḥi is''ma rabbika l-aʿlā', 'তোমার মহান প্রতিপালকের নামের পবিত্রতা ও মহিমা ঘোষণা কর।', 'Exalt the name of your Lord, the Most High,', 'তোমার মহান প্রতিপালকের নামের পবিত্রতা ও মহিমা ঘোষণা কর।', 'Exalt the name of your Lord, the Most High,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087001.mp3', now()),
  (87, 2, '', '[{"id":1760,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1761,"position":2,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1762,"position":3,"text_uthmani":"فَسَوَّىٰ","transliteration":"fasawwā","translation_bn":"অতঃপর সুবিন্যস্ত করেছেন","root":"سوي","lemma":"سَوَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1763,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī khalaqa fasawwā', 'যিনি সৃষ্টি করেছেন অতঃপর করেছেন (দেহের প্রতিটি অঙ্গকে) সামঞ্জস্যপূর্ণ।', 'Who created and proportioned', 'যিনি সৃষ্টি করেছেন অতঃপর করেছেন (দেহের প্রতিটি অঙ্গকে) সামঞ্জস্যপূর্ণ।', 'Who created and proportioned', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087002.mp3', now()),
  (87, 3, '', '[{"id":2885,"position":1,"text_uthmani":"وَٱلَّذِى","transliteration":"wa-alladhī","translation_bn":"এবং যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2886,"position":2,"text_uthmani":"قَدَّرَ","transliteration":"qaddara","translation_bn":"নিয়তি নির্ধারণ করেছেন","root":"قدر","lemma":"قَدَّرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2887,"position":3,"text_uthmani":"فَهَدَىٰ","transliteration":"fahadā","translation_bn":"অতঃপর পথ দেখিয়েছেন","root":"هدي","lemma":"هَدَى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2888,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhī qaddara fahadā', 'যিনি সকল বস্তুকে পরিমাণ মত সৃষ্টি করেছেন, অতঃপর (জীবনে চলার) পথনির্দেশ করেছেন।', 'And who destined and [then] guided', 'যিনি সকল বস্তুকে পরিমাণ মত সৃষ্টি করেছেন, অতঃপর (জীবনে চলার) পথনির্দেশ করেছেন।', 'And who destined and [then] guided', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087003.mp3', now()),
  (87, 4, '', '[{"id":3248,"position":1,"text_uthmani":"وَٱلَّذِىٓ","transliteration":"wa-alladhī","translation_bn":"এবং যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3249,"position":2,"text_uthmani":"أَخْرَجَ","transliteration":"akhraja","translation_bn":"উৎপন্ন করেছেন","root":"خرج","lemma":"أَخْرَجَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3250,"position":3,"text_uthmani":"ٱلْمَرْعَىٰ","transliteration":"l-marʿā","translation_bn":"তৃণ","root":"رعي","lemma":"مَرْعَىٰ","grammar_bn":"শব্দ"},{"id":3251,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-alladhī akhraja l-marʿā', 'যিনি তৃণ ইত্যাদি বের করেছেন।', 'And who brings out the pasture', 'যিনি তৃণ ইত্যাদি বের করেছেন।', 'And who brings out the pasture', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087004.mp3', now()),
  (87, 5, '', '[{"id":5507,"position":1,"text_uthmani":"فَجَعَلَهُۥ","transliteration":"fajaʿalahu","translation_bn":"অতঃপর তা পরিণত করেছেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5508,"position":2,"text_uthmani":"غُثَآءً","transliteration":"ghuthāan","translation_bn":"আবর্জনায়","root":"غثو","lemma":"غُثَا^ء","grammar_bn":"বিশেষ্য (Noun)"},{"id":5509,"position":3,"text_uthmani":"أَحْوَىٰ","transliteration":"aḥwā","translation_bn":"কালো","root":"حوي","lemma":"أَحْوَىٰ","grammar_bn":"বিশেষণ (Adjective)"},{"id":5510,"position":4,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fajaʿalahu ghuthāan aḥwā', 'অতঃপর তাকে কাল আবর্জনায় পরিণত করেছেন।', 'And [then] makes it black stubble.', 'অতঃপর তাকে কাল আবর্জনায় পরিণত করেছেন।', 'And [then] makes it black stubble.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087005.mp3', now()),
  (87, 6, '', '[{"id":6743,"position":1,"text_uthmani":"سَنُقْرِئُكَ","transliteration":"sanuq''ri-uka","translation_bn":"তোমাকে শীঘ্রই আমরা পড়িয়ে দেব","root":"قرا","lemma":"نُقْرِئُ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":6744,"position":2,"text_uthmani":"فَلَا","transliteration":"falā","translation_bn":"অতঃপর না","root":"—","lemma":"لَا\r","grammar_bn":"শব্দ"},{"id":6745,"position":3,"text_uthmani":"تَنسَىٰٓ","transliteration":"tansā","translation_bn":"তুমি ভুলবে","root":"نسي","lemma":"نَسِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6746,"position":4,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'sanuq''ri-uka falā tansā', 'আমি তোমাকে পড়িয়ে দেব, যার ফলে তুমি ভুলে যাবে না।', 'We will make you recite, [O Muhammad], and you will not forget,', 'আমি তোমাকে পড়িয়ে দেব, যার ফলে তুমি ভুলে যাবে না।', 'We will make you recite, [O Muhammad], and you will not forget,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087006.mp3', now()),
  (87, 7, '', '[{"id":8087,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ব্যতীত","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":8088,"position":2,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":8089,"position":3,"text_uthmani":"شَآءَ","transliteration":"shāa","translation_bn":"ইচ্ছা করেন","root":"شيا","lemma":"شَا^ءَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8090,"position":4,"text_uthmani":"ٱللَّهُ ۚ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":8092,"position":5,"text_uthmani":"إِنَّهُۥ","transliteration":"innahu","translation_bn":"নিশ্চয়ই তিনি","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8093,"position":6,"text_uthmani":"يَعْلَمُ","transliteration":"yaʿlamu","translation_bn":"জানেন","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8094,"position":7,"text_uthmani":"ٱلْجَهْرَ","transliteration":"l-jahra","translation_bn":"প্রকাশ্য (বিষয়)","root":"جهر","lemma":"جَهْر","grammar_bn":"শব্দ"},{"id":8095,"position":8,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"ও যা কিছু","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8096,"position":9,"text_uthmani":"يَخْفَىٰ","transliteration":"yakhfā","translation_bn":"কেউ গোপন করে","root":"خفي","lemma":"يَخْفَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8097,"position":10,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'illā mā shāa l-lahu innahu yaʿlamu l-jahra wamā yakhfā', 'তবে ওটা বাদে যেটা আল্লাহ (রহিত করার) ইচ্ছে করবেন। তিনি জানেন যা প্রকাশ্য আর যা গোপন।', 'Except what Allah should will. Indeed, He knows what is declared and what is hidden.', 'তবে ওটা বাদে যেটা আল্লাহ (রহিত করার) ইচ্ছে করবেন। তিনি জানেন যা প্রকাশ্য আর যা গোপন।', 'Except what Allah should will. Indeed, He knows what is declared and what is hidden.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087007.mp3', now()),
  (87, 8, '', '[{"id":9263,"position":1,"text_uthmani":"وَنُيَسِّرُكَ","transliteration":"wanuyassiruka","translation_bn":"এবং আমরা তোমাকে সহজ করে দিবো","root":"يسر","lemma":"يَسَّرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":9264,"position":2,"text_uthmani":"لِلْيُسْرَىٰ","transliteration":"lil''yus''rā","translation_bn":"সহজ (পন্থাকে)","root":"يسر","lemma":"يُسْرَىٰ","grammar_bn":"অব্যয় (Preposition)"},{"id":9265,"position":3,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wanuyassiruka lil''yus''rā', 'আমি তোমার জন্য সহজপথ (অনুসরণ করা) আরো সহজ করে দেব।', 'And We will ease you toward ease.', 'আমি তোমার জন্য সহজপথ (অনুসরণ করা) আরো সহজ করে দেব।', 'And We will ease you toward ease.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087008.mp3', now()),
  (87, 9, '', '[{"id":10457,"position":1,"text_uthmani":"فَذَكِّرْ","transliteration":"fadhakkir","translation_bn":"অতঃপর উপদেশ দাও","root":"ذكر","lemma":"ذُكِّرَ","grammar_bn":"শব্দ"},{"id":10458,"position":2,"text_uthmani":"إِن","transliteration":"in","translation_bn":"যদি","root":"—","lemma":"إِن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":10459,"position":3,"text_uthmani":"نَّفَعَتِ","transliteration":"nafaʿati","translation_bn":"কল্যাণকর হয়","root":"نفع","lemma":"نَفَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10460,"position":4,"text_uthmani":"ٱلذِّكْرَىٰ","transliteration":"l-dhik''rā","translation_bn":"উপদেশ","root":"ذكر","lemma":"ذِكْرَىٰ","grammar_bn":"শব্দ"},{"id":10461,"position":5,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'fadhakkir in nafaʿati l-dhik''rā', 'কাজেই তুমি উপদেশ দাও যদি উপদেশ উপকার দেয়।', 'So remind, if the reminder should benefit;', 'কাজেই তুমি উপদেশ দাও যদি উপদেশ উপকার দেয়।', 'So remind, if the reminder should benefit;', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087009.mp3', now()),
  (87, 10, '', '[{"id":11671,"position":1,"text_uthmani":"سَيَذَّكَّرُ","transliteration":"sayadhakkaru","translation_bn":"সে শীঘ্রই শিক্ষা নেবে","root":"ذكر","lemma":"تَذَكَّرَ","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":11672,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":11673,"position":3,"text_uthmani":"يَخْشَىٰ","transliteration":"yakhshā","translation_bn":"ভয় করে","root":"خشي","lemma":"خَشِىَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":11674,"position":4,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'sayadhakkaru man yakhshā', 'যে ভয় করে সে উপদেশ গ্রহণ করবে।', 'He who fears [Allah] will be reminded.', 'যে ভয় করে সে উপদেশ গ্রহণ করবে।', 'He who fears [Allah] will be reminded.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087010.mp3', now()),
  (87, 11, '', '[{"id":13050,"position":1,"text_uthmani":"وَيَتَجَنَّبُهَا","transliteration":"wayatajannabuhā","translation_bn":"আর তা পাশ কাটাবে/ উপেক্ষা করবে","root":"جنب","lemma":"يَتَجَنَّبُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":13051,"position":2,"text_uthmani":"ٱلْأَشْقَى","transliteration":"l-ashqā","translation_bn":"নিতান্তই হতভাগা","root":"شقو","lemma":"أَشْقَى","grammar_bn":"শব্দ"},{"id":13052,"position":3,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'wayatajannabuhā l-ashqā', 'আর তা উপেক্ষা করবে যে চরম হতভাগা।', 'But the wretched one will avoid it -', 'আর তা উপেক্ষা করবে যে চরম হতভাগা।', 'But the wretched one will avoid it -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087011.mp3', now()),
  (87, 12, '', '[{"id":14191,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":14192,"position":2,"text_uthmani":"يَصْلَى","transliteration":"yaṣlā","translation_bn":"প্রবেশ করবে","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":14193,"position":3,"text_uthmani":"ٱلنَّارَ","transliteration":"l-nāra","translation_bn":"আগুনে","root":"نور","lemma":"نَار","grammar_bn":"শব্দ"},{"id":14194,"position":4,"text_uthmani":"ٱلْكُبْرَىٰ","transliteration":"l-kub''rā","translation_bn":"ভয়াবহ","root":"كبر","lemma":"كُبْرَىٰ","grammar_bn":"শব্দ"},{"id":14195,"position":5,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī yaṣlā l-nāra l-kub''rā', 'যে ভয়াবহ আগুনে প্রবেশ করবে।', '[He] who will [enter and] burn in the greatest Fire,', 'যে ভয়াবহ আগুনে প্রবেশ করবে।', '[He] who will [enter and] burn in the greatest Fire,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087012.mp3', now()),
  (87, 13, '', '[{"id":15406,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15407,"position":2,"text_uthmani":"لَا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":15408,"position":3,"text_uthmani":"يَمُوتُ","transliteration":"yamūtu","translation_bn":"সে মরবে","root":"موت","lemma":"مَّاتَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15409,"position":4,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15410,"position":5,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15411,"position":6,"text_uthmani":"يَحْيَىٰ","transliteration":"yaḥyā","translation_bn":"বাঁচবে","root":"حيي","lemma":"حَىَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":15412,"position":7,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'thumma lā yamūtu fīhā walā yaḥyā', 'অতঃপর সেখানে সে না (মরার মত) মরবে, আর না (বাঁচার মত) বাঁচবে।', 'Neither dying therein nor living.', 'অতঃপর সেখানে সে না (মরার মত) মরবে, আর না (বাঁচার মত) বাঁচবে।', 'Neither dying therein nor living.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087013.mp3', now()),
  (87, 14, '', '[{"id":16451,"position":1,"text_uthmani":"قَدْ","transliteration":"qad","translation_bn":"নিশ্চয়ই","root":"—","lemma":"قَد\r","grammar_bn":"নিশ্চয়তাবোধক (Certainty)"},{"id":16452,"position":2,"text_uthmani":"أَفْلَحَ","transliteration":"aflaḥa","translation_bn":"সে সাফল্য পেলো","root":"فلح","lemma":"أَفْلَحَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16453,"position":3,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":16454,"position":4,"text_uthmani":"تَزَكَّىٰ","transliteration":"tazakkā","translation_bn":"পবিত্র হলো","root":"زكو","lemma":"تَزَكَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16455,"position":5,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'qad aflaḥa man tazakkā', 'সাফল্য লাভ করবে সে যে নিজেকে পরিশুদ্ধ করে,', 'He has certainly succeeded who purifies himself', 'সাফল্য লাভ করবে সে যে নিজেকে পরিশুদ্ধ করে,', 'He has certainly succeeded who purifies himself', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087014.mp3', now()),
  (87, 15, '', '[{"id":17611,"position":1,"text_uthmani":"وَذَكَرَ","transliteration":"wadhakara","translation_bn":"স্মরণ করল","root":"ذكر","lemma":"ذَكَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17612,"position":2,"text_uthmani":"ٱسْمَ","transliteration":"is''ma","translation_bn":"নাম","root":"سمو","lemma":"ٱسْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":17613,"position":3,"text_uthmani":"رَبِّهِۦ","transliteration":"rabbihi","translation_bn":"তার রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17614,"position":4,"text_uthmani":"فَصَلَّىٰ","transliteration":"faṣallā","translation_bn":"অতঃপর সে  সালাত পড়ল","root":"صلو","lemma":"صَلَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17615,"position":5,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'wadhakara is''ma rabbihi faṣallā', 'আর তার প্রতিপালকের নাম স্মরণ করে ও নামায কায়েম করে।', 'And mentions the name of his Lord and prays.', 'আর তার প্রতিপালকের নাম স্মরণ করে ও নামায কায়েম করে।', 'And mentions the name of his Lord and prays.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087015.mp3', now()),
  (87, 16, '', '[{"id":18745,"position":1,"text_uthmani":"بَلْ","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":18746,"position":2,"text_uthmani":"تُؤْثِرُونَ","transliteration":"tu''thirūna","translation_bn":"তোমরা প্রাধান্য দাও","root":"اثر","lemma":"ا^ثَرَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18747,"position":3,"text_uthmani":"ٱلْحَيَوٰةَ","transliteration":"l-ḥayata","translation_bn":"জীবনকে","root":"حيي","lemma":"حَيَوٰة","grammar_bn":"শব্দ"},{"id":18748,"position":4,"text_uthmani":"ٱلدُّنْيَا","transliteration":"l-dun''yā","translation_bn":"দুনিয়ার/ পার্থিব","root":"دنو","lemma":"دُّنْيَا","grammar_bn":"শব্দ"},{"id":18749,"position":5,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'bal tu''thirūna l-ḥayata l-dun''yā', 'কিন্তু তোমরা তো দুনিয়ার জীবনকেই প্রাধান্য দাও,', 'But you prefer the worldly life,', 'কিন্তু তোমরা তো দুনিয়ার জীবনকেই প্রাধান্য দাও,', 'But you prefer the worldly life,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087016.mp3', now()),
  (87, 17, '', '[{"id":19712,"position":1,"text_uthmani":"وَٱلْـَٔاخِرَةُ","transliteration":"wal-ākhiratu","translation_bn":"অথচ পরকাল","root":"اخر","lemma":"ا^خِر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19713,"position":2,"text_uthmani":"خَيْرٌۭ","transliteration":"khayrun","translation_bn":"উত্তম","root":"خير","lemma":"خَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":19714,"position":3,"text_uthmani":"وَأَبْقَىٰٓ","transliteration":"wa-abqā","translation_bn":"ও স্থায়ী","root":"بقي","lemma":"أَبْقَىٰ^","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":19715,"position":4,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'wal-ākhiratu khayrun wa-abqā', 'অথচ আখিরাতই অধিক উৎকৃষ্ট ও স্থায়ী।', 'While the Hereafter is better and more enduring.', 'অথচ আখিরাতই অধিক উৎকৃষ্ট ও স্থায়ী।', 'While the Hereafter is better and more enduring.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087017.mp3', now()),
  (87, 18, '', '[{"id":20793,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":20794,"position":2,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এটা (ছিল)","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":20795,"position":3,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":20796,"position":4,"text_uthmani":"ٱلصُّحُفِ","transliteration":"l-ṣuḥufi","translation_bn":"সহীফাসমূহের","root":"صحف","lemma":"صُحُف","grammar_bn":"শব্দ"},{"id":20797,"position":5,"text_uthmani":"ٱلْأُولَىٰ","transliteration":"l-ūlā","translation_bn":"পূর্ববর্তী","root":"اول","lemma":"أَوَّل","grammar_bn":"শব্দ"},{"id":20798,"position":6,"text_uthmani":"١٨","transliteration":"","translation_bn":"(১৮)","root":"—","lemma":"١٨","grammar_bn":"মার্কার"}]'::jsonb, 'inna hādhā lafī l-ṣuḥufi l-ūlā', 'আগের কিতাবগুলোতে এ কথা (লিপিবদ্ধ) আছে,', 'Indeed, this is in the former scriptures,', 'আগের কিতাবগুলোতে এ কথা (লিপিবদ্ধ) আছে,', 'Indeed, this is in the former scriptures,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087018.mp3', now()),
  (87, 19, '', '[{"id":21185,"position":1,"text_uthmani":"صُحُفِ","transliteration":"ṣuḥufi","translation_bn":"সহীফাসমূহে","root":"صحف","lemma":"صُحُف","grammar_bn":"বিশেষ্য (Noun)"},{"id":21186,"position":2,"text_uthmani":"إِبْرَٰهِيمَ","transliteration":"ib''rāhīma","translation_bn":"ইব্রাহীমের","root":"—","lemma":"إِبْرَاهِيم","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":21187,"position":3,"text_uthmani":"وَمُوسَىٰ","transliteration":"wamūsā","translation_bn":"ও মূসার","root":"—","lemma":"مُوسَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":21188,"position":4,"text_uthmani":"١٩","transliteration":"","translation_bn":"(১৯)","root":"—","lemma":"١٩","grammar_bn":"মার্কার"}]'::jsonb, 'ṣuḥufi ib''rāhīma wamūsā', 'ইবরাহীম ও মূসার কিতাবে।', 'The scriptures of Abraham and Moses.', 'ইবরাহীম ও মূসার কিতাবে।', 'The scriptures of Abraham and Moses.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/087019.mp3', now())
