  (88, 1, '', '[{"id":724,"position":1,"text_uthmani":"هَلْ","transliteration":"hal","translation_bn":"কি","root":"—","lemma":"هَل\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":725,"position":2,"text_uthmani":"أَتَىٰكَ","transliteration":"atāka","translation_bn":"তোমার কাছে পৌঁছেছে","root":"اتي","lemma":"أَتَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":726,"position":3,"text_uthmani":"حَدِيثُ","transliteration":"ḥadīthu","translation_bn":"সংবাদ","root":"حدث","lemma":"حَدِيث","grammar_bn":"বিশেষ্য (Noun)"},{"id":727,"position":4,"text_uthmani":"ٱلْغَـٰشِيَةِ","transliteration":"l-ghāshiyati","translation_bn":"আচ্ছন্নকারী (ক্বিয়ামাতের)","root":"غشو","lemma":"غَٰشِيَة","grammar_bn":"শব্দ"},{"id":728,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'hal atāka ḥadīthu l-ghāshiyati', '(সব কিছুকে) আচ্ছন্নকারী কিয়ামাতের খবর তোমার কাছে পৌঁছেছে কি?', 'Has there reached you the report of the Overwhelming [event]?', '(সব কিছুকে) আচ্ছন্নকারী কিয়ামাতের খবর তোমার কাছে পৌঁছেছে কি?', 'Has there reached you the report of the Overwhelming [event]?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088001.mp3', now()),
  (88, 2, '', '[{"id":1774,"position":1,"text_uthmani":"وُجُوهٌۭ","transliteration":"wujūhun","translation_bn":"(অনেকের) মুখমণ্ডল","root":"وجه","lemma":"وَجْه","grammar_bn":"বিশেষ্য (Noun)"},{"id":1775,"position":2,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":1776,"position":3,"text_uthmani":"خَـٰشِعَةٌ","transliteration":"khāshiʿatun","translation_bn":"অবনত (হবে)","root":"خشع","lemma":"خَاشِع","grammar_bn":"বিশেষ্য (Noun)"},{"id":1777,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wujūhun yawma-idhin khāshiʿatun', 'কতক মুখ সেদিন নীচু হবে', '[Some] faces, that Day, will be humbled,', 'কতক মুখ সেদিন নীচু হবে', '[Some] faces, that Day, will be humbled,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088002.mp3', now()),
  (88, 3, '', '[{"id":2859,"position":1,"text_uthmani":"عَامِلَةٌۭ","transliteration":"ʿāmilatun","translation_bn":"ক্লিষ্ট (হবে)","root":"عمل","lemma":"عَامِلَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":2860,"position":2,"text_uthmani":"نَّاصِبَةٌۭ","transliteration":"nāṣibatun","translation_bn":"ক্লান্ত (হবে)","root":"نصب","lemma":"نَّاصِبَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":2861,"position":3,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'ʿāmilatun nāṣibatun', 'হবে কর্মক্লান্ত, শ্রান্ত।', 'Working [hard] and exhausted.', 'হবে কর্মক্লান্ত, শ্রান্ত।', 'Working [hard] and exhausted.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088003.mp3', now()),
  (88, 4, '', '[{"id":3332,"position":1,"text_uthmani":"تَصْلَىٰ","transliteration":"taṣlā","translation_bn":"প্রবেশ করবে","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ক্রিয়া (Verb)"},{"id":3333,"position":2,"text_uthmani":"نَارًا","transliteration":"nāran","translation_bn":"আগুনে","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":3334,"position":3,"text_uthmani":"حَامِيَةًۭ","transliteration":"ḥāmiyatan","translation_bn":"উত্তপ্ত","root":"حمي","lemma":"حَامِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":3335,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'taṣlā nāran ḥāmiyatan', 'তারা জ্বলন্ত আগুনে প্রবেশ করবে।', 'They will [enter to] burn in an intensely hot Fire.', 'তারা জ্বলন্ত আগুনে প্রবেশ করবে।', 'They will [enter to] burn in an intensely hot Fire.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088004.mp3', now()),
  (88, 5, '', '[{"id":4671,"position":1,"text_uthmani":"تُسْقَىٰ","transliteration":"tus''qā","translation_bn":"পান করানো হবে (পানি)","root":"سقي","lemma":"سَقَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4672,"position":2,"text_uthmani":"مِنْ","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4673,"position":3,"text_uthmani":"عَيْنٍ","transliteration":"ʿaynin","translation_bn":"ঝর্ণা","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":4674,"position":4,"text_uthmani":"ءَانِيَةٍۢ","transliteration":"āniyatin","translation_bn":"ফুটন্ত","root":"اني","lemma":"ءَانِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":4675,"position":5,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'tus''qā min ʿaynin āniyatin', 'টগবগে ফুটন্ত ঝর্ণা থেকে তাদেরকে পান করানো হবে।', 'They will be given drink from a boiling spring.', 'টগবগে ফুটন্ত ঝর্ণা থেকে তাদেরকে পান করানো হবে।', 'They will be given drink from a boiling spring.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088005.mp3', now()),
  (88, 6, '', '[{"id":5859,"position":1,"text_uthmani":"لَّيْسَ","transliteration":"laysa","translation_bn":"নেই","root":"ليس","lemma":"لَّيْسَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5860,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদের জন্যে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":5861,"position":3,"text_uthmani":"طَعَامٌ","transliteration":"ṭaʿāmun","translation_bn":"(অন্য কোনো) খাদ্য","root":"طعم","lemma":"طَعَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":5862,"position":4,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"এ ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":5863,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5864,"position":6,"text_uthmani":"ضَرِيعٍۢ","transliteration":"ḍarīʿin","translation_bn":"শুকনো কাঁটাযুক্ত ঝাড়","root":"ضرع","lemma":"ضَرِيع","grammar_bn":"বিশেষ্য (Noun)"},{"id":5865,"position":7,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'laysa lahum ṭaʿāmun illā min ḍarīʿin', 'কাঁটাযুক্ত শুকনো ঘাস ছাড়া তাদের জন্য আর কোন খাদ্য থাকবে না।', 'For them there will be no food except from a poisonous, thorny plant', 'কাঁটাযুক্ত শুকনো ঘাস ছাড়া তাদের জন্য আর কোন খাদ্য থাকবে না।', 'For them there will be no food except from a poisonous, thorny plant', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088006.mp3', now()),
  (88, 7, '', '[{"id":7328,"position":1,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":7329,"position":2,"text_uthmani":"يُسْمِنُ","transliteration":"yus''minu","translation_bn":"পুষ্ট করবে (তা)","root":"سمن","lemma":"يُسْمِنُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7330,"position":3,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"আর না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7331,"position":4,"text_uthmani":"يُغْنِى","transliteration":"yugh''nī","translation_bn":"মেটাবে","root":"غني","lemma":"أَغْنَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7332,"position":5,"text_uthmani":"مِن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7333,"position":6,"text_uthmani":"جُوعٍۢ","transliteration":"jūʿin","translation_bn":"ক্ষুধা","root":"جوع","lemma":"جُوع","grammar_bn":"বিশেষ্য (Noun)"},{"id":7334,"position":7,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'lā yus''minu walā yugh''nī min jūʿin', 'যা পুষ্টিসাধন করবে না, আর ক্ষুধাও মিটাবে না।', 'Which neither nourishes nor avails against hunger.', 'যা পুষ্টিসাধন করবে না, আর ক্ষুধাও মিটাবে না।', 'Which neither nourishes nor avails against hunger.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088007.mp3', now()),
