  (88, 23, '', '[{"id":25796,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"তবে","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":25797,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":25798,"position":3,"text_uthmani":"تَوَلَّىٰ","transliteration":"tawallā","translation_bn":"মুখ ফিরায়","root":"ولي","lemma":"تَوَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":25799,"position":4,"text_uthmani":"وَكَفَرَ","transliteration":"wakafara","translation_bn":"ও অবিশ্বাস করে","root":"كفر","lemma":"كَفَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":25800,"position":5,"text_uthmani":"٢٣","transliteration":"","translation_bn":"(২৩)","root":"—","lemma":"٢٣","grammar_bn":"মার্কার"}]'::jsonb, 'illā man tawallā wakafara', 'তবে কেউ কুফুরি করলে এবং মুখ ফিরিয়ে নিলে', 'However, he who turns away and disbelieves -', 'তবে কেউ কুফুরি করলে এবং মুখ ফিরিয়ে নিলে', 'However, he who turns away and disbelieves -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088023.mp3', now()),
  (88, 24, '', '[{"id":26853,"position":1,"text_uthmani":"فَيُعَذِّبُهُ","transliteration":"fayuʿadhibuhu","translation_bn":"অতঃপর তাকে শাস্তি দেবেন","root":"عذب","lemma":"عَذَّبَ","grammar_bn":"শব্দ"},{"id":26854,"position":2,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ্‌","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":26855,"position":3,"text_uthmani":"ٱلْعَذَابَ","transliteration":"l-ʿadhāba","translation_bn":"শাস্তি","root":"عذب","lemma":"عَذَاب","grammar_bn":"শব্দ"},{"id":26856,"position":4,"text_uthmani":"ٱلْأَكْبَرَ","transliteration":"l-akbara","translation_bn":"মহা","root":"كبر","lemma":"أَكْبَر","grammar_bn":"শব্দ"},{"id":26857,"position":5,"text_uthmani":"٢٤","transliteration":"","translation_bn":"(২৪)","root":"—","lemma":"٢٤","grammar_bn":"মার্কার"}]'::jsonb, 'fayuʿadhibuhu l-lahu l-ʿadhāba l-akbara', 'আল্লাহ তাকে মহাশাস্তিতে শাস্তি দেবেন।', 'Then Allah will punish him with the greatest punishment.', 'আল্লাহ তাকে মহাশাস্তিতে শাস্তি দেবেন।', 'Then Allah will punish him with the greatest punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088024.mp3', now()),
  (88, 25, '', '[{"id":27843,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":27844,"position":2,"text_uthmani":"إِلَيْنَآ","transliteration":"ilaynā","translation_bn":"আমাদের দিকে","root":"—","lemma":"إِلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":27845,"position":3,"text_uthmani":"إِيَابَهُمْ","transliteration":"iyābahum","translation_bn":"তাদের প্রত্যাবর্তন হবে","root":"اوب","lemma":"إِيَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":27846,"position":4,"text_uthmani":"٢٥","transliteration":"","translation_bn":"(২৫)","root":"—","lemma":"٢٥","grammar_bn":"মার্কার"}]'::jsonb, 'inna ilaynā iyābahum', 'তাদেরকে আমার কাছেই ফিরে আসতে হবে।', 'Indeed, to Us is their return.', 'তাদেরকে আমার কাছেই ফিরে আসতে হবে।', 'Indeed, to Us is their return.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088025.mp3', now()),
  (88, 26, '', '[{"id":28569,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"অতঃপর","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":28570,"position":2,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":28571,"position":3,"text_uthmani":"عَلَيْنَا","transliteration":"ʿalaynā","translation_bn":"আমাদের উপর (দায়িত্ব)","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":28572,"position":4,"text_uthmani":"حِسَابَهُم","transliteration":"ḥisābahum","translation_bn":"তাদের হিসাবের","root":"حسب","lemma":"حِسَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":28573,"position":5,"text_uthmani":"٢٦","transliteration":"","translation_bn":"(২৬)","root":"—","lemma":"٢٦","grammar_bn":"মার্কার"}]'::jsonb, 'thumma inna ʿalaynā ḥisābahum', 'অতঃপর তাদের হিসাব নেয়া তো আমারই কাজ।', 'Then indeed, upon Us is their account.', 'অতঃপর তাদের হিসাব নেয়া তো আমারই কাজ।', 'Then indeed, upon Us is their account.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/088026.mp3', now())
