  (89, 3, '', '[{"id":2408,"position":1,"text_uthmani":"وَٱلشَّفْعِ","transliteration":"wal-shafʿi","translation_bn":"শপথ জোড়ের","root":"شفع","lemma":"شَّفْع","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2409,"position":2,"text_uthmani":"وَٱلْوَتْرِ","transliteration":"wal-watri","translation_bn":"ও বেজোড়ের","root":"وتر","lemma":"وَتْر","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2410,"position":3,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wal-shafʿi wal-watri', 'জোড় ও বেজোড়ের শপথ,', 'And [by] the even [number] and the odd', 'জোড় ও বেজোড়ের শপথ,', 'And [by] the even [number] and the odd', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089003.mp3', now()),
  (89, 4, '', '[{"id":3817,"position":1,"text_uthmani":"وَٱلَّيْلِ","transliteration":"wa-al-layli","translation_bn":"শপথ রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3818,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":3819,"position":3,"text_uthmani":"يَسْرِ","transliteration":"yasri","translation_bn":"তা যেতে থাকে","root":"سري","lemma":"يَسْرِ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3820,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-al-layli idhā yasri', 'আর রাতের শপথ যখন তা গত হতে থাকে,', 'And [by] the night when it passes,', 'আর রাতের শপথ যখন তা গত হতে থাকে,', 'And [by] the night when it passes,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089004.mp3', now()),
