  (89, 12, '', '[{"id":14074,"position":1,"text_uthmani":"فَأَكْثَرُوا۟","transliteration":"fa-aktharū","translation_bn":"আর বৃদ্ধি করেছিল","root":"كثر","lemma":"أَكْثَرُ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":14075,"position":2,"text_uthmani":"فِيهَا","transliteration":"fīhā","translation_bn":"তার মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":14076,"position":3,"text_uthmani":"ٱلْفَسَادَ","transliteration":"l-fasāda","translation_bn":"বিপর্যয়/ অশান্তি","root":"فسد","lemma":"فَسَاد","grammar_bn":"শব্দ"},{"id":14077,"position":4,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'fa-aktharū fīhā l-fasāda', 'আর সেখানে বহু বিপর্যয় সৃষ্টি করেছিল।', 'And increased therein the corruption.', 'আর সেখানে বহু বিপর্যয় সৃষ্টি করেছিল।', 'And increased therein the corruption.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089012.mp3', now()),
  (89, 13, '', '[{"id":15087,"position":1,"text_uthmani":"فَصَبَّ","transliteration":"faṣabba","translation_bn":"তারপর আঘাত করলেন","root":"صبب","lemma":"صَبَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15088,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15089,"position":3,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15090,"position":4,"text_uthmani":"سَوْطَ","transliteration":"sawṭa","translation_bn":"চাবুকের","root":"سوط","lemma":"سَوْط","grammar_bn":"বিশেষ্য (Noun)"},{"id":15091,"position":5,"text_uthmani":"عَذَابٍ","transliteration":"ʿadhābin","translation_bn":"শাস্তির","root":"عذب","lemma":"عَذَاب","grammar_bn":"বিশেষ্য (Noun)"},{"id":15092,"position":6,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'faṣabba ʿalayhim rabbuka sawṭa ʿadhābin', 'অতঃপর তোমার প্রতিপালক তাদের উপর শাস্তির চাবুক হানলেন', 'So your Lord poured upon them a scourge of punishment.', 'অতঃপর তোমার প্রতিপালক তাদের উপর শাস্তির চাবুক হানলেন', 'So your Lord poured upon them a scourge of punishment.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089013.mp3', now()),
  (89, 14, '', '[{"id":16267,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":16268,"position":2,"text_uthmani":"رَبَّكَ","transliteration":"rabbaka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":16269,"position":3,"text_uthmani":"لَبِٱلْمِرْصَادِ","transliteration":"labil-mir''ṣādi","translation_bn":"অবশ্যই (ধরবেন) ঘাঁটিতে","root":"رصد","lemma":"مِرْصَاد","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":16270,"position":4,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna rabbaka labil-mir''ṣādi', 'তোমার প্রতিপালক অবশ্যই সতর্ক দৃষ্টি রাখছেন (যেমন ঘাঁটিতে শত্রুর প্রতি দৃষ্টি রাখা হয়)।', 'Indeed, your Lord is in observation.', 'তোমার প্রতিপালক অবশ্যই সতর্ক দৃষ্টি রাখছেন (যেমন ঘাঁটিতে শত্রুর প্রতি দৃষ্টি রাখা হয়)।', 'Indeed, your Lord is in observation.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089014.mp3', now()),
  (89, 15, '', '[{"id":17445,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"অতঃপর ব্যাপার হলো","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":17446,"position":2,"text_uthmani":"ٱلْإِنسَـٰنُ","transliteration":"l-insānu","translation_bn":"মানুষের","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":17447,"position":3,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":17448,"position":4,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"তাকে","root":"—","lemma":"مَا\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":17449,"position":5,"text_uthmani":"ٱبْتَلَىٰهُ","transliteration":"ib''talāhu","translation_bn":"পরীক্ষা করেন","root":"بلو","lemma":"ٱبْتَلَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":17450,"position":6,"text_uthmani":"رَبُّهُۥ","transliteration":"rabbuhu","translation_bn":"তার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17451,"position":7,"text_uthmani":"فَأَكْرَمَهُۥ","transliteration":"fa-akramahu","translation_bn":"তাকে সম্মান দেন","root":"كرم","lemma":"أَكْرَمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17452,"position":8,"text_uthmani":"وَنَعَّمَهُۥ","transliteration":"wanaʿʿamahu","translation_bn":"ও তাকে অনুগ্রহ করেন","root":"نعم","lemma":"نَعَّمَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":17453,"position":9,"text_uthmani":"فَيَقُولُ","transliteration":"fayaqūlu","translation_bn":"তখন সে বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":17454,"position":10,"text_uthmani":"رَبِّىٓ","transliteration":"rabbī","translation_bn":"\"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":17455,"position":11,"text_uthmani":"أَكْرَمَنِ","transliteration":"akramani","translation_bn":"আমাকে সম্মানিত করেছেন\"","root":"كرم","lemma":"أَكْرَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":17456,"position":12,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā l-insānu idhā mā ib''talāhu rabbuhu fa-akramahu wanaʿʿamahu fayaqūlu rabbī akramani', 'মানুষ এমন যে, তার প্রতিপালক যখন তাকে পরীক্ষা করেন সম্মান ও অনুগ্রহ দান ক’রে, তখন সে বলে, ‘আমার রব আমাকে সম্মানিত করেছেন।’', 'And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, "My Lord has honored me."', 'মানুষ এমন যে, তার প্রতিপালক যখন তাকে পরীক্ষা করেন সম্মান ও অনুগ্রহ দান ক’রে, তখন সে বলে, ‘আমার রব আমাকে সম্মানিত করেছেন।’', 'And as for man, when his Lord tries him and [thus] is generous to him and favors him, he says, "My Lord has honored me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089015.mp3', now()),
  (89, 16, '', '[{"id":18516,"position":1,"text_uthmani":"وَأَمَّآ","transliteration":"wa-ammā","translation_bn":"আর","root":"—","lemma":"أَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18517,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":18518,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"তাকে","root":"—","lemma":"مَا\r","grammar_bn":"সম্পূরক পদ (Supplemental)"},{"id":18519,"position":4,"text_uthmani":"ٱبْتَلَىٰهُ","transliteration":"ib''talāhu","translation_bn":"পরীক্ষা করেন","root":"بلو","lemma":"ٱبْتَلَىٰ^","grammar_bn":"ক্রিয়া (Verb)"},{"id":18520,"position":5,"text_uthmani":"فَقَدَرَ","transliteration":"faqadara","translation_bn":"সংকীর্ণ করেন","root":"قدر","lemma":"قَدَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":18521,"position":6,"text_uthmani":"عَلَيْهِ","transliteration":"ʿalayhi","translation_bn":"তার  উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":18522,"position":7,"text_uthmani":"رِزْقَهُۥ","transliteration":"riz''qahu","translation_bn":"তার রিযক","root":"رزق","lemma":"رِزْق","grammar_bn":"বিশেষ্য (Noun)"},{"id":18523,"position":8,"text_uthmani":"فَيَقُولُ","transliteration":"fayaqūlu","translation_bn":"তখন সে বলে","root":"قول","lemma":"قَالَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":18524,"position":9,"text_uthmani":"رَبِّىٓ","transliteration":"rabbī","translation_bn":"\"আমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":18525,"position":10,"text_uthmani":"أَهَـٰنَنِ","transliteration":"ahānani","translation_bn":"আমাকে হেয় করেছেন\"","root":"هون","lemma":"أَهَٰنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":18526,"position":11,"text_uthmani":"١٦","transliteration":"","translation_bn":"(১৬)","root":"—","lemma":"١٦","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ammā idhā mā ib''talāhu faqadara ʿalayhi riz''qahu fayaqūlu rabbī ahānani', 'আর যখন তিনি তাকে পরীক্ষা করেন তার রিযক সঙ্কুচিত ক’রে, তখন সে বলে, ‘আমার রব আমাকে লাঞ্ছিত করেছেন।’', 'But when He tries him and restricts his provision, he says, "My Lord has humiliated me."', 'আর যখন তিনি তাকে পরীক্ষা করেন তার রিযক সঙ্কুচিত ক’রে, তখন সে বলে, ‘আমার রব আমাকে লাঞ্ছিত করেছেন।’', 'But when He tries him and restricts his provision, he says, "My Lord has humiliated me."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089016.mp3', now()),
  (89, 17, '', '[{"id":19504,"position":1,"text_uthmani":"كَلَّا ۖ","transliteration":"kallā","translation_bn":"কখনও না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":19506,"position":2,"text_uthmani":"بَل","transliteration":"bal","translation_bn":"বরং","root":"—","lemma":"بَل\r","grammar_bn":"প্রত্যাহার পদ (Retraction)"},{"id":19507,"position":3,"text_uthmani":"لَّا","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":19508,"position":4,"text_uthmani":"تُكْرِمُونَ","transliteration":"tuk''rimūna","translation_bn":"তোমরা সম্মান করো","root":"كرم","lemma":"أَكْرَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19509,"position":5,"text_uthmani":"ٱلْيَتِيمَ","transliteration":"l-yatīma","translation_bn":"ইয়াতীমের","root":"يتم","lemma":"يَتِيم","grammar_bn":"শব্দ"},{"id":19510,"position":6,"text_uthmani":"١٧","transliteration":"","translation_bn":"(১৭)","root":"—","lemma":"١٧","grammar_bn":"মার্কার"}]'::jsonb, 'kallā bal lā tuk''rimūna l-yatīma', 'না (রিযক) কক্ষনো (মান-সম্মানের মানদন্ড) নয়, বরং তোমরা ইয়াতীমের প্রতি সম্মানজনক আচরণ কর না,', 'No! But you do not honor the orphan', 'না (রিযক) কক্ষনো (মান-সম্মানের মানদন্ড) নয়, বরং তোমরা ইয়াতীমের প্রতি সম্মানজনক আচরণ কর না,', 'No! But you do not honor the orphan', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/089017.mp3', now()),
