  (90, 1, '', '[{"id":731,"position":1,"text_uthmani":"لَآ","transliteration":"lā","translation_bn":"না","root":"—","lemma":"لَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":732,"position":2,"text_uthmani":"أُقْسِمُ","transliteration":"uq''simu","translation_bn":"আমি শপথ করছি","root":"قسم","lemma":"أَقْسَمُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":733,"position":3,"text_uthmani":"بِهَـٰذَا","transliteration":"bihādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"অব্যয় (Preposition)"},{"id":734,"position":4,"text_uthmani":"ٱلْبَلَدِ","transliteration":"l-baladi","translation_bn":"নগরের (অর্থাৎ মক্কার)","root":"بلد","lemma":"بَلَد","grammar_bn":"শব্দ"},{"id":735,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'lā uq''simu bihādhā l-baladi', '(কাফিররা বলছে দুনিয়ার জীবনই সবকিছু) না, আমি এই (মক্কা) নগরের শপথ করছি (যে নগরে সকলেই নিরাপদ),', 'I swear by this city, Makkah -', '(কাফিররা বলছে দুনিয়ার জীবনই সবকিছু) না, আমি এই (মক্কা) নগরের শপথ করছি (যে নগরে সকলেই নিরাপদ),', 'I swear by this city, Makkah -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/090001.mp3', now()),
  (90, 2, '', '[{"id":1741,"position":1,"text_uthmani":"وَأَنتَ","transliteration":"wa-anta","translation_bn":"আর তুমি","root":"—","lemma":"وَأَنتَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1742,"position":2,"text_uthmani":"حِلٌّۢ","transliteration":"ḥillun","translation_bn":"হালাল/অধিবাসী (হয়েছে)","root":"حلل","lemma":"حِلّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":1743,"position":3,"text_uthmani":"بِهَـٰذَا","transliteration":"bihādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"অব্যয় (Preposition)"},{"id":1744,"position":4,"text_uthmani":"ٱلْبَلَدِ","transliteration":"l-baladi","translation_bn":"নগরের","root":"بلد","lemma":"بَلَد","grammar_bn":"শব্দ"},{"id":1745,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wa-anta ḥillun bihādhā l-baladi', 'আর তুমি এই নগরের হালালকারী।', 'And you, [O Muhammad], are free of restriction in this city -', 'আর তুমি এই নগরের হালালকারী।', 'And you, [O Muhammad], are free of restriction in this city -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/090002.mp3', now()),
