  (91, 11, '', '[{"id":13328,"position":1,"text_uthmani":"كَذَّبَتْ","transliteration":"kadhabat","translation_bn":"মিথ্যারোপ করেছিল","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":13329,"position":2,"text_uthmani":"ثَمُودُ","transliteration":"thamūdu","translation_bn":"সামূদ জাতি","root":"—","lemma":"ثَمُود","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":13330,"position":3,"text_uthmani":"بِطَغْوَىٰهَآ","transliteration":"biṭaghwāhā","translation_bn":"তার অবাধ্যতাবশতঃ","root":"طغي","lemma":"طَغْوَىٰ","grammar_bn":"অব্যয় (Preposition)"},{"id":13331,"position":4,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'kadhabat thamūdu biṭaghwāhā', 'সামূদ জাতি সীমালঙ্ঘন ক’রে (তাদের নবীকে মেনে নিতে) অস্বীকার করেছিল।', 'Thamud denied [their prophet] by reason of their transgression,', 'সামূদ জাতি সীমালঙ্ঘন ক’রে (তাদের নবীকে মেনে নিতে) অস্বীকার করেছিল।', 'Thamud denied [their prophet] by reason of their transgression,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/091011.mp3', now()),
  (91, 12, '', '[{"id":14556,"position":1,"text_uthmani":"إِذِ","transliteration":"idhi","translation_bn":"যখন","root":"—","lemma":"إِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":14557,"position":2,"text_uthmani":"ٱنۢبَعَثَ","transliteration":"inbaʿatha","translation_bn":"(তৎপর হয়ে)উঠলো","root":"بعث","lemma":"ٱن[بَعَثَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":14558,"position":3,"text_uthmani":"أَشْقَىٰهَا","transliteration":"ashqāhā","translation_bn":"তার সবচেয়ে হতভাগা ব্যক্তি","root":"شقو","lemma":"أَشْقَى","grammar_bn":"বিশেষ্য (Noun)"},{"id":14559,"position":4,"text_uthmani":"١٢","transliteration":"","translation_bn":"(১২)","root":"—","lemma":"١٢","grammar_bn":"মার্কার"}]'::jsonb, 'idhi inbaʿatha ashqāhā', 'যখন তাদের সবচেয়ে হতভাগা লোকটি মাথা চাড়া দিয়ে উঠল।', 'When the most wretched of them was sent forth.', 'যখন তাদের সবচেয়ে হতভাগা লোকটি মাথা চাড়া দিয়ে উঠল।', 'When the most wretched of them was sent forth.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/091012.mp3', now()),
  (91, 13, '', '[{"id":15451,"position":1,"text_uthmani":"فَقَالَ","transliteration":"faqāla","translation_bn":"অতঃপর বললো","root":"قول","lemma":"قَالَ","grammar_bn":"শব্দ"},{"id":15452,"position":2,"text_uthmani":"لَهُمْ","transliteration":"lahum","translation_bn":"তাদেরকে","root":"—","lemma":"لَهُمْ","grammar_bn":"অব্যয় (Preposition)"},{"id":15453,"position":3,"text_uthmani":"رَسُولُ","transliteration":"rasūlu","translation_bn":"রাসূল","root":"رسل","lemma":"رَسُول","grammar_bn":"বিশেষ্য (Noun)"},{"id":15454,"position":4,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15455,"position":5,"text_uthmani":"نَاقَةَ","transliteration":"nāqata","translation_bn":"\"(সাবধান)উষ্ট্রীকে","root":"نوق","lemma":"نَاقَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":15456,"position":6,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর (স্পর্শ করো না)","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":15457,"position":7,"text_uthmani":"وَسُقْيَـٰهَا","transliteration":"wasuq''yāhā","translation_bn":"ও তার পানি পান করায় (বাধা দিও না)\"","root":"سقي","lemma":"سُقْيَٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15458,"position":8,"text_uthmani":"١٣","transliteration":"","translation_bn":"(১৩)","root":"—","lemma":"١٣","grammar_bn":"মার্কার"}]'::jsonb, 'faqāla lahum rasūlu l-lahi nāqata l-lahi wasuq''yāhā', 'তখন আল্লাহর রাসূল (সালিহ) তাদেরকে বলল, ‘এটা আল্লাহর উটনি, একে পানি পান করতে বাধা দিও না।', 'And the messenger of Allah [Salih] said to them, "[Do not harm] the she-camel of Allah or [prevent her from] her drink."', 'তখন আল্লাহর রাসূল (সালিহ) তাদেরকে বলল, ‘এটা আল্লাহর উটনি, একে পানি পান করতে বাধা দিও না।', 'And the messenger of Allah [Salih] said to them, "[Do not harm] the she-camel of Allah or [prevent her from] her drink."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/091013.mp3', now()),
  (91, 14, '', '[{"id":15841,"position":1,"text_uthmani":"فَكَذَّبُوهُ","transliteration":"fakadhabūhu","translation_bn":"কিন্তু তারা তাকে  মিথ্যা ভাবলো","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"শব্দ"},{"id":15842,"position":2,"text_uthmani":"فَعَقَرُوهَا","transliteration":"faʿaqarūhā","translation_bn":"অতঃপর তারা তাকে  হত্যা করলো","root":"عقر","lemma":"عَقَرَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15843,"position":3,"text_uthmani":"فَدَمْدَمَ","transliteration":"fadamdama","translation_bn":"ফলে ধ্বংস করে দিলেন","root":"دمدم","lemma":"دَمْدَمَ","grammar_bn":"কারণবাচক (Cause)"},{"id":15844,"position":4,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদেরকে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":15845,"position":5,"text_uthmani":"رَبُّهُم","transliteration":"rabbuhum","translation_bn":"তাদের রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":15846,"position":6,"text_uthmani":"بِذَنۢبِهِمْ","transliteration":"bidhanbihim","translation_bn":"তাদের পাপের জন্য","root":"ذنب","lemma":"ذَنب","grammar_bn":"অব্যয় (Preposition)"},{"id":15847,"position":7,"text_uthmani":"فَسَوَّىٰهَا","transliteration":"fasawwāhā","translation_bn":"অতঃপর তাদেরকে (মাটি) সমান করে দিলেন","root":"سوي","lemma":"سَوَّىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":15848,"position":8,"text_uthmani":"١٤","transliteration":"","translation_bn":"(১৪)","root":"—","lemma":"١٤","grammar_bn":"মার্কার"}]'::jsonb, 'fakadhabūhu faʿaqarūhā fadamdama ʿalayhim rabbuhum bidhanbihim fasawwāhā', 'কিন্তু তারা রসূলের কথা অগ্রাহ্য করল এবং উটনির পায়ের রগ কেটে দিল। শেষ পর্যন্ত তাদের পাপের কারণে তাদের প্রতিপালক তাদেরকে ধ্বংস করে মাটিতে মিশিয়ে দিলেন।', 'But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].', 'কিন্তু তারা রসূলের কথা অগ্রাহ্য করল এবং উটনির পায়ের রগ কেটে দিল। শেষ পর্যন্ত তাদের পাপের কারণে তাদের প্রতিপালক তাদেরকে ধ্বংস করে মাটিতে মিশিয়ে দিলেন।', 'But they denied him and hamstrung her. So their Lord brought down upon them destruction for their sin and made it equal [upon all of them].', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/091014.mp3', now()),
  (91, 15, '', '[{"id":16868,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":16869,"position":2,"text_uthmani":"يَخَافُ","transliteration":"yakhāfu","translation_bn":"ভয় করেন তিনি","root":"خوف","lemma":"خَافَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":16870,"position":3,"text_uthmani":"عُقْبَـٰهَا","transliteration":"ʿuq''bāhā","translation_bn":"তাঁর (কাজের) পরিণতির","root":"عقب","lemma":"عُقْبَى","grammar_bn":"বিশেষ্য (Noun)"},{"id":16871,"position":4,"text_uthmani":"١٥","transliteration":"","translation_bn":"(১৫)","root":"—","lemma":"١٥","grammar_bn":"মার্কার"}]'::jsonb, 'walā yakhāfu ʿuq''bāhā', 'আর তিনি (তাঁর এ কাজের) কোন খারাপ পরিণতির ভয় মোটেই পোষণ করেন না।', 'And He does not fear the consequence thereof.', 'আর তিনি (তাঁর এ কাজের) কোন খারাপ পরিণতির ভয় মোটেই পোষণ করেন না।', 'And He does not fear the consequence thereof.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/091015.mp3', now())
