  (92, 1, '', '[{"id":222,"position":1,"text_uthmani":"وَٱلَّيْلِ","transliteration":"wa-al-layli","translation_bn":"শপথ রাতের","root":"ليل","lemma":"لَيْل","grammar_bn":"অব্যয় (Preposition)"},{"id":223,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":224,"position":3,"text_uthmani":"يَغْشَىٰ","transliteration":"yaghshā","translation_bn":"আচ্ছন্ন করে","root":"غشو","lemma":"غَشِيَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":225,"position":4,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wa-al-layli idhā yaghshā', 'শপথ রাতের যখন তা (আলোকে) ঢেকে দেয়,', 'By the night when it covers', 'শপথ রাতের যখন তা (আলোকে) ঢেকে দেয়,', 'By the night when it covers', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/092001.mp3', now()),
  (92, 2, '', '[{"id":1785,"position":1,"text_uthmani":"وَٱلنَّهَارِ","transliteration":"wal-nahāri","translation_bn":"শপথ দিনের","root":"نهر","lemma":"نَهَار","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1786,"position":2,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":1787,"position":3,"text_uthmani":"تَجَلَّىٰ","transliteration":"tajallā","translation_bn":"আলোকিত হয়","root":"جلو","lemma":"تَجَلَّىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1788,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'wal-nahāri idhā tajallā', 'শপথ দিনের যখন তা উদ্ভাসিত হয়ে উঠে।', 'And [by] the day when it appears', 'শপথ দিনের যখন তা উদ্ভাসিত হয়ে উঠে।', 'And [by] the day when it appears', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/092002.mp3', now()),
  (92, 3, '', '[{"id":2121,"position":1,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"শপথ তাঁর (যিনি)","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2122,"position":2,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2123,"position":3,"text_uthmani":"ٱلذَّكَرَ","transliteration":"l-dhakara","translation_bn":"পুরুষ","root":"ذكر","lemma":"ذَكَر","grammar_bn":"শব্দ"},{"id":2124,"position":4,"text_uthmani":"وَٱلْأُنثَىٰٓ","transliteration":"wal-unthā","translation_bn":"ও নারী","root":"انث","lemma":"أُنثَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2125,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamā khalaqa l-dhakara wal-unthā', 'আর শপথ তাঁর যিনি সৃষ্টি করেছেন পুরুষ ও নারী,', 'And [by] He who created the male and female,', 'আর শপথ তাঁর যিনি সৃষ্টি করেছেন পুরুষ ও নারী,', 'And [by] He who created the male and female,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/092003.mp3', now()),
  (92, 4, '', '[{"id":3404,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":3405,"position":2,"text_uthmani":"سَعْيَكُمْ","transliteration":"saʿyakum","translation_bn":"তোমাদের কর্মপ্রচেষ্টা","root":"سعي","lemma":"سَعْي","grammar_bn":"বিশেষ্য (Noun)"},{"id":3406,"position":3,"text_uthmani":"لَشَتَّىٰ","transliteration":"lashattā","translation_bn":"অবশ্যই বিভিন্ন প্রকৃতির","root":"شتت","lemma":"شَتَّىٰ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":3407,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'inna saʿyakum lashattā', 'তোমাদের চেষ্টা সাধনা অবশ্যই বিভিন্নমুখী।', 'Indeed, your efforts are diverse.', 'তোমাদের চেষ্টা সাধনা অবশ্যই বিভিন্নমুখী।', 'Indeed, your efforts are diverse.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/092004.mp3', now()),
  (92, 5, '', '[{"id":4746,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"অতঃপর (তার) ক্ষেত্রে","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":4747,"position":2,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যে","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":4748,"position":3,"text_uthmani":"أَعْطَىٰ","transliteration":"aʿṭā","translation_bn":"দান করলো","root":"عطو","lemma":"أَعْطَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4749,"position":4,"text_uthmani":"وَٱتَّقَىٰ","transliteration":"wa-ittaqā","translation_bn":"ও খোদাভীরু হলো","root":"وقي","lemma":"ٱتَّقَىٰ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4750,"position":5,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā man aʿṭā wa-ittaqā', 'অতএব যে ব্যক্তি (আল্লাহর সন্তুষ্টির জন্য) দান করে ও (আল্লাহকে) ভয় করে,', 'As for he who gives and fears Allah', 'অতএব যে ব্যক্তি (আল্লাহর সন্তুষ্টির জন্য) দান করে ও (আল্লাহকে) ভয় করে,', 'As for he who gives and fears Allah', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/092005.mp3', now()),
  (92, 6, '', '[{"id":5977,"position":1,"text_uthmani":"وَصَدَّقَ","transliteration":"waṣaddaqa","translation_bn":"এবং সত্য মানলো","root":"صدق","lemma":"صَدَّقَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5978,"position":2,"text_uthmani":"بِٱلْحُسْنَىٰ","transliteration":"bil-ḥus''nā","translation_bn":"উত্তমকে (ইসলামকে)","root":"حسن","lemma":"حُسْنَىٰ","grammar_bn":"অব্যয় (Preposition)"},{"id":5979,"position":3,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'waṣaddaqa bil-ḥus''nā', 'এবং উত্তম বিষয়কে সত্য মনে করে,', 'And believes in the best [reward],', 'এবং উত্তম বিষয়কে সত্য মনে করে,', 'And believes in the best [reward],', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/092006.mp3', now()),
