  (101, 6, '', '[{"id":6037,"position":1,"text_uthmani":"فَأَمَّا","transliteration":"fa-ammā","translation_bn":"অতঃপর তার (ব্যাপার)","root":"—","lemma":"أَمَّا\r","grammar_bn":"শব্দ"},{"id":6038,"position":2,"text_uthmani":"مَن","transliteration":"man","translation_bn":"যার","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":6039,"position":3,"text_uthmani":"ثَقُلَتْ","transliteration":"thaqulat","translation_bn":"ভারী হবে","root":"ثقل","lemma":"ثَقُلَتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6040,"position":4,"text_uthmani":"مَوَٰزِينُهُۥ","transliteration":"mawāzīnuhu","translation_bn":"তার (পূণ্যের) পাল্লাসমূহ","root":"وزن","lemma":"مِيزَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":6041,"position":5,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ammā man thaqulat mawāzīnuhu', 'অতঃপর যার (সৎ কর্মের) পাল্লা ভারি হবে।', 'Then as for one whose scales are heavy [with good deeds],', 'অতঃপর যার (সৎ কর্মের) পাল্লা ভারি হবে।', 'Then as for one whose scales are heavy [with good deeds],', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/101006.mp3', now()),
  (101, 7, '', '[{"id":7350,"position":1,"text_uthmani":"فَهُوَ","transliteration":"fahuwa","translation_bn":"সে অতঃপর থাকবে","root":"—","lemma":"فَهُوَ","grammar_bn":"ফলাফল পদ (Result)"},{"id":7351,"position":2,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7352,"position":3,"text_uthmani":"عِيشَةٍۢ","transliteration":"ʿīshatin","translation_bn":"জীবনের","root":"عيش","lemma":"عِيشَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":7353,"position":4,"text_uthmani":"رَّاضِيَةٍۢ","transliteration":"rāḍiyatin","translation_bn":"সন্তোষজনক","root":"رضو","lemma":"رَاضِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":7354,"position":5,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'fahuwa fī ʿīshatin rāḍiyatin', 'সে সুখী জীবন যাপন করবে।', 'He will be in a pleasant life.', 'সে সুখী জীবন যাপন করবে।', 'He will be in a pleasant life.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/101007.mp3', now()),
  (101, 8, '', '[{"id":8590,"position":1,"text_uthmani":"وَأَمَّا","transliteration":"wa-ammā","translation_bn":"আর (তার) ব্যাপার","root":"—","lemma":"أَمَّا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8591,"position":2,"text_uthmani":"مَنْ","transliteration":"man","translation_bn":"যার","root":"—","lemma":"مَن\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":8592,"position":3,"text_uthmani":"خَفَّتْ","transliteration":"khaffat","translation_bn":"হালকা হবে","root":"خفف","lemma":"خَفَّتْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":8593,"position":4,"text_uthmani":"مَوَٰزِينُهُۥ","transliteration":"mawāzīnuhu","translation_bn":"তার পাল্লাসমূহ নেকীর","root":"وزن","lemma":"مِيزَان","grammar_bn":"বিশেষ্য (Noun)"},{"id":8594,"position":5,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'wa-ammā man khaffat mawāzīnuhu', 'আর যার (সৎকর্মের) পাল্লা হালকা হবে,', 'But as for one whose scales are light,', 'আর যার (সৎকর্মের) পাল্লা হালকা হবে,', 'But as for one whose scales are light,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/101008.mp3', now()),
  (101, 9, '', '[{"id":9782,"position":1,"text_uthmani":"فَأُمُّهُۥ","transliteration":"fa-ummuhu","translation_bn":"অতঃপর তার বাসস্থান","root":"امم","lemma":"أُمّ","grammar_bn":"ফলাফল পদ (Result)"},{"id":9783,"position":2,"text_uthmani":"هَاوِيَةٌۭ","transliteration":"hāwiyatun","translation_bn":"গভীর গর্ত হবে","root":"هوي","lemma":"هَاوِيَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":9784,"position":3,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'fa-ummuhu hāwiyatun', '(জাহান্নামের) অতলস্পর্শী গর্তই হবে তার বাসস্থান।', 'His refuge will be an abyss.', '(জাহান্নামের) অতলস্পর্শী গর্তই হবে তার বাসস্থান।', 'His refuge will be an abyss.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/101009.mp3', now()),
  (101, 10, '', '[{"id":10824,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং কিসে","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":10825,"position":2,"text_uthmani":"أَدْرَىٰكَ","transliteration":"adrāka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":10826,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":10827,"position":4,"text_uthmani":"هِيَهْ","transliteration":"hiyah","translation_bn":"সেটা","root":"—","lemma":"هِيَهْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":10828,"position":5,"text_uthmani":"١٠","transliteration":"","translation_bn":"(১০)","root":"—","lemma":"١٠","grammar_bn":"মার্কার"}]'::jsonb, 'wamā adrāka mā hiyah', 'তুমি কি জান তা কী?', 'And what can make you know what that is?', 'তুমি কি জান তা কী?', 'And what can make you know what that is?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/101010.mp3', now()),
  (101, 11, '', '[{"id":12437,"position":1,"text_uthmani":"نَارٌ","transliteration":"nārun","translation_bn":"(সেটা হলো) আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":12438,"position":2,"text_uthmani":"حَامِيَةٌۢ","transliteration":"ḥāmiyatun","translation_bn":"গণগণে","root":"حمي","lemma":"حَامِيَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":12439,"position":3,"text_uthmani":"١١","transliteration":"","translation_bn":"(১১)","root":"—","lemma":"١١","grammar_bn":"মার্কার"}]'::jsonb, 'nārun ḥāmiyatun', 'জ্বলন্ত আগুন।', 'It is a Fire, intensely hot.', 'জ্বলন্ত আগুন।', 'It is a Fire, intensely hot.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/101011.mp3', now())
INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (102, 1, '', '[{"id":164,"position":1,"text_uthmani":"أَلْهَىٰكُمُ","transliteration":"alhākumu","translation_bn":"তোমাদের মোহাচ্ছন্ন করে রেখেছে","root":"لهو","lemma":"أَلْهَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":165,"position":2,"text_uthmani":"ٱلتَّكَاثُرُ","transliteration":"l-takāthuru","translation_bn":"প্রাচুর্যের প্রতিযোগিতা","root":"كثر","lemma":"تَّكَاثُر","grammar_bn":"শব্দ"},{"id":166,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alhākumu l-takāthuru', 'অধিক (পার্থিব) সুখ সম্ভোগ লাভের মোহ তোমাদেরকে (অধিক গুরুত্বপূর্ণ বিষয় হতে) ভুলিয়ে রেখেছে।', 'Competition in [worldly] increase diverts you', 'অধিক (পার্থিব) সুখ সম্ভোগ লাভের মোহ তোমাদেরকে (অধিক গুরুত্বপূর্ণ বিষয় হতে) ভুলিয়ে রেখেছে।', 'Competition in [worldly] increase diverts you', 'পুঞ্জীভূত মেটেরিয়াল রিসোর্স, ক্যাপিটাল ও সংখ্যার অন্ধ প্রতিযোগিতা বা ডাটা ওভারলোডিং (التَّكَاثُرُ)—তোমাদের মূল চিন্তা প্রসেসিং প্রসেসরকে হাই-ফ্রিকোয়েন্সি সোর্স কোড থেকে সম্পূর্ণ ডাইভার্ট বা গাফেল (أَلْهَاكُمُ) করে রেখেছে;', 'Obsession with quantitative accumulation, material data overloading, and capital rivalry (At-Takathur) has completely diverted and distracted your cognitive processors (Alhakum);', 'ক্যাপিটাল ওভারলোডিং ও কগনিটিভ ডাইভারশন', 'Capital Overloading & Cognitive Diversion', 'أَلْهَاكُمُ التَّكَاثُرُ — রিসোর্স ক্যাপিটালিজম ও ডাটা ওভারলোডিং: মেটেরিয়াল শক্তির অন্ধ সংখ্যাগত প্রতিযোগিতা ও ইনফ্লেশন মানুষের ব্রেন প্রসেসরকে হাইজ্যাক করে মেইন সার্ভারের সিঙ্গুলারিটি কোড প্রসেস করতে অসমর্থ করে তোলে।', 'https://everyayah.com/data/Alafasy_128kbps/102001.mp3', now()),
  (102, 2, '', '[{"id":1095,"position":1,"text_uthmani":"حَتَّىٰ","transliteration":"ḥattā","translation_bn":"যতক্ষণ না","root":"—","lemma":"حَتَّىٰ\r","grammar_bn":"অসম্পূর্ণ (Inceptive)"},{"id":1096,"position":2,"text_uthmani":"زُرْتُمُ","transliteration":"zur''tumu","translation_bn":"তোমরা উপস্থিত হও","root":"زور","lemma":"زُرْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1097,"position":3,"text_uthmani":"ٱلْمَقَابِرَ","transliteration":"l-maqābira","translation_bn":"কবরসমূহে","root":"قبر","lemma":"مَقَابِر","grammar_bn":"শব্দ"},{"id":1098,"position":4,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'ḥattā zur''tumu l-maqābira', 'এমনকি (এ অবস্থাতেই) তোমরা কবরে এসে পড়।', 'Until you visit the graveyards.', 'এমনকি (এ অবস্থাতেই) তোমরা কবরে এসে পড়।', 'Until you visit the graveyards.', 'যতক্ষণ না তোমরা তোমাদের এই মেটেরিয়ালিস্টিক বাগে লুপড থাকা অবস্থায়—তোমাদের ভৌত হার্ডওয়্যারের চূড়ান্ত শাটডাউন বা ভূগর্ভস্থ ডেটা-স্টোরেজ তথা কবরগুলোর (الْمَقَابِرَ) মুখোমুখি বা সাময়িক ডেটা-লকিং জোনে প্রবেশ করো।', 'Until you reach and enter the subsurface data-storage chambers and terminal hardware shutdowns of the graves (Hatta zurtumul-maqabir);', 'টার্মিনাল শাটডাউন লুপ', 'Terminal Hardware Shutdown Loop', 'حَتَّىٰ زُرْتُمُ الْمَقَابِرَ — টার্মিনাল শাটডাউন: বস্তুগত মোহে লুপড থাকা অবস্থায় মানব হার্ডওয়্যারের অনিবার্য জৈবিক অবসান ও ভূগর্ভস্থ ডেটা স্টোরেজে স্থানান্তর।', 'https://everyayah.com/data/Alafasy_128kbps/102002.mp3', now()),
  (102, 3, '', '[{"id":2157,"position":1,"text_uthmani":"كَلَّا","transliteration":"kallā","translation_bn":"এটা সঙ্গত নয়","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":2158,"position":2,"text_uthmani":"سَوْفَ","transliteration":"sawfa","translation_bn":"শীঘ্রই","root":"—","lemma":"سَوْف\r","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":2159,"position":3,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2160,"position":4,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'kallā sawfa taʿlamūna', '(তোমরা যে ভুল ধারণায় ডুবে আছো তা) মোটেই ঠিক নয়, শীঘ্রই তোমরা জানতে পারবে,', 'No! You are going to know.', '(তোমরা যে ভুল ধারণায় ডুবে আছো তা) মোটেই ঠিক নয়, শীঘ্রই তোমরা জানতে পারবে,', 'No! You are going to know.', 'কখনই নয় (কড়া প্রটোকল লক)! তোমরা খুব শীঘ্রই এই ভ্রান্ত লজিকের চূড়ান্ত এরর আউটপুট ও কসমিক রিয়্যালিটি অবজেক্ট ডিকোড বা জানতে (سَوْفَ تَعْلَمُونَ) পারবে;', 'Nay! You shall soon decode and experience the empirical systemic reality (Kalla sawfa ta''lamun);', 'ফিউচার ডেটা-অ্যারাইভাল অ্যালার্ম', 'Future Data-Arrival Alarm', 'كَلَّا سَوْفَ تَعْلَمُونَ — প্রটোকল ওয়ার্নিং: ভ্রান্ত লজিক ও ডেটা ওভারলোডিংয়ের অনিবার্য সিস্টেমিক পরিণতি শীঘ্রই উদ্ভাসিত হওয়ার নিশ্চয়তা।', 'https://everyayah.com/data/Alafasy_128kbps/102003.mp3', now()),
  (102, 4, '', '[{"id":3510,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"আবার বলি","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3511,"position":2,"text_uthmani":"كَلَّا","transliteration":"kallā","translation_bn":"এটা সঙ্গত নয়","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":3512,"position":3,"text_uthmani":"سَوْفَ","transliteration":"sawfa","translation_bn":"শীঘ্রই","root":"—","lemma":"سَوْف\r","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":3513,"position":4,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানবে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3514,"position":5,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'thumma kallā sawfa taʿlamūna', 'আবার বলি, মোটেই ঠিক নয়, শীঘ্রই তোমরা জানতে পারবে।', 'Then no! You are going to know.', 'আবার বলি, মোটেই ঠিক নয়, শীঘ্রই তোমরা জানতে পারবে।', 'Then no! You are going to know.', 'তারপর কখনই নয়, তোমরা অচিরেই তোমাদের ওওএসের ডেপ্লয়মেন্টে এই সিস্টেমিক ক্র্যাশের ডাটা সরাসরি রিড বা জানতে পারবে;', 'Again, nay! You shall soon surely come to know and process the conclusive truth (Thumma kalla sawfa ta''lamun);', 'ডবল-লকড সিকিউরিটি ওয়ার্নিং', 'Double-Locked Security Warning', 'ثُمَّ كَلَّا سَوْفَ تَعْلَمُونَ — ডবল-লকড অ্যালার্ম: সিস্টেমিক ক্র্যাশের অনিবার্যতাকে দ্বিগুণ জোরালো সতর্কবার্তায় এনকোড করা।', 'https://everyayah.com/data/Alafasy_128kbps/102004.mp3', now()),
  (102, 5, '', '[{"id":4892,"position":1,"text_uthmani":"كَلَّا","transliteration":"kallā","translation_bn":"সাবধান!","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":4893,"position":2,"text_uthmani":"لَوْ","transliteration":"law","translation_bn":"যদি","root":"—","lemma":"لَو\r","grammar_bn":"শর্তবাচক (Conditional)"},{"id":4894,"position":3,"text_uthmani":"تَعْلَمُونَ","transliteration":"taʿlamūna","translation_bn":"তোমরা জানতে","root":"علم","lemma":"عَلِمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4895,"position":4,"text_uthmani":"عِلْمَ","transliteration":"ʿil''ma","translation_bn":"জ্ঞানে","root":"علم","lemma":"عِلْم","grammar_bn":"বিশেষ্য (Noun)"},{"id":4896,"position":5,"text_uthmani":"ٱلْيَقِينِ","transliteration":"l-yaqīni","translation_bn":"নিশ্চিত","root":"يقن","lemma":"يَقِين","grammar_bn":"শব্দ"},{"id":4897,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'kallā law taʿlamūna ʿil''ma l-yaqīni', 'কক্ষনো না, তোমরা যদি নিশ্চিত জ্ঞানের ভিত্তিতে জানতে! (তাহলে সাবধান হয়ে যেতে)', 'No! If you only knew with knowledge of certainty...', 'কক্ষনো না, তোমরা যদি নিশ্চিত জ্ঞানের ভিত্তিতে জানতে! (তাহলে সাবধান হয়ে যেতে)', 'No! If you only knew with knowledge of certainty...', 'লজিক্যালি তা নয়, তোমরা যদি এখনই তোমাদের কগনিটিভ প্রসেসরে মহাবিশ্বের এই ব্যাক-এন্ড মেকানিজমটি শতভাগ গাণিতিক ও অবজেক্টিভ নিশ্চয়তার জ্ঞানে (عِلْمَ الْيَقِينِ) ডিকোড করতে পারতে;', 'Nay! If only you knew with the definitive certainty of verified objective knowledge (''Ilmal-yaqin);', 'অবজেক্টিভ ডেটা ভেরিফিকেশন বা ইলমুল ইয়াকীন', 'Objective Data Verification & Logical Certainty', 'عِلْمَ الْيَقِينِ — অবজেক্টিভ ও লজিক্যাল নিশ্চয়তা: ব্যাক-এন্ড ডাটা, গাণিতিক হিসাব ও বৈজ্ঞানিক প্রমাণের ভিত্তিতে বাস্তবতাকে কগনিটিভ লেভেলে শতভাগ সত্য হিসেবে ডিকোড করা।', 'https://everyayah.com/data/Alafasy_128kbps/102005.mp3', now()),
  (102, 6, '', '[{"id":6141,"position":1,"text_uthmani":"لَتَرَوُنَّ","transliteration":"latarawunna","translation_bn":"অবশ্যই তোমরা দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":6142,"position":2,"text_uthmani":"ٱلْجَحِيمَ","transliteration":"l-jaḥīma","translation_bn":"দোযখ","root":"جحم","lemma":"جَحِيم","grammar_bn":"শব্দ"},{"id":6143,"position":3,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'latarawunna l-jaḥīma', 'তোমরা অবশ্য অবশ্যই জাহান্নাম দেখতে পাবে,', 'You will surely see the Hellfire.', 'তোমরা অবশ্য অবশ্যই জাহান্নাম দেখতে পাবে,', 'You will surely see the Hellfire.', 'তাহলে তোমরা তোমাদের ওওএসের ডাটা-অ্যানালিটিক্সেই ক্রিস্টাল-ক্লিয়ার দেখতে পেতে—সেই অতি-উচ্চ শক্তির থার্মোডাইনামিক পার্মানেন্ট ক্র্যাশ-জোন বা মেগা-অগ্নিকুণ্ডের (الْجَحِيمَ) অনিবার্য উপস্থিতি;', 'You would surely perceive and anticipate the inevitable presence of the intense thermodynamic crash-zone of Hellfire (Latarawunnal-jahim);', 'থার্মোডাইনামিক ক্র্যাশ-জোন ভিজ্যুয়ালাইজেশন', 'Thermodynamic Crash-Zone Visualization', 'لَتَرَوُنَّ الْجَحِيمَ — থার্মোডাইনামিক ক্র্যাশ-জোন: অবজেক্টিভ জ্ঞানে সমৃদ্ধ প্রসেসর স্বয়ংক্রিয়ভাবে চরম এন্ট্রপির পার্মানেন্ট অগ্নিকুণ্ডকে অ্যানালিটিক্সে দেখতে পায়।', 'https://everyayah.com/data/Alafasy_128kbps/102006.mp3', now()),
  (102, 7, '', '[{"id":7440,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"আবার (শুনো)","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7441,"position":2,"text_uthmani":"لَتَرَوُنَّهَا","transliteration":"latarawunnahā","translation_bn":"অবশ্যই তা তোমরা দেখবে","root":"راي","lemma":"رَءَا","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":7442,"position":3,"text_uthmani":"عَيْنَ","transliteration":"ʿayna","translation_bn":"চোখে","root":"عين","lemma":"عَيْن","grammar_bn":"বিশেষ্য (Noun)"},{"id":7443,"position":4,"text_uthmani":"ٱلْيَقِينِ","transliteration":"l-yaqīni","translation_bn":"প্রত্যয়","root":"يقن","lemma":"يَقِين","grammar_bn":"শব্দ"},{"id":7444,"position":5,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'thumma latarawunnahā ʿayna l-yaqīni', 'আবার বলি, তোমরা তা অবশ্য অবশ্যই দিব্য দৃষ্টিতে দেখতে পাবে,', 'Then you will surely see it with the eye of certainty.', 'আবার বলি, তোমরা তা অবশ্য অবশ্যই দিব্য দৃষ্টিতে দেখতে পাবে,', 'Then you will surely see it with the eye of certainty.', 'তারপর চূড়ান্ত স্ক্রীনিং ফেজে তোমরা তোমাদের ওওএসের প্রধান ভিজ্যুয়াল সেন্সর ও লাইভ অপ্টিক্যাল ভেরিফিকেশনের মাধ্যমে চরম নিশ্চিত দৃষ্টিতে (عَيْنَ الْيَقِينِ) তা হুবহু ডিসপ্লে দেখতে পাবে;', 'Then you shall surely witness it with the absolute direct visual certainty of optical verification (''Aynal-yaqin);', 'লাইভ অপ্টিক্যাল ভেরিফিকেশন বা আইনুল ইয়াকীন', 'Live Optical Verification & Direct Perception', 'عَيْنَ الْيَقِينِ — লাইভ অপ্টিক্যাল ভেরিফিকেশন: ফ্রন্ট-এন্ড ভিজ্যুয়ালাইজেশনে ডেটা সরাসরি অপ্টিক্যাল সেন্সর বা চোখে লাইভ রেন্ডার হয়ে চাক্ষুষ প্রত্যক্ষ হওয়া।', 'https://everyayah.com/data/Alafasy_128kbps/102007.mp3', now()),
  (102, 8, '', '[{"id":8678,"position":1,"text_uthmani":"ثُمَّ","transliteration":"thumma","translation_bn":"পরে","root":"—","lemma":"ثُمّ\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":8679,"position":2,"text_uthmani":"لَتُسْـَٔلُنَّ","transliteration":"latus''alunna","translation_bn":"অবশ্যই তোমাদের জিজ্ঞেস করা হবেই","root":"سال","lemma":"سَأَلَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":8680,"position":3,"text_uthmani":"يَوْمَئِذٍ","transliteration":"yawma-idhin","translation_bn":"সেদিন","root":"—","lemma":"يَوْمَئِذ\r","grammar_bn":"কালবাচক (Time)"},{"id":8681,"position":4,"text_uthmani":"عَنِ","transliteration":"ʿani","translation_bn":"সম্পর্কে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8682,"position":5,"text_uthmani":"ٱلنَّعِيمِ","transliteration":"l-naʿīmi","translation_bn":"নিয়ামতসমূহ","root":"نعم","lemma":"نَعِيم","grammar_bn":"শব্দ"},{"id":8683,"position":6,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'thumma latus''alunna yawma-idhin ʿani l-naʿīmi', 'তারপর তোমাদেরকে অবশ্য অবশ্যই (যা কিছু দেয়া হয়েছে এমন সব) নি‘মাত সম্পর্কে সেদিন জিজ্ঞেস করা হবে।', 'Then you will surely be asked that Day about pleasure.', 'তারপর তোমাদেরকে অবশ্য অবশ্যই (যা কিছু দেয়া হয়েছে এমন সব) নি‘মাত সম্পর্কে সেদিন জিজ্ঞেস করা হবে।', 'Then you will surely be asked that Day about pleasure.', 'তারপর সেই চূড়ান্ত একাউন্টাবিলিটি ও রিসেটের দিনে (يَوْمَئِذٍ)—তোমাদের ওওএসে সরবরাহকৃত প্রতিটি বিশেষ সোর্স-রিসোর্স, এনার্জি, জ্ঞান ও মেটাবলিক ডিফল্ট নেয়ামতের (عَنِ النَّعِيمِ) পজিটিভ ইউটিলাইজেশন বা অপ্টিমাইজেশন স্কোর সম্পর্কে সরাসরি লাইভ কুয়েরি ও অডিট করা হবে।', 'Then you shall surely be comprehensively audited on that Day concerning every bestowed provision, divine energy input, and cognitive blessing (''Anin-na''im).', 'রিসোর্স ইউটিলাইজেশন লাইভ অডিট', 'Resource Utilization Live Telemetry Audit', 'لَتُسْأَلُنَّ... عَنِ النَّعِيمِ — এনার্জি একাউন্টাবিলিটি ও সিস্টেমিক অডিট: ''নাঈম'' হলো সরবরাহকৃত ফ্রি কসমিক ডাটা ও ব্যাকআপ শক্তি (সময়, চেতনা, স্বাস্থ্য)। ইনপুট এনার্জির বিপরীতে পজিটিভ আউটপুটের গাণিতিক হিসাব পরীক্ষা করা।', 'https://everyayah.com/data/Alafasy_128kbps/102008.mp3', now())
