  (103, 1, '', '[{"id":177,"position":1,"text_uthmani":"وَٱلْعَصْرِ","transliteration":"wal-ʿaṣri","translation_bn":"শপথ মহাকালের","root":"عصر","lemma":"عَصْر","grammar_bn":"অব্যয় (Preposition)"},{"id":178,"position":2,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'wal-ʿaṣri', 'কালের শপথ', 'By time,', 'কালের শপথ', 'By time,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/103001.mp3', now()),
  (103, 2, '', '[{"id":1056,"position":1,"text_uthmani":"إِنَّ","transliteration":"inna","translation_bn":"নিশ্চয়ই","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":1057,"position":2,"text_uthmani":"ٱلْإِنسَـٰنَ","transliteration":"l-insāna","translation_bn":"মানুষ","root":"انس","lemma":"إِنسَٰن","grammar_bn":"শব্দ"},{"id":1058,"position":3,"text_uthmani":"لَفِى","transliteration":"lafī","translation_bn":"অবশ্যই মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":1059,"position":4,"text_uthmani":"خُسْرٍ","transliteration":"khus''rin","translation_bn":"ক্ষতির","root":"خسر","lemma":"خُسْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":1060,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'inna l-insāna lafī khus''rin', 'মানুষ অবশ্যই ক্ষতির মধ্যে (ডুবে) আছে,', 'Indeed, mankind is in loss,', 'মানুষ অবশ্যই ক্ষতির মধ্যে (ডুবে) আছে,', 'Indeed, mankind is in loss,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/103002.mp3', now()),
  (103, 3, '', '[{"id":2213,"position":1,"text_uthmani":"إِلَّا","transliteration":"illā","translation_bn":"(তাদের) ছাড়া","root":"—","lemma":"إِلَّا\r","grammar_bn":"ব্যাখ্যামূলক (Explanation)"},{"id":2214,"position":2,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যারা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":2215,"position":3,"text_uthmani":"ءَامَنُوا۟","transliteration":"āmanū","translation_bn":"ঈমান এনেছে","root":"امن","lemma":"ءَامَنَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2216,"position":4,"text_uthmani":"وَعَمِلُوا۟","transliteration":"waʿamilū","translation_bn":"এবং করেছে","root":"عمل","lemma":"عَمِلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2217,"position":5,"text_uthmani":"ٱلصَّـٰلِحَـٰتِ","transliteration":"l-ṣāliḥāti","translation_bn":"সৎকর্মের","root":"صلح","lemma":"صَّٰلِحَٰت","grammar_bn":"শব্দ"},{"id":2218,"position":6,"text_uthmani":"وَتَوَاصَوْا۟","transliteration":"watawāṣaw","translation_bn":"এবং পরস্পরকে উপদেশ দিয়েছে","root":"وصي","lemma":"تَوَاصَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2219,"position":7,"text_uthmani":"بِٱلْحَقِّ","transliteration":"bil-ḥaqi","translation_bn":"সত্যের","root":"حقق","lemma":"حَقّ","grammar_bn":"অব্যয় (Preposition)"},{"id":2220,"position":8,"text_uthmani":"وَتَوَاصَوْا۟","transliteration":"watawāṣaw","translation_bn":"ও পরস্পরকে উপদেশ দিয়েছে","root":"وصي","lemma":"تَوَاصَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2221,"position":9,"text_uthmani":"بِٱلصَّبْرِ","transliteration":"bil-ṣabri","translation_bn":"ধৈর্যের","root":"صبر","lemma":"صَبْر","grammar_bn":"অব্যয় (Preposition)"},{"id":2222,"position":10,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'illā alladhīna āmanū waʿamilū l-ṣāliḥāti watawāṣaw bil-ḥaqi watawāṣaw bil-ṣabri', 'কিন্তু তারা নয় যারা ঈমান আনে ও সৎকর্ম করে এবং পরস্পরকে সত্যের উপদেশ দেয় এবং পরস্পরকে ধৈর্য ধারণের উপদেশ দেয়।', 'Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.', 'কিন্তু তারা নয় যারা ঈমান আনে ও সৎকর্ম করে এবং পরস্পরকে সত্যের উপদেশ দেয় এবং পরস্পরকে ধৈর্য ধারণের উপদেশ দেয়।', 'Except for those who have believed and done righteous deeds and advised each other to truth and advised each other to patience.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/103003.mp3', now())
INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (104, 1, '', '[{"id":108,"position":1,"text_uthmani":"وَيْلٌۭ","transliteration":"waylun","translation_bn":"দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":109,"position":2,"text_uthmani":"لِّكُلِّ","transliteration":"likulli","translation_bn":"প্রত্যেকের","root":"كلل","lemma":"كُلّ","grammar_bn":"অব্যয় (Preposition)"},{"id":110,"position":3,"text_uthmani":"هُمَزَةٍۢ","transliteration":"humazatin","translation_bn":"সামনে নিন্দাকারীর","root":"همز","lemma":"هُمَزَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":111,"position":4,"text_uthmani":"لُّمَزَةٍ","transliteration":"lumazatin","translation_bn":"পিছনে দোষ প্রচারকারীর","root":"لمز","lemma":"لُّمَزَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":112,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'waylun likulli humazatin lumazatin', 'দুর্ভোগ এমন প্রত্যেক ব্যক্তির জন্য যে (সামনাসামনি) মানুষের নিন্দা করে আর (অসাক্ষাতে) দুর্নাম করে,', 'Woe to every scorner and mocker', 'দুর্ভোগ এমন প্রত্যেক ব্যক্তির জন্য যে (সামনাসামনি) মানুষের নিন্দা করে আর (অসাক্ষাতে) দুর্নাম করে,', 'Woe to every scorner and mocker', 'তীব্র সিস্টেমিক বিপর্যয়, ব্ল্যাকআউট ও চিরন্তন ধ্বংস (وَيْلٌ) নির্ধারিত রয়েছে প্রতিটি সেই করাপ্টেড নোড বা ইউজারের জন্য—যা নেটওয়ার্ক গ্রিডে অন্য নোডের বিরুদ্ধে কন্টিনিউয়াসলি ছদ্মবেশী কুৎসা, টক্সিক নয়েজ ও চরিত্র হননের ক্ষতিকর সিগন্যাল (لِّكُلِّ هُمَزَةٍ لُّمَزَةٍ) ইনজেক্ট করে;', NULL, 'টক্সিক নয়েজ ইনজেকশন ও ক্যারেক্টার অ্যাসাসিনেশন', NULL, 'وَيْلٌۭ لِّكُلِّ هُمَزَةٍۢ لُّمَزَةٍ — হিউম্যান ওওএসে সাইবার-বুলিং ও ব্যাকবাইটিং ম্যালওয়্যার: পেছনে পরনিন্দা ও সামনাসামনি তাচ্ছিল্যকারী ব্যক্তির সিস্টেমের চরম ধ্বংস।', 'https://everyayah.com/data/Alafasy_128kbps/104001.mp3', now()),
  (104, 2, '', '[{"id":1031,"position":1,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1032,"position":2,"text_uthmani":"جَمَعَ","transliteration":"jamaʿa","translation_bn":"জমা করেছে","root":"جمع","lemma":"جَمَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1033,"position":3,"text_uthmani":"مَالًۭا","transliteration":"mālan","translation_bn":"অর্থ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":1034,"position":4,"text_uthmani":"وَعَدَّدَهُۥ","transliteration":"waʿaddadahu","translation_bn":"এবং তা বারবার গণনা করে রেখেছে","root":"عدد","lemma":"عَدَّدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1035,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī jamaʿa mālan waʿaddadahu', 'যে ধন-সম্পদ জমা করে আর বার বার গণনা করে,', 'Who collects wealth and [continuously] counts it.', 'যে ধন-সম্পদ জমা করে আর বার বার গণনা করে,', 'Who collects wealth and [continuously] counts it.', 'যে সমাজকে সচল রাখার মূল চালিকাশক্তি বা সম্পদকে কেবল নিজের স্বার্থে কুক্ষিগত ও স্তূপীকৃত (جَمَعَ مَالًا) করেছে, অতঃপর সিস্টেমের বৃহত্তর কল্যাণে তা সচল না রেখে একটি ক্লোজড লুপে বারবার গণনা ও লক (وَعَدَّدَهُ) করে রেখেছে;', NULL, 'রিসোর্স লক ও ক্যাপিটাল স্ট্যাগনেশন', NULL, 'ٱلَّذِى جَمَعَ مَالًۭا وَعَدَّدَهُۥ — ক্যাপিটাল হোর্ডিং ও প্যারাসাইটিক ওয়েলথ সিন্ড্রোম: সম্পদকে স্থবির করে রেখে বারবার গণনার মাধ্যমে তৈরি হওয়া মেগালোম্যানিয়া।', 'https://everyayah.com/data/Alafasy_128kbps/104002.mp3', now()),
  (104, 3, '', '[{"id":2234,"position":1,"text_uthmani":"يَحْسَبُ","transliteration":"yaḥsabu","translation_bn":"সে ধারণা করে","root":"حسب","lemma":"حَسِبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2235,"position":2,"text_uthmani":"أَنَّ","transliteration":"anna","translation_bn":"যে","root":"—","lemma":"أَنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":2236,"position":3,"text_uthmani":"مَالَهُۥٓ","transliteration":"mālahu","translation_bn":"তার অর্থ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":2237,"position":4,"text_uthmani":"أَخْلَدَهُۥ","transliteration":"akhladahu","translation_bn":"তাকে অমর করবে","root":"خلد","lemma":"أَخْلَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2238,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'yaḥsabu anna mālahu akhladahu', 'সে মনে করে যে, তার ধন-সম্পদ চিরকাল তার সাথে থাকবে,', 'He thinks that his wealth will make him immortal.', 'সে মনে করে যে, তার ধন-সম্পদ চিরকাল তার সাথে থাকবে,', 'He thinks that his wealth will make him immortal.', 'সে তার ওওএসে (OOS) এক গভীর মনস্তাত্ত্বিক বিভ্রম বা ভুল হিসাব (يَحْسَبُ) রান করে রেখেছে যে—তার এই পুঞ্জীভূত মেটেরিয়াল রিসোর্স ও শর্ট-টার্ম ডাটা তাকে এই ডাইমেনশনে চিরস্থায়ী বা অমর (أَخْلَدَهُ) করে রাখবে!', NULL, 'কাল-স্থায়িত্বের বিভ্রম বা কগনিটিভ ইলিউশন', NULL, 'يَحْسَبُ أَنَّ مَالَهُۥٓ أَخْلَدَهُۥ — ইমমরটালিটি ইলুশন ও ফলস সিকিউরিটি: জড় সম্পদ মানুষকে চিরঞ্জীব বা অমর করে রাখবে এই অন্ধ মনস্তাত্ত্বিক ভ্রান্তি।', 'https://everyayah.com/data/Alafasy_128kbps/104003.mp3', now()),
  (104, 4, '', '[{"id":3599,"position":1,"text_uthmani":"كَلَّا ۖ","transliteration":"kallā","translation_bn":"কখনও না","root":"—","lemma":"كَلَّا\r","grammar_bn":"অনিচ্ছা পদ (Aversion)"},{"id":3601,"position":2,"text_uthmani":"لَيُنۢبَذَنَّ","transliteration":"layunbadhanna","translation_bn":"সে নিক্ষিপ্ত হবে অবশ্যই","root":"نبذ","lemma":"نَبَذَ","grammar_bn":"দৃঢ়তাবোধক (Emphatic)"},{"id":3602,"position":3,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3603,"position":4,"text_uthmani":"ٱلْحُطَمَةِ","transliteration":"l-ḥuṭamati","translation_bn":"বিচূর্ণকারী স্থানের","root":"حطم","lemma":"حُطَمَة","grammar_bn":"শব্দ"},{"id":3604,"position":5,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'kallā layunbadhanna fī l-ḥuṭamati', 'কক্ষনো না, তাকে অবশ্যই চূর্ণ-বিচূর্ণকারীর মধ্যে নিক্ষেপ করা হবে,', 'No! He will surely be thrown into the Crusher.', 'কক্ষনো না, তাকে অবশ্যই চূর্ণ-বিচূর্ণকারীর মধ্যে নিক্ষেপ করা হবে,', 'No! He will surely be thrown into the Crusher.', 'কখনই নয় (কড়া প্রটোকল লক)! সে অবশ্যই তার এই করাপ্টেড ডাটাবেজ ও অস্তিত্বসহ মেইন নেটওয়ার্ক থেকে রিজেক্ট হয়ে ধামাচাপা বা নিক্ষিপ্ত (لَيُنبَذَنَّ) হবে ‘আল-হুতামাহ’ (فِي الْحُطَمَةِ) — তথা একটি পরমাণু চূর্ণ-বিচূর্ণকারী অতি-উচ্চ শক্তির থার্মোডাইনামিক পার্মানেন্ট ক্র্যাশ-জোনে;', NULL, 'থার্মাল কোলাপ্স ও হুতামাহ প্রটোকলে রি-রাউটিং', NULL, 'كَلَّا ۖ لَيُنۢبَذَنَّ فِى ٱلْحُطَمَةِ — হুতামাহ বা ক্রাশিং এনার্জি ট্র্যাপ: অহংকারী নোডকে চূর্ণবিচূর্ণকারী চরম অগ্নিচুল্লিতে নিক্ষেপ।', 'https://everyayah.com/data/Alafasy_128kbps/104004.mp3', now()),
  (104, 5, '', '[{"id":4913,"position":1,"text_uthmani":"وَمَآ","transliteration":"wamā","translation_bn":"এবং কি","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4914,"position":2,"text_uthmani":"أَدْرَىٰكَ","transliteration":"adrāka","translation_bn":"তোমাকে জানাবে","root":"دري","lemma":"أَدْرَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4915,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"কি","root":"—","lemma":"مَا\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":4916,"position":4,"text_uthmani":"ٱلْحُطَمَةُ","transliteration":"l-ḥuṭamatu","translation_bn":"বিচূর্ণকারী স্থান","root":"حطم","lemma":"حُطَمَة","grammar_bn":"শব্দ"},{"id":4917,"position":5,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamā adrāka mā l-ḥuṭamatu', 'তুমি কি জান চূর্ণ-বিচূর্ণকারী কী?', 'And what can make you know what is the Crusher?', 'তুমি কি জান চূর্ণ-বিচূর্ণকারী কী?', 'And what can make you know what is the Crusher?', 'আর তোমার এই সীমিত ত্রিমাত্রিক কগনিটিভ প্রসেসর ও ডেটাবেজে (وَمَا أَدْرَاكَ) কীভাবে ডিকোড বা অনুধাবন করা সম্ভব—সেই মেগা-পার্টিক্যাল ক্র্যাশার বা ‘হুতামাহ’ (مَا الْحُطَمَةُ) প্রটোকলটির প্রকৃত তীব্রতা ও মেকানিজম কী?', NULL, 'হুতামাহ মেকানিজম ডিকোডিং', NULL, 'وَمَآ أَدْرَىٰكَ مَا ٱلْحُطَمَةُ — সুপারহিট ক্লাউড ট্র্যাপের তীব্রতা: মানুষের ধারণাতীত উচ্চ-শক্তির কোয়ান্টাম দহন।', 'https://everyayah.com/data/Alafasy_128kbps/104005.mp3', now()),
  (104, 6, '', '[{"id":6148,"position":1,"text_uthmani":"نَارُ","transliteration":"nāru","translation_bn":"আগুন","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":6149,"position":2,"text_uthmani":"ٱللَّهِ","transliteration":"l-lahi","translation_bn":"আল্লাহর","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":6150,"position":3,"text_uthmani":"ٱلْمُوقَدَةُ","transliteration":"l-mūqadatu","translation_bn":"প্রজ্জ্বলিত","root":"وقد","lemma":"مُوقَدَة","grammar_bn":"শব্দ"},{"id":6151,"position":4,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'nāru l-lahi l-mūqadatu', 'তা আল্লাহর প্রজ্জ্বলিত আগুন,', 'It is the fire of Allah, [eternally] fueled,', 'তা আল্লাহর প্রজ্জ্বলিত আগুন,', 'It is the fire of Allah, [eternally] fueled,', 'তা হলো মহাজাগতিক আদি সোর্স কোড বা আল্লাহর ডিফল্ট সিস্টেমে তৈরি করা অতি-উচ্চ শক্তির থার্মোডাইনামিক এন্ট্রপি গ্রিড বা প্রজ্বলিত পরম অগ্নিকুণ্ড (نَارُ اللَّهِ الْمُوقَدَةُ);', NULL, 'ডিভাইন থার্মাল এন্ট্রপি সোর্স', NULL, 'نَارُ ٱللَّهِ ٱلْمُوقَدَةُ — ডিভাইনলি প্রিকিন্ডলড এনার্জি গ্রিড: আল্লাহর প্রজ্জ্বলিত চিরন্তন অগ্নি যা কখনো নিভে না।', 'https://everyayah.com/data/Alafasy_128kbps/104006.mp3', now()),
  (104, 7, '', '[{"id":7378,"position":1,"text_uthmani":"ٱلَّتِى","transliteration":"allatī","translation_bn":"যা","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":7379,"position":2,"text_uthmani":"تَطَّلِعُ","transliteration":"taṭṭaliʿu","translation_bn":"পৌঁছে যাবে","root":"طلع","lemma":"طَّلَعَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7380,"position":3,"text_uthmani":"عَلَى","transliteration":"ʿalā","translation_bn":"উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":7381,"position":4,"text_uthmani":"ٱلْأَفْـِٔدَةِ","transliteration":"l-afidati","translation_bn":"অন্তরসমূহের","root":"فاد","lemma":"فُؤَاد","grammar_bn":"শব্দ"},{"id":7382,"position":5,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'allatī taṭṭaliʿu ʿalā l-afidati', 'যা হৃদয় পর্যন্ত পৌঁছে যাবে।', 'Which mounts directed at the hearts.', 'যা হৃদয় পর্যন্ত পৌঁছে যাবে।', 'Which mounts directed at the hearts.', 'যার তীব্র বিকিরণ ও এনার্জি-ডিসরপশন সরাসরি মানুষের মূল চিন্তা প্রসেসিং সেন্টার, স্মৃতিভাণ্ডার ও চেতনার কোর ডোমেইন বা হৃদয়সমূহে (عَلَى الْأَفْئِدَةِ) অনুপ্রবেশ করে ভেতরের সমস্ত ডেটা-লগ সেকেন্ডে বার্ন করে দেয়;', NULL, 'চিন্তা প্রসেসিং সেন্টারে সরাসরি এনার্জি অ্যাটাক', NULL, 'ٱلَّتِى تَطَّلِعُ عَلَى ٱلْأَفْـِٔدَةِ — নিউরাল হার্ট অডিট ও ডিরেক্ট হিট: যা মানুষের বুকের গভীরে লুকানো অহংকার ও হিংসার মূল সেন্টারকে সরাসরি গ্রাস করে।', 'https://everyayah.com/data/Alafasy_128kbps/104007.mp3', now()),
  (104, 8, '', '[{"id":8482,"position":1,"text_uthmani":"إِنَّهَا","transliteration":"innahā","translation_bn":"নিশ্চয়ই তা","root":"—","lemma":"إِنّ","grammar_bn":"অভিঘাত পদ (Accusative)"},{"id":8483,"position":2,"text_uthmani":"عَلَيْهِم","transliteration":"ʿalayhim","translation_bn":"তাদের উপর","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":8484,"position":3,"text_uthmani":"مُّؤْصَدَةٌۭ","transliteration":"mu''ṣadatun","translation_bn":"অবরুদ্ধ করে দেয়া হবে","root":"وصد","lemma":"مُّؤْصَدَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":8485,"position":4,"text_uthmani":"٨","transliteration":"","translation_bn":"(৮)","root":"—","lemma":"٨","grammar_bn":"মার্কার"}]'::jsonb, 'innahā ʿalayhim mu''ṣadatun', 'তা তাদেরকে চতুর্দিক থেকে পরিবেষ্টন করে রাখবে,', 'Indeed, Hellfire will be closed down upon them', 'তা তাদেরকে চতুর্দিক থেকে পরিবেষ্টন করে রাখবে,', 'Indeed, Hellfire will be closed down upon them', 'নিশ্চয়ই সেই এন্ট্রপি ক্র্যাশ-জোনটি এই পার্মানেন্ট এরর-যুক্ত নোডগুলোর চারপাশ থেকে সম্পূর্ণ সিলড্ বা ডাইমেনশনালি এনক্যাপসুলেট (مُّؤْصَدةٌ) করে লক করে দেওয়া হবে;', NULL, 'পার্মানেন্ট ডাইমেনশনাল এনক্যাপসুলেশন', NULL, 'إِنَّهَا عَلَيْهِم مُّؤْصَدَةٌۭ — হারমেটিক্যালি সিলড ফায়ারওয়াল চেম্বার: যার চারপাশ সম্পূর্ণরূপে বন্ধ এবং কোনো এক্সিট পোর্ট নেই।', 'https://everyayah.com/data/Alafasy_128kbps/104008.mp3', now()),
  (104, 9, '', '[{"id":10159,"position":1,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":10160,"position":2,"text_uthmani":"عَمَدٍۢ","transliteration":"ʿamadin","translation_bn":"স্তম্ভসমূহের","root":"عمد","lemma":"عَمَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10161,"position":3,"text_uthmani":"مُّمَدَّدَةٍۭ","transliteration":"mumaddadatin","translation_bn":"দীর্ঘায়িত","root":"مدد","lemma":"مُّمَدَّدَة","grammar_bn":"বিশেষণ (Adjective)"},{"id":10162,"position":4,"text_uthmani":"٩","transliteration":"","translation_bn":"(৯)","root":"—","lemma":"٩","grammar_bn":"মার্কার"}]'::jsonb, 'fī ʿamadin mumaddadatin', '(লেলিহান অগ্নিশিখার) উঁচু উঁচু স্তম্ভে।', 'In extended columns.', '(লেলিহান অগ্নিশিখার) উঁচু উঁচু স্তম্ভে।', 'In extended columns.', 'এক অতি-উচ্চ ঘনত্বের অবিনশ্বর এনার্জি গ্রিড, অভিকর্ষীয় আকর্ষণ বা সুদীর্ঘ অগ্নি-স্তম্ভসমূহের (فِي عَمَدٍ مُّمَدَّدَةٍ) বন্ধ লুপের ভেতর।', NULL, 'অবিনশ্বর এনার্জি গ্রিড ও ক্লোজড লুপ', NULL, 'فِى عَمَدٍۢ مُّمَدَّدَةٍۭ — এক্সটেন্ডেড এনার্জি কলামস ও পার্মানেন্ট লক: সুউচ্চ স্তম্ভে আবদ্ধ করে চিরতরে বন্দি রাখার মেকানিজম।', 'https://everyayah.com/data/Alafasy_128kbps/104009.mp3', now())
