  (104, 9, 'অবিনশ্বর এনার্জি গ্রিড ও ক্লোজড লুপ', NULL, now())
INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (105, 1, '', '[{"id":137,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"নাই কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":138,"position":2,"text_uthmani":"تَرَ","transliteration":"tara","translation_bn":"তুমি দেখো","root":"راي","lemma":"رَءَا","grammar_bn":"ক্রিয়া (Verb)"},{"id":139,"position":3,"text_uthmani":"كَيْفَ","transliteration":"kayfa","translation_bn":"কেমন","root":"كيف\r","lemma":"كَيْف","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":140,"position":4,"text_uthmani":"فَعَلَ","transliteration":"faʿala","translation_bn":"করেছেন","root":"فعل","lemma":"فَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":141,"position":5,"text_uthmani":"رَبُّكَ","transliteration":"rabbuka","translation_bn":"তোমার রব","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":142,"position":6,"text_uthmani":"بِأَصْحَـٰبِ","transliteration":"bi-aṣḥābi","translation_bn":"বাহিনীর সাথে","root":"صحب","lemma":"أَصْحَٰب","grammar_bn":"অব্যয় (Preposition)"},{"id":143,"position":7,"text_uthmani":"ٱلْفِيلِ","transliteration":"l-fīli","translation_bn":"হাতি","root":"فيل","lemma":"فِيل","grammar_bn":"শব্দ"},{"id":144,"position":8,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'alam tara kayfa faʿala rabbuka bi-aṣḥābi l-fīli', 'তুমি কি দেখনি (কা‘বা ঘর ধ্বংসের জন্য আগত) হাতীওয়ালাদের সঙ্গে তোমার প্রতিপালক কীরূপ ব্যবহার করেছিলেন?', 'Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?', 'তুমি কি দেখনি (কা‘বা ঘর ধ্বংসের জন্য আগত) হাতীওয়ালাদের সঙ্গে তোমার প্রতিপালক কীরূপ ব্যবহার করেছিলেন?', 'Have you not considered, [O Muhammad], how your Lord dealt with the companions of the elephant?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/105001.mp3', now()),
  (105, 2, '', '[{"id":1019,"position":1,"text_uthmani":"أَلَمْ","transliteration":"alam","translation_bn":"নাই কি","root":"—","lemma":"لَم\r","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":1020,"position":2,"text_uthmani":"يَجْعَلْ","transliteration":"yajʿal","translation_bn":"তিনি পরণত করে","root":"جعل","lemma":"جَعَلَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1021,"position":3,"text_uthmani":"كَيْدَهُمْ","transliteration":"kaydahum","translation_bn":"তাদের ষড়যন্ত্রকে","root":"كيد","lemma":"كَيْد","grammar_bn":"বিশেষ্য (Noun)"},{"id":1022,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":1023,"position":5,"text_uthmani":"تَضْلِيلٍۢ","transliteration":"taḍlīlin","translation_bn":"নিষ্ফলতার","root":"ضلل","lemma":"تَضْلِيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":1024,"position":6,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'alam yajʿal kaydahum fī taḍlīlin', 'তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?', 'Did He not make their plan into misguidance?', 'তিনি কি তাদের চক্রান্ত ব্যর্থ করে দেননি?', 'Did He not make their plan into misguidance?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/105002.mp3', now()),
  (105, 3, '', '[{"id":2361,"position":1,"text_uthmani":"وَأَرْسَلَ","transliteration":"wa-arsala","translation_bn":"এবং পাঠিয়েছেন","root":"رسل","lemma":"أَرْسَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2362,"position":2,"text_uthmani":"عَلَيْهِمْ","transliteration":"ʿalayhim","translation_bn":"তাদের বিরুদ্ধে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2363,"position":3,"text_uthmani":"طَيْرًا","transliteration":"ṭayran","translation_bn":"পাখি","root":"طير","lemma":"طَيْر","grammar_bn":"বিশেষ্য (Noun)"},{"id":2364,"position":4,"text_uthmani":"أَبَابِيلَ","transliteration":"abābīla","translation_bn":"ঝাঁকে ঝাঁকে","root":"ابل","lemma":"أَبَابِيل","grammar_bn":"বিশেষণ (Adjective)"},{"id":2365,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wa-arsala ʿalayhim ṭayran abābīla', 'তিনি তাদের বিরুদ্ধে পাঠিয়েছিলেন ঝাঁকে ঝাঁকে পাখি।', 'And He sent against them birds in flocks,', 'তিনি তাদের বিরুদ্ধে পাঠিয়েছিলেন ঝাঁকে ঝাঁকে পাখি।', 'And He sent against them birds in flocks,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/105003.mp3', now()),
  (105, 4, '', '[{"id":3867,"position":1,"text_uthmani":"تَرْمِيهِم","transliteration":"tarmīhim","translation_bn":"তাদের উপর নিক্ষেপ করে","root":"رمي","lemma":"رَمَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3868,"position":2,"text_uthmani":"بِحِجَارَةٍۢ","transliteration":"biḥijāratin","translation_bn":"পাথরসমূহকে","root":"حجر","lemma":"حِجَارَة","grammar_bn":"অব্যয় (Preposition)"},{"id":3869,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3870,"position":4,"text_uthmani":"سِجِّيلٍۢ","transliteration":"sijjīlin","translation_bn":"কংকরের","root":"سجل","lemma":"سِجِّيل","grammar_bn":"বিশেষ্য (Noun)"},{"id":3871,"position":5,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'tarmīhim biḥijāratin min sijjīlin', 'যারা তাদের উপর পাথরের কাঁকর নিক্ষেপ করেছিল।', 'Striking them with stones of hard clay,', 'যারা তাদের উপর পাথরের কাঁকর নিক্ষেপ করেছিল।', 'Striking them with stones of hard clay,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/105004.mp3', now()),
  (105, 5, '', '[{"id":5092,"position":1,"text_uthmani":"فَجَعَلَهُمْ","transliteration":"fajaʿalahum","translation_bn":"অতঃপর তিনি তাদের করে দেন","root":"جعل","lemma":"جَعَلَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5093,"position":2,"text_uthmani":"كَعَصْفٍۢ","transliteration":"kaʿaṣfin","translation_bn":"ভুসির মতো","root":"عصف","lemma":"عَصْف","grammar_bn":"অব্যয় (Preposition)"},{"id":5094,"position":3,"text_uthmani":"مَّأْكُولٍۭ","transliteration":"makūlin","translation_bn":"খাওয়া/ভক্ষিত","root":"اكل","lemma":"مَّأْكُول","grammar_bn":"বিশেষণ (Adjective)"},{"id":5095,"position":4,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fajaʿalahum kaʿaṣfin makūlin', 'অতঃপর তিনি তাদেরকে করে দিলেন ভক্ষিত তৃণ-ভুষির মত।', 'And He made them like eaten straw.', 'অতঃপর তিনি তাদেরকে করে দিলেন ভক্ষিত তৃণ-ভুষির মত।', 'And He made them like eaten straw.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/105005.mp3', now())
