  (106, 1, '', '[{"id":266,"position":1,"text_uthmani":"لِإِيلَـٰفِ","transliteration":"liīlāfi","translation_bn":"যেহেতু আসক্তি আছে","root":"الف","lemma":"إِلَٰف","grammar_bn":"অব্যয় (Preposition)"},{"id":267,"position":2,"text_uthmani":"قُرَيْشٍ","transliteration":"qurayshin","translation_bn":"কুরাইশদের","root":"—","lemma":"قُرَيْش","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":268,"position":3,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'liīlāfi qurayshin', 'কুরাইশদের অভ্যস্ত হওয়ার কারণে,', 'For the accustomed security of the Quraysh -', 'কুরাইশদের অভ্যস্ত হওয়ার কারণে,', 'For the accustomed security of the Quraysh -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/106001.mp3', now()),
  (106, 2, '', '[{"id":961,"position":1,"text_uthmani":"إِۦلَـٰفِهِمْ","transliteration":"īlāfihim","translation_bn":"আসক্তি আছে","root":"الف","lemma":"إِلَٰف","grammar_bn":"বিশেষ্য (Noun)"},{"id":962,"position":2,"text_uthmani":"رِحْلَةَ","transliteration":"riḥ''lata","translation_bn":"ভ্রমণে","root":"رحل","lemma":"رِحْلَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":963,"position":3,"text_uthmani":"ٱلشِّتَآءِ","transliteration":"l-shitāi","translation_bn":"শীতের","root":"شتو","lemma":"شِّتَا^ء","grammar_bn":"শব্দ"},{"id":964,"position":4,"text_uthmani":"وَٱلصَّيْفِ","transliteration":"wal-ṣayfi","translation_bn":"ও গ্রীষ্মের","root":"صيف","lemma":"صَّيْف","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":965,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'īlāfihim riḥ''lata l-shitāi wal-ṣayfi', '(অর্থাৎ) শীত ও গ্রীষ্মে তাদের বিদেশ সফরে অভ্যস্ত হওয়ার (কারণে)', 'Their accustomed security [in] the caravan of winter and summer -', '(অর্থাৎ) শীত ও গ্রীষ্মে তাদের বিদেশ সফরে অভ্যস্ত হওয়ার (কারণে)', 'Their accustomed security [in] the caravan of winter and summer -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/106002.mp3', now()),
  (106, 3, '', '[{"id":2411,"position":1,"text_uthmani":"فَلْيَعْبُدُوا۟","transliteration":"falyaʿbudū","translation_bn":"অতএব তারা ইবাদত করুক","root":"عبد","lemma":"عَبَدَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2412,"position":2,"text_uthmani":"رَبَّ","transliteration":"rabba","translation_bn":"রবের","root":"ربب","lemma":"رَبّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2413,"position":3,"text_uthmani":"هَـٰذَا","transliteration":"hādhā","translation_bn":"এই","root":"—","lemma":"هَٰذَا","grammar_bn":"নির্দেশক সর্বনাম (Demonstrative)"},{"id":2414,"position":4,"text_uthmani":"ٱلْبَيْتِ","transliteration":"l-bayti","translation_bn":"ঘরের","root":"بيت","lemma":"بَيْت","grammar_bn":"শব্দ"},{"id":2415,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'falyaʿbudū rabba hādhā l-bayti', 'তাদের কর্তব্য হল এই (কা‘বা) ঘরের রবের ‘ইবাদাত করা,', 'Let them worship the Lord of this House,', 'তাদের কর্তব্য হল এই (কা‘বা) ঘরের রবের ‘ইবাদাত করা,', 'Let them worship the Lord of this House,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/106003.mp3', now()),
  (106, 4, '', '[{"id":3906,"position":1,"text_uthmani":"ٱلَّذِىٓ","transliteration":"alladhī","translation_bn":"যিনি","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":3907,"position":2,"text_uthmani":"أَطْعَمَهُم","transliteration":"aṭʿamahum","translation_bn":"তাদেরকে খাবার দিয়েছেন","root":"طعم","lemma":"أَطْعَمَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":3908,"position":3,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3909,"position":4,"text_uthmani":"جُوعٍۢ","transliteration":"jūʿin","translation_bn":"ক্ষুধা","root":"جوع","lemma":"جُوع","grammar_bn":"বিশেষ্য (Noun)"},{"id":3910,"position":5,"text_uthmani":"وَءَامَنَهُم","transliteration":"waāmanahum","translation_bn":"এবং তাদের নিরাপত্তা দিয়েছেন","root":"امن","lemma":"ءَامَنَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":3911,"position":6,"text_uthmani":"مِّنْ","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":3912,"position":7,"text_uthmani":"خَوْفٍۭ","transliteration":"khawfin","translation_bn":"ভয়","root":"خوف","lemma":"خَوْف","grammar_bn":"বিশেষ্য (Noun)"},{"id":3913,"position":8,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'alladhī aṭʿamahum min jūʿin waāmanahum min khawfin', 'যিনি তাদেরকে (কা‘বা ঘরের খাদিম হওয়ার কারণে নির্বিঘ্নে ব্যবসা-বাণিজ্যের মাধ্যমে) ক্ষুধায় খাদ্য দিচ্ছেন এবং তাদেরকে ভয়-ভীতি হতে নিরাপদ করেছেন।', 'Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.', 'যিনি তাদেরকে (কা‘বা ঘরের খাদিম হওয়ার কারণে নির্বিঘ্নে ব্যবসা-বাণিজ্যের মাধ্যমে) ক্ষুধায় খাদ্য দিচ্ছেন এবং তাদেরকে ভয়-ভীতি হতে নিরাপদ করেছেন।', 'Who has fed them, [saving them] from hunger and made them safe, [saving them] from fear.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/106004.mp3', now())
