VALUES
  (107, 1, '', '[{"id":256,"position":1,"text_uthmani":"أَرَءَيْتَ","transliteration":"ara-ayta","translation_bn":"তুমি কি দেখেছ","root":"راي","lemma":"رَءَا","grammar_bn":"প্রশ্নবোধক (Interrogative)"},{"id":257,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"(তাকে) যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":258,"position":3,"text_uthmani":"يُكَذِّبُ","transliteration":"yukadhibu","translation_bn":"মিথ্যা অভিহিত করে","root":"كذب","lemma":"كَذَّبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":259,"position":4,"text_uthmani":"بِٱلدِّينِ","transliteration":"bil-dīni","translation_bn":"বিচার দিনকে","root":"دين","lemma":"دِين","grammar_bn":"অব্যয় (Preposition)"},{"id":260,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'ara-ayta alladhī yukadhibu bil-dīni', 'তুমি কি তাকে দেখেছ, যে কর্মফল (দিবসকে) অস্বীকার করে?', 'Have you seen the one who denies the Recompense?', 'তুমি কি তাকে দেখেছ, যে কর্মফল (দিবসকে) অস্বীকার করে?', 'Have you seen the one who denies the Recompense?', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107001.mp3', now()),
  (107, 2, '', '[{"id":1007,"position":1,"text_uthmani":"فَذَٰلِكَ","transliteration":"fadhālika","translation_bn":"সে তো সে-ই","root":"—","lemma":"ذَٰلِك","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":1008,"position":2,"text_uthmani":"ٱلَّذِى","transliteration":"alladhī","translation_bn":"যে","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":1009,"position":3,"text_uthmani":"يَدُعُّ","transliteration":"yaduʿʿu","translation_bn":"ধাক্কা দেয়","root":"دعع","lemma":"يَدُعُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":1010,"position":4,"text_uthmani":"ٱلْيَتِيمَ","transliteration":"l-yatīma","translation_bn":"ইয়াতিমকে","root":"يتم","lemma":"يَتِيم","grammar_bn":"শব্দ"},{"id":1011,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'fadhālika alladhī yaduʿʿu l-yatīma', 'সে তো সেই (লোক) যে ইয়াতীমকে ধাক্কা দিয়ে সরিয়ে দেয়,', 'For that is the one who drives away the orphan', 'সে তো সেই (লোক) যে ইয়াতীমকে ধাক্কা দিয়ে সরিয়ে দেয়,', 'For that is the one who drives away the orphan', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107002.mp3', now()),
  (107, 3, '', '[{"id":2449,"position":1,"text_uthmani":"وَلَا","transliteration":"walā","translation_bn":"এবং না","root":"—","lemma":"لَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2450,"position":2,"text_uthmani":"يَحُضُّ","transliteration":"yaḥuḍḍu","translation_bn":"উৎসাহিত করে","root":"حضض","lemma":"يَحُضُّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2451,"position":3,"text_uthmani":"عَلَىٰ","transliteration":"ʿalā","translation_bn":"ব্যাপারে","root":"—","lemma":"عَلَىٰ\r","grammar_bn":"অব্যয় (Preposition)"},{"id":2452,"position":4,"text_uthmani":"طَعَامِ","transliteration":"ṭaʿāmi","translation_bn":"খাদ্যদানের","root":"طعم","lemma":"طَعَام","grammar_bn":"বিশেষ্য (Noun)"},{"id":2453,"position":5,"text_uthmani":"ٱلْمِسْكِينِ","transliteration":"l-mis''kīni","translation_bn":"অভাবগ্রস্তকে","root":"سكن","lemma":"مِسْكِين","grammar_bn":"শব্দ"},{"id":2454,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'walā yaḥuḍḍu ʿalā ṭaʿāmi l-mis''kīni', 'এবং মিসকীনকে অন্ন দিতে উৎসাহ দেয় না', 'And does not encourage the feeding of the poor.', 'এবং মিসকীনকে অন্ন দিতে উৎসাহ দেয় না', 'And does not encourage the feeding of the poor.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107003.mp3', now()),
  (107, 4, '', '[{"id":3903,"position":1,"text_uthmani":"فَوَيْلٌۭ","transliteration":"fawaylun","translation_bn":"অতএব দুর্ভোগ","root":"—","lemma":"وَيْل","grammar_bn":"শব্দ"},{"id":3904,"position":2,"text_uthmani":"لِّلْمُصَلِّينَ","transliteration":"lil''muṣallīna","translation_bn":"(ঐসব) সালাত আদায়কারীদের জন্য","root":"صلو","lemma":"مُصَلِّين","grammar_bn":"অব্যয় (Preposition)"},{"id":3905,"position":3,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'fawaylun lil''muṣallīna', 'অতএব দুর্ভোগ সে সব নামায আদায়কারীর', 'So woe to those who pray', 'অতএব দুর্ভোগ সে সব নামায আদায়কারীর', 'So woe to those who pray', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107004.mp3', now()),
  (107, 5, '', '[{"id":5264,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের (বৈশিষ্ট্য হলো)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":5265,"position":2,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":5266,"position":3,"text_uthmani":"عَن","transliteration":"ʿan","translation_bn":"সম্বন্ধে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5267,"position":4,"text_uthmani":"صَلَاتِهِمْ","transliteration":"ṣalātihim","translation_bn":"তাদের সালাত","root":"صلو","lemma":"صَلَوٰة","grammar_bn":"বিশেষ্য (Noun)"},{"id":5268,"position":5,"text_uthmani":"سَاهُونَ","transliteration":"sāhūna","translation_bn":"উদাসীন","root":"سهو","lemma":"سَاهُون","grammar_bn":"বিশেষ্য (Noun)"},{"id":5269,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna hum ʿan ṣalātihim sāhūna', 'যারা নিজেদের নামাযের ব্যাপারে উদাসীন,', '[But] who are heedless of their prayer -', 'যারা নিজেদের নামাযের ব্যাপারে উদাসীন,', '[But] who are heedless of their prayer -', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107005.mp3', now()),
  (107, 6, '', '[{"id":6392,"position":1,"text_uthmani":"ٱلَّذِينَ","transliteration":"alladhīna","translation_bn":"যাদের (বৈশিষ্ট্য হলো)","root":"—","lemma":"ٱلَّذِى","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":6393,"position":2,"text_uthmani":"هُمْ","transliteration":"hum","translation_bn":"তারা","root":"—","lemma":"هُمْ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":6394,"position":3,"text_uthmani":"يُرَآءُونَ","transliteration":"yurāūna","translation_bn":"লোকদেখানোর (কাজ করে)","root":"راي","lemma":"يُرَا^ءُ","grammar_bn":"ক্রিয়া (Verb)"},{"id":6395,"position":4,"text_uthmani":"٦","transliteration":"","translation_bn":"(৬)","root":"—","lemma":"٦","grammar_bn":"মার্কার"}]'::jsonb, 'alladhīna hum yurāūna', 'যারা লোক দেখানোর জন্য তা করে,', 'Those who make show [of their deeds]', 'যারা লোক দেখানোর জন্য তা করে,', 'Those who make show [of their deeds]', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107006.mp3', now()),
  (107, 7, '', '[{"id":7669,"position":1,"text_uthmani":"وَيَمْنَعُونَ","transliteration":"wayamnaʿūna","translation_bn":"এবং দেওয়া হতে বিরত থাকে","root":"منع","lemma":"مَّنَعَ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":7670,"position":2,"text_uthmani":"ٱلْمَاعُونَ","transliteration":"l-māʿūna","translation_bn":"সংসারের প্রয়োজনীয় ছোটখাটো জিনিসের","root":"معن","lemma":"مَاعُون","grammar_bn":"শব্দ"},{"id":7671,"position":3,"text_uthmani":"٧","transliteration":"","translation_bn":"(৭)","root":"—","lemma":"٧","grammar_bn":"মার্কার"}]'::jsonb, 'wayamnaʿūna l-māʿūna', 'এবং প্রয়োজনীয় গৃহসামগ্রী দানের ছোট খাট সাহায্য করা থেকেও বিরত থাকে।', 'And withhold [simple] assistance.', 'এবং প্রয়োজনীয় গৃহসামগ্রী দানের ছোট খাট সাহায্য করা থেকেও বিরত থাকে।', 'And withhold [simple] assistance.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/107007.mp3', now())
