VALUES
  (111, 1, '', '[{"id":18,"position":1,"text_uthmani":"تَبَّتْ","transliteration":"tabbat","translation_bn":"ধ্বংস হোক","root":"تبب","lemma":"تَبَّ","grammar_bn":"ক্রিয়া (Verb)"},{"id":19,"position":2,"text_uthmani":"يَدَآ","transliteration":"yadā","translation_bn":"দু''হাত","root":"يدي","lemma":"يَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":20,"position":3,"text_uthmani":"أَبِى","transliteration":"abī","translation_bn":"আবু","root":"ابو","lemma":"أَبٌ","grammar_bn":"বিশেষ্য (Noun)"},{"id":21,"position":4,"text_uthmani":"لَهَبٍۢ","transliteration":"lahabin","translation_bn":"লাহাবের","root":"لهب","lemma":"لَهَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":22,"position":5,"text_uthmani":"وَتَبَّ","transliteration":"watabba","translation_bn":"এবং সেও ধ্বংস হোক","root":"تبب","lemma":"تَبَّ","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":23,"position":6,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'tabbat yadā abī lahabin watabba', 'আবূ লাহাবের হাত দু‘টো ধ্বংস হোক, ধ্বংস হোক সে নিজে,', 'May the hands of Abu Lahab be ruined, and ruined is he.', 'আবূ লাহাবের হাত দু‘টো ধ্বংস হোক, ধ্বংস হোক সে নিজে,', 'May the hands of Abu Lahab be ruined, and ruined is he.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/111001.mp3', now()),
  (111, 2, '', '[{"id":949,"position":1,"text_uthmani":"مَآ","transliteration":"mā","translation_bn":"না","root":"—","lemma":"مَا\r","grammar_bn":"না-বোধক (Negative)"},{"id":950,"position":2,"text_uthmani":"أَغْنَىٰ","transliteration":"aghnā","translation_bn":"কাজে আসলো","root":"غني","lemma":"أَغْنَىٰ","grammar_bn":"ক্রিয়া (Verb)"},{"id":951,"position":3,"text_uthmani":"عَنْهُ","transliteration":"ʿanhu","translation_bn":"তার পক্ষে","root":"—","lemma":"عَن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":952,"position":4,"text_uthmani":"مَالُهُۥ","transliteration":"māluhu","translation_bn":"তার সম্পদ","root":"مول","lemma":"مَال","grammar_bn":"বিশেষ্য (Noun)"},{"id":953,"position":5,"text_uthmani":"وَمَا","transliteration":"wamā","translation_bn":"আর যা","root":"—","lemma":"مَا\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":954,"position":6,"text_uthmani":"كَسَبَ","transliteration":"kasaba","translation_bn":"সে  উপার্জন করেছিল","root":"كسب","lemma":"كَسَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":955,"position":7,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'mā aghnā ʿanhu māluhu wamā kasaba', 'তার ধন-সম্পদ আর সে যা অর্জন করেছে তা তার কোন কাজে আসল না,', 'His wealth will not avail him or that which he gained.', 'তার ধন-সম্পদ আর সে যা অর্জন করেছে তা তার কোন কাজে আসল না,', 'His wealth will not avail him or that which he gained.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/111002.mp3', now()),
  (111, 3, '', '[{"id":2625,"position":1,"text_uthmani":"سَيَصْلَىٰ","transliteration":"sayaṣlā","translation_bn":"শীঘ্রই জ্বলবে","root":"صلي","lemma":"يَصْلَى","grammar_bn":"ভবিষ্যদ্বাচক (Future)"},{"id":2626,"position":2,"text_uthmani":"نَارًۭا","transliteration":"nāran","translation_bn":"আগুনে","root":"نور","lemma":"نَار","grammar_bn":"বিশেষ্য (Noun)"},{"id":2627,"position":3,"text_uthmani":"ذَاتَ","transliteration":"dhāta","translation_bn":"সমন্বিত","root":"—","lemma":"ذُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":2628,"position":4,"text_uthmani":"لَهَبٍۢ","transliteration":"lahabin","translation_bn":"শিখা","root":"لهب","lemma":"لَهَب","grammar_bn":"বিশেষ্য (Noun)"},{"id":2629,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'sayaṣlā nāran dhāta lahabin', 'অচিরে সে প্রবেশ করবে লেলিহান শিখাযুক্ত আগুনে,', 'He will [enter to] burn in a Fire of [blazing] flame', 'অচিরে সে প্রবেশ করবে লেলিহান শিখাযুক্ত আগুনে,', 'He will [enter to] burn in a Fire of [blazing] flame', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/111003.mp3', now()),
  (111, 4, '', '[{"id":4041,"position":1,"text_uthmani":"وَٱمْرَأَتُهُۥ","transliteration":"wa-im''ra-atuhu","translation_bn":"এবং তার স্ত্রীও","root":"مرا","lemma":"ٱمْرَأَت","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4042,"position":2,"text_uthmani":"حَمَّالَةَ","transliteration":"ḥammālata","translation_bn":"বহনকারিণী","root":"حمل","lemma":"حَمَّالَة","grammar_bn":"বিশেষ্য (Noun)"},{"id":4043,"position":3,"text_uthmani":"ٱلْحَطَبِ","transliteration":"l-ḥaṭabi","translation_bn":"কাঠের","root":"حطب","lemma":"حَطَب","grammar_bn":"শব্দ"},{"id":4044,"position":4,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wa-im''ra-atuhu ḥammālata l-ḥaṭabi', 'আর তার স্ত্রীও- যে কাঠবহনকারিণী (যে কাঁটার সাহায্যে নবী-কে কষ্ট দিত এবং একজনের কথা অন্যজনকে ব’লে পারস্পরিক বিবাদের আগুন জ্বালাত)।', 'And his wife [as well] - the carrier of firewood.', 'আর তার স্ত্রীও- যে কাঠবহনকারিণী (যে কাঁটার সাহায্যে নবী-কে কষ্ট দিত এবং একজনের কথা অন্যজনকে ব’লে পারস্পরিক বিবাদের আগুন জ্বালাত)।', 'And his wife [as well] - the carrier of firewood.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/111004.mp3', now()),
  (111, 5, '', '[{"id":5280,"position":1,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5281,"position":2,"text_uthmani":"جِيدِهَا","transliteration":"jīdihā","translation_bn":"তার গলার","root":"جيد","lemma":"جِيد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5282,"position":3,"text_uthmani":"حَبْلٌۭ","transliteration":"ḥablun","translation_bn":"দড়ি","root":"حبل","lemma":"حَبْل","grammar_bn":"বিশেষ্য (Noun)"},{"id":5283,"position":4,"text_uthmani":"مِّن","transliteration":"min","translation_bn":"থেকে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":5284,"position":5,"text_uthmani":"مَّسَدٍۭ","transliteration":"masadin","translation_bn":"পাকানো","root":"مسد","lemma":"مَّسَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5285,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'fī jīdihā ḥablun min masadin', 'আর (দুনিয়াতে তার বহনকৃত কাঠ-খড়ির পরিবর্তে জাহান্নামে) তার গলায় শক্ত পাকানো রশি বাঁধা থাকবে।', 'Around her neck is a rope of [twisted] fiber.', 'আর (দুনিয়াতে তার বহনকৃত কাঠ-খড়ির পরিবর্তে জাহান্নামে) তার গলায় শক্ত পাকানো রশি বাঁধা থাকবে।', 'Around her neck is a rope of [twisted] fiber.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/111005.mp3', now())
INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (112, 1, '', '[{"id":6,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":7,"position":2,"text_uthmani":"هُوَ","transliteration":"huwa","translation_bn":"\"তিনি","root":"—","lemma":"هُوَ","grammar_bn":"সর্বনাম (Pronoun)"},{"id":8,"position":3,"text_uthmani":"ٱللَّهُ","transliteration":"l-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":9,"position":4,"text_uthmani":"أَحَدٌ","transliteration":"aḥadun","translation_bn":"এক-অদ্বিতীয়","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":10,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'qul huwa l-lahu aḥadun', 'বল, তিনি আল্লাহ, এক অদ্বিতীয়,', 'Say, "He is Allah, [who is] One,', 'বল, তিনি আল্লাহ, এক অদ্বিতীয়,', 'Say, "He is Allah, [who is] One,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/112001.mp3', now()),
  (112, 2, '', '[{"id":916,"position":1,"text_uthmani":"ٱللَّهُ","transliteration":"al-lahu","translation_bn":"আল্লাহ","root":"اله","lemma":"ٱللَّه","grammar_bn":"নামবাচক বিশেষ্য (Proper Noun)"},{"id":917,"position":2,"text_uthmani":"ٱلصَّمَدُ","transliteration":"l-ṣamadu","translation_bn":"অমুখাপেক্ষী","root":"صمد","lemma":"صَّمَد","grammar_bn":"শব্দ"},{"id":918,"position":3,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'al-lahu l-ṣamadu', 'আল্লাহ কোন কিছুর মুখাপেক্ষী নন, সবই তাঁর মুখাপেক্ষী,', 'Allah, the Eternal Refuge.', 'আল্লাহ কোন কিছুর মুখাপেক্ষী নন, সবই তাঁর মুখাপেক্ষী,', 'Allah, the Eternal Refuge.', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/112002.mp3', now()),
  (112, 3, '', '[{"id":2746,"position":1,"text_uthmani":"لَمْ","transliteration":"lam","translation_bn":"নি","root":"—","lemma":"لَم\r","grammar_bn":"না-বোধক (Negative)"},{"id":2747,"position":2,"text_uthmani":"يَلِدْ","transliteration":"yalid","translation_bn":"তিনি (কাউকে) জন্ম দেন","root":"ولد","lemma":"وَلَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2748,"position":3,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নি","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2749,"position":4,"text_uthmani":"يُولَدْ","transliteration":"yūlad","translation_bn":"তাঁকে জন্ম দেয়া হয়","root":"ولد","lemma":"وَلَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2750,"position":5,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'lam yalid walam yūlad', 'তিনি কাউকে জন্ম দেন না, আর তাঁকেও জন্ম দেয়া হয়নি।', 'He neither begets nor is born,', 'তিনি কাউকে জন্ম দেন না, আর তাঁকেও জন্ম দেয়া হয়নি।', 'He neither begets nor is born,', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/112003.mp3', now()),
  (112, 4, '', '[{"id":4136,"position":1,"text_uthmani":"وَلَمْ","transliteration":"walam","translation_bn":"এবং নাই","root":"—","lemma":"لَم\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4137,"position":2,"text_uthmani":"يَكُن","transliteration":"yakun","translation_bn":"(হয়)","root":"كون","lemma":"كَانَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":4138,"position":3,"text_uthmani":"لَّهُۥ","transliteration":"lahu","translation_bn":"তাঁর","root":"—","lemma":"لَّهُۥ","grammar_bn":"অব্যয় (Preposition)"},{"id":4139,"position":4,"text_uthmani":"كُفُوًا","transliteration":"kufuwan","translation_bn":"সমতুল্য/ সমান","root":"كفا","lemma":"كُفُو","grammar_bn":"বিশেষ্য (Noun)"},{"id":4140,"position":5,"text_uthmani":"أَحَدٌۢ","transliteration":"aḥadun","translation_bn":"কেউই\"","root":"احد","lemma":"أَحَد","grammar_bn":"বিশেষ্য (Noun)"},{"id":4141,"position":6,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'walam yakun lahu kufuwan aḥadun', 'তাঁর সমকক্ষ কেউ নয়।', 'Nor is there to Him any equivalent."', 'তাঁর সমকক্ষ কেউ নয়।', 'Nor is there to Him any equivalent."', NULL, NULL, NULL, NULL, NULL, 'https://everyayah.com/data/Alafasy_128kbps/112004.mp3', now())
INSERT INTO public.quran_verses (surah, ayah, text_uthmani, words, transliteration, bn_text, en_text, conventional_bn, conventional_en, modern_translation_bn, modern_translation_en, meta_bn, meta_en, lexicon_modern_notes, audio_url, updated_at)
VALUES
  (113, 1, '', '[{"id":215,"position":1,"text_uthmani":"قُلْ","transliteration":"qul","translation_bn":"বলো","root":"قول","lemma":"قَالَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":216,"position":2,"text_uthmani":"أَعُوذُ","transliteration":"aʿūdhu","translation_bn":"\"আমি আশ্রয় চাই","root":"عوذ","lemma":"عُذْ","grammar_bn":"ক্রিয়া (Verb)"},{"id":217,"position":3,"text_uthmani":"بِرَبِّ","transliteration":"birabbi","translation_bn":"স্রষ্টার নিকট","root":"ربب","lemma":"رَبّ","grammar_bn":"অব্যয় (Preposition)"},{"id":218,"position":4,"text_uthmani":"ٱلْفَلَقِ","transliteration":"l-falaqi","translation_bn":"প্রভাতের","root":"فلق","lemma":"فَلَق","grammar_bn":"শব্দ"},{"id":219,"position":5,"text_uthmani":"١","transliteration":"","translation_bn":"(১)","root":"—","lemma":"١","grammar_bn":"মার্কার"}]'::jsonb, 'qul aʿūdhu birabbi l-falaqi', 'বল, ‘আমি আশ্রয় চাচ্ছি সকাল বেলার রব-এর,', 'Say, "I seek refuge in the Lord of daybreak', 'বল, ‘আমি আশ্রয় চাচ্ছি সকাল বেলার রব-এর,', 'Say, "I seek refuge in the Lord of daybreak', 'তুমি তোমার ওওএসে (OOS) এই কসমিক সিকিউরিটি শিল্ড বা ডিফেন্স কমান্ড ইনপুট দাও—‘আমি আমার চেতনার রিসিভিং ভেক্টরকে রি-অ্যালাইন বা আশ্রয় (أَعُوذُ) করছি বিগ ব্যাং সিঙ্গুলারিটি এবং কসমিক এক্সপ্যানশনের মাধ্যমে স্থান-কাল উন্মোচনকারী পরম প্রতিপালকের (بِرَبِّ الْفَلَقِ) মূল সোর্স কোডের সাথে—', NULL, 'বিগ ব্যাং সিঙ্গুলারিটি ও কসমিক সিকিউরিটি ডিফেন্স', NULL, 'قُلْ أَعُوذُ بِرَبِّ ٱلْفَلَقِ — কসমিক ডন ও মহাজাগতিক স্প্লিটিং এনার্জির সুপ্রীম আর্কিটেক্টের আশ্রয়ে ফায়ারওয়াল শিল্ড সক্রিয়করণ।', 'https://everyayah.com/data/Alafasy_128kbps/113001.mp3', now()),
  (113, 2, '', '[{"id":969,"position":1,"text_uthmani":"مِن","transliteration":"min","translation_bn":"হতে","root":"—","lemma":"مِن\r","grammar_bn":"অব্যয় (Preposition)"},{"id":970,"position":2,"text_uthmani":"شَرِّ","transliteration":"sharri","translation_bn":"অনিষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":971,"position":3,"text_uthmani":"مَا","transliteration":"mā","translation_bn":"যা","root":"—","lemma":"مَا\r","grammar_bn":"সাপেক্ষ সর্বনাম (Relative)"},{"id":972,"position":4,"text_uthmani":"خَلَقَ","transliteration":"khalaqa","translation_bn":"তিনি সৃষ্টি করেছেন","root":"خلق","lemma":"خَلَقَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":973,"position":5,"text_uthmani":"٢","transliteration":"","translation_bn":"(২)","root":"—","lemma":"٢","grammar_bn":"মার্কার"}]'::jsonb, 'min sharri mā khalaqa', 'তিনি যা সৃষ্টি করেছেন তার অনিষ্ট হতে,', 'From the evil of that which He created', 'তিনি যা সৃষ্টি করেছেন তার অনিষ্ট হতে,', 'From the evil of that which He created', 'তিনি এই মহাজাগতিক ইকোসিস্টেমে স্বাধীন মেকানিজমে যা কিছু বাউন্ড বা সৃষ্টি (مَا خَلَقَ) করেছেন, তাদের মধ্যকার সম্ভাব্য ড্যামেজ, বিশৃঙ্খলা ও স্বয়ংক্রিয় নেতিবাচক এন্ট্রপির (مِن شَرِّ) ক্ষতিকর প্রভাব থেকে—', NULL, 'সিস্টেমিক ড্যামেজ ও নেতিবাচক এন্ট্রপি শিল্ড', NULL, 'مِن شَرِّ مَا خَلَقَ — ইউনিভার্সাল এনভায়রনমেন্টাল থ্রেট ফিল্টার: আল্লাহর সৃষ্ট সকল ক্ষতিকারক প্রভাব ও ডার্ক এনার্জি থেকে সুরক্ষা।', 'https://everyayah.com/data/Alafasy_128kbps/113002.mp3', now()),
  (113, 3, '', '[{"id":2793,"position":1,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":2794,"position":2,"text_uthmani":"شَرِّ","transliteration":"sharri","translation_bn":"অনিষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":2795,"position":3,"text_uthmani":"غَاسِقٍ","transliteration":"ghāsiqin","translation_bn":"রাতের অন্ধকারের","root":"غسق","lemma":"غَاسِق","grammar_bn":"বিশেষ্য (Noun)"},{"id":2796,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":2797,"position":5,"text_uthmani":"وَقَبَ","transliteration":"waqaba","translation_bn":"তা গভীর হয়","root":"وقب","lemma":"وَقَبَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":2798,"position":6,"text_uthmani":"٣","transliteration":"","translation_bn":"(৩)","root":"—","lemma":"٣","grammar_bn":"মার্কার"}]'::jsonb, 'wamin sharri ghāsiqin idhā waqaba', 'আর অন্ধকার রাতের অনিষ্ট হতে যখন তা আচ্ছন্ন হয়ে যায়।', 'And from the evil of darkness when it settles', 'আর অন্ধকার রাতের অনিষ্ট হতে যখন তা আচ্ছন্ন হয়ে যায়।', 'And from the evil of darkness when it settles', 'এবং স্পেস-টাইমের আলোহীন গভীর ডার্ক ডোমেইন, ডার্ক এনার্জি ও কসমিক ব্ল্যাকআউটের তীব্র নেতিবাচক ফ্রিকোয়েন্সি (غَاسِقٍ) থেকে—যখন তা পুরো লোকাল ইকোসিস্টেমকে আচ্ছন্ন বা ওভারল্যাপ (إِذَا وَقَبَ) করে ফেলে;', NULL, 'ডার্ক এনার্জি ও কসমিক ব্ল্যাকআউট ফিল্টারিং', NULL, 'وَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ — ডার্কনেস ও লেটেন্ট রিস্ক শিল্ড: অন্ধকারের গভীরতায় ছড়িয়ে পড়া ক্ষতিকারক ভেক্টর থেকে নিরাপত্তা।', 'https://everyayah.com/data/Alafasy_128kbps/113003.mp3', now()),
  (113, 4, '', '[{"id":4181,"position":1,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":4182,"position":2,"text_uthmani":"شَرِّ","transliteration":"sharri","translation_bn":"অনিষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":4183,"position":3,"text_uthmani":"ٱلنَّفَّـٰثَـٰتِ","transliteration":"l-nafāthāti","translation_bn":"ফুঁকদানকারীর (রাতের) অনিষ্ট","root":"نفث","lemma":"نَّفَّٰثَٰت","grammar_bn":"শব্দ"},{"id":4184,"position":4,"text_uthmani":"فِى","transliteration":"fī","translation_bn":"মধ্যে","root":"—","lemma":"فِى\r","grammar_bn":"অব্যয় (Preposition)"},{"id":4185,"position":5,"text_uthmani":"ٱلْعُقَدِ","transliteration":"l-ʿuqadi","translation_bn":"গিঁটগুলোর","root":"عقد","lemma":"عُقْدَة","grammar_bn":"শব্দ"},{"id":4186,"position":6,"text_uthmani":"٤","transliteration":"","translation_bn":"(৪)","root":"—","lemma":"٤","grammar_bn":"মার্কার"}]'::jsonb, 'wamin sharri l-nafāthāti fī l-ʿuqadi', 'এবং (জাদু করার উদ্দেশ্যে) গিরায় ফুৎকারকারিণীদের অনিষ্ট হতে,', 'And from the evil of the blowers in knots', 'এবং (জাদু করার উদ্দেশ্যে) গিরায় ফুৎকারকারিণীদের অনিষ্ট হতে,', 'And from the evil of the blowers in knots', 'এবং সুরক্ষিত নেটওয়ার্কের সুনির্দিষ্ট সংযোগস্থল, ডাটা-নোড ও এনক্রিপ্ট করা বাউন্ডিং গিরাগুলোর (فِي الْعُقَدِ) ভেতর মেলিশিয়াস কোড ইনজেকশন বা অদৃশ্য ক্ষতিকর ফ্রিকোয়েন্সি ফুঁ দিয়ে (النَّفَّاثَاتِ) তথ্য বিকৃত ও হাইজ্যাককারী ছদ্মবেশী হ্যাকার শক্তির নেতিবাচক প্রভাব থেকে—', NULL, 'মেলিশিয়াস কোড ইনজেকশন ও নোড এনক্রিপশন হ্যাকিং প্রতিরোধ', NULL, 'وَمِن شَرِّ ٱلنَّفَّـٰثَـٰتِ فِى ٱلْعُقَدِ — সাইকোলজিক্যাল নট-ম্যানিপুলেশন ও টক্সিক স্পেল ফিল্টারিং: মানুষের সম্পর্কের বাঁধন নষ্টকারী বিষাক্ত ফুঁক ও বিভ্রান্তি থেকে সুরক্ষা।', 'https://everyayah.com/data/Alafasy_128kbps/113004.mp3', now()),
  (113, 5, '', '[{"id":5473,"position":1,"text_uthmani":"وَمِن","transliteration":"wamin","translation_bn":"এবং হতে","root":"—","lemma":"مِن\r","grammar_bn":"সংযোজক অব্যয় (Conjunction)"},{"id":5474,"position":2,"text_uthmani":"شَرِّ","transliteration":"sharri","translation_bn":"অনিষ্ট","root":"شرر","lemma":"شَرّ","grammar_bn":"বিশেষ্য (Noun)"},{"id":5475,"position":3,"text_uthmani":"حَاسِدٍ","transliteration":"ḥāsidin","translation_bn":"হিংসুকের","root":"حسد","lemma":"حَاسِد","grammar_bn":"বিশেষ্য (Noun)"},{"id":5476,"position":4,"text_uthmani":"إِذَا","transliteration":"idhā","translation_bn":"যখন","root":"—","lemma":"إِذَا\r","grammar_bn":"কালবাচক (Time)"},{"id":5477,"position":5,"text_uthmani":"حَسَدَ","transliteration":"ḥasada","translation_bn":"সে হিংসা করে\"","root":"حسد","lemma":"حَسَدَ","grammar_bn":"ক্রিয়া (Verb)"},{"id":5478,"position":6,"text_uthmani":"٥","transliteration":"","translation_bn":"(৫)","root":"—","lemma":"٥","grammar_bn":"মার্কার"}]'::jsonb, 'wamin sharri ḥāsidin idhā ḥasada', 'এবং হিংসুকের অনিষ্ট হতে, যখন সে হিংসা করে।', 'And from the evil of an envier when he envies."', 'এবং হিংসুকের অনিষ্ট হতে, যখন সে হিংসা করে।', 'And from the evil of an envier when he envies."', 'এবং তীব্র নেতিবাচক মনস্তাত্ত্বিক এন্ট্রপি-যুক্ত কোনো আউটলায়ার নোড বা হিংসুকের (حَاسِدٍ) তৈরি করা ক্ষতিকর সাইকো-কোয়ান্টাম ভাইব্রেশন থেকে—যখন সে তার ওওএস থেকে সেই ধ্বংসাত্মক ও ক্ষতিকারক তরঙ্গ মেইন গ্রিডে ট্রিগার বা রিলিজ (إِذَا حَسَدَ) করে।', NULL, 'সাইকো-কোয়ান্টাম এন্ট্রপি ও নেতিবাচক বায়ো-ইলেক্ট্রোম্যাগনেটিক ফিল্টার', NULL, 'وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ — এনভি রেডিয়েশন ও নেগেটিভ সাইকিক অ্যাটাক শিল্ড: হিংসুকের ক্ষতিকারক চোখ ও হিংসার আক্রমণ থেকে সার্বিক নিরাপত্তা।', 'https://everyayah.com/data/Alafasy_128kbps/113005.mp3', now())
